// Generated by tools/build_grammar.js from content/french/grammar/*.json.
// Edit the JSON files, not this one.
window.IGCSE_DATA = window.IGCSE_DATA || {};
window.IGCSE_DATA.frenchGrammar = {"topics":[{"id":"nouns-gender","order":1,"area":"Nouns","title":"Gender of nouns","spec":"Nouns: gender","receptive":false,"summary":["Every French noun is masculine or feminine, so learn each one with its article: le livre, la table, un parc, une gare.","With l' and les you cannot hear the gender, so note it when you learn the word: l'hôtel (m), l'école (f).","Endings that are usually masculine: -age, -ment, -eau, -isme, -oir, -ier: le voyage, le bâtiment, le gâteau, le tourisme, le couloir, le quartier.","Endings that are usually feminine: -tion, -sion, -té, -ure, -ie, -ette, -ence, -ée: la natation, la télévision, la santé, la voiture, la boulangerie, la journée.","Learn the common exceptions: la plage, la page, l'image (f), l'eau (f), la peau, le musée, le lycée, le silence.","Days, months, seasons and languages are masculine: le lundi, le printemps, l'été (m), le français.","Some nouns change meaning with gender: le tour (a trip round) / la tour (a tower), le livre (a book) / la livre (a pound), le poste (a job) / la poste (the post office).","Many job nouns have a feminine form: un infirmier → une infirmière, un vendeur → une vendeuse, un acteur → une actrice, un musicien → une musicienne.","Job nouns that already end in -e are the same for both: un journaliste / une journaliste, un dentiste / une dentiste."],"cards":[{"id":"nouns-gender-01","type":"flip","front":"Why should you always learn a French noun with le/la or un/une?","back":"Gender changes the article, the adjectives and the pronouns, and you usually can't work it out from the meaning: le livre (m), la table (f). With l' and les the gender is hidden, so note it: l'hôtel (m), l'école (f)."},{"id":"nouns-gender-02","type":"flip","front":"Name six noun endings that are usually masculine.","back":"-age (le fromage), -ment (le bâtiment), -eau (le bateau), -isme (le tourisme), -oir (le couloir), -ier (le quartier)."},{"id":"nouns-gender-03","type":"flip","front":"Name six noun endings that are usually feminine.","back":"-tion/-sion (la natation, la télévision), -té (la santé), -ure (la voiture), -ie (la boulangerie), -ette (la baguette), -ence (la différence). Most nouns in -ée are feminine too: la journée, l'idée."},{"id":"nouns-gender-04","type":"gap","prompt":"Le matin, mon père va à ___ boulangerie pour acheter des croissants.","hint":"(the)","answers":["la"],"en":"In the morning my father goes to the baker's to buy croissants.","why":"-ie is a feminine ending: la boulangerie, la pharmacie, la géographie."},{"id":"nouns-gender-05","type":"gap","prompt":"Pour mon anniversaire, ma grand-mère a fait ___ gâteau au chocolat.","hint":"(a)","answers":["un"],"en":"For my birthday my grandmother made a chocolate cake.","why":"-eau is a masculine ending: un gâteau, un bateau, un cadeau."},{"id":"nouns-gender-06","type":"flip","front":"Which common nouns break the ending rules?","back":"Feminine although they end in -age: la plage, la page, l'image. Masculine although they end in -ée: le musée, le lycée. Masculine although it ends in -ence: le silence. Feminine although they end in -eau: l'eau, la peau."},{"id":"nouns-gender-07","type":"gap","prompt":"Il y a ___ plage magnifique près de notre hôtel.","hint":"(a)","answers":["une"],"en":"There is a magnificent beach near our hotel.","why":"plage is feminine, an exception to the masculine -age ending (like la page and l'image)."},{"id":"nouns-gender-08","type":"gap","prompt":"Demain, nous allons visiter ___ musée des sciences.","hint":"(the)","answers":["le"],"en":"Tomorrow we are going to visit the science museum.","why":"Most nouns in -ée are feminine, but musée (like lycée) is masculine."},{"id":"nouns-gender-09","type":"flip","front":"What do these pairs mean: le tour / la tour, le livre / la livre, le poste / la poste, le mode / la mode?","back":"le tour = a tour, a trip round; la tour = a tower. le livre = a book; la livre = a pound (money, or 500 g). le poste = a job, a position or a (TV) set; la poste = the post office. le mode = a method, a way; la mode = fashion."},{"id":"nouns-gender-10","type":"gap","prompt":"Du haut de ___ tour, on voit toute la ville.","hint":"(the)","answers":["la"],"en":"From the top of the tower you can see the whole town.","why":"la tour = a tower; le tour = a tour or a trip round something."},{"id":"nouns-gender-11","type":"gap","prompt":"Ce week-end, on va faire ___ tour du lac à vélo.","hint":"(the)","answers":["le"],"en":"This weekend we're going to cycle round the lake.","why":"le tour = a trip round something (faire le tour de); la tour = a tower."},{"id":"nouns-gender-12","type":"gap","prompt":"Pour envoyer ce colis, il faut aller à ___ poste.","hint":"(the)","answers":["la"],"en":"To send this parcel you have to go to the post office.","why":"la poste = the post office; le poste = a job or position."},{"id":"nouns-gender-13","type":"flip","front":"How do job nouns change to refer to a woman?","back":"Often just add -e: un avocat → une avocate. Also -ier/-er → -ière/-ère (infirmière, boulangère), -ien → -ienne (musicienne), -eur → -euse (vendeuse, chanteuse), -teur → -trice (actrice, directrice). Nouns already ending in -e don't change: un/une journaliste, un/une secrétaire."},{"id":"nouns-gender-14","type":"gap","prompt":"Ma tante travaille comme ___ dans un hôpital à Lyon.","base":"infirmier","answers":["infirmière"],"en":"My aunt works as a nurse in a hospital in Lyon.","why":"-ier becomes -ière for a woman, with a grave accent: une infirmière."},{"id":"nouns-gender-15","type":"gap","prompt":"Plus tard, Chloé voudrait devenir ___.","base":"acteur","answers":["actrice"],"en":"Later on, Chloé would like to become an actress.","why":"Most job nouns in -teur become -trice for a woman: un acteur → une actrice. No article is needed after devenir or être with a job."},{"id":"nouns-gender-16","type":"gap","prompt":"Ma sœur rêve de devenir ___ dans un groupe de rock.","base":"chanteur","answers":["chanteuse"],"en":"My sister dreams of becoming a singer in a rock band.","why":"chanteur comes from the verb chanter, so it follows the -eur → -euse pattern (like vendeur → vendeuse), not -teur → -trice."},{"id":"nouns-gender-17","type":"gap","prompt":"Ma mère est ___ pour une chaîne de télévision.","base":"journaliste","answers":["journaliste"],"en":"My mother is a journalist for a TV channel.","why":"Nouns ending in -e (journaliste, dentiste, secrétaire, élève) are the same for both genders; only the article shows it: une journaliste."},{"id":"nouns-gender-18","type":"transform","instruction":"Rewrite the sentence so it is about a female cousin, changing the words in bold.","prompt":"**Mon cousin** est **musicien**.","answers":["Ma cousine est musicienne."],"en":"My (female) cousin is a musician.","why":"cousin → cousine, so mon → ma; -ien doubles the n and adds -e: musicienne."}]},{"id":"nouns-plural","order":2,"area":"Nouns","title":"Singular and plural nouns","spec":"Nouns: singular and plural forms","receptive":false,"summary":["Most nouns add a silent -s in the plural: un livre → des livres, une maison → des maisons. You hear the plural in the article: les, des.","Nouns ending in -s, -x or -z do not change: un bus → des bus, un prix → des prix, un nez → des nez.","Nouns ending in -eau or -eu add -x: un gâteau → des gâteaux, un jeu → des jeux, un neveu → des neveux.","Most nouns ending in -al change to -aux: un animal → des animaux, un journal → des journaux. A few just add -s: des festivals, des carnavals.","A few nouns in -ail change to -aux (un travail → des travaux) and a few in -ou add -x (un genou → des genoux, un bijou → des bijoux). Most others just add -s: des détails, des trous.","Irregular plurals: un œil → des yeux, monsieur → messieurs, madame → mesdames.","Some nouns are plural in French but singular in English: les cheveux (hair), les vacances (holiday), les devoirs (homework), les informations (the news).","In compounds made of an adjective + a noun, both parts take -s: des grands-parents, des petits-enfants. Un week-end → des week-ends.","When the noun is plural, the verb and adjectives change too: les châteaux sont beaux."],"cards":[{"id":"nouns-plural-01","type":"flip","front":"How do most French nouns form the plural, and how can you hear it?","back":"Add -s, which is silent: un vélo → des vélos, une rue → des rues. You hear the plural in the article (les, des) and in liaison before a vowel: in les enfants the s is sounded like a z."},{"id":"nouns-plural-02","type":"flip","front":"What happens to nouns ending in -s, -x or -z in the plural?","back":"Nothing – they stay the same: un bus → des bus, un pays → des pays, un prix → des prix, un nez → des nez."},{"id":"nouns-plural-03","type":"gap","prompt":"Le matin, les ___ sont souvent en retard.","base":"bus","answers":["bus"],"en":"In the morning the buses are often late.","why":"Nouns ending in -s, -x or -z don't change in the plural: un bus → des bus."},{"id":"nouns-plural-04","type":"flip","front":"What is the plural of nouns ending in -eau, -eu and -al?","back":"-eau and -eu add -x: un bateau → des bateaux, un cheveu → des cheveux. -al becomes -aux: un cheval → des chevaux, un hôpital → des hôpitaux. Exceptions that just add -s: un festival → des festivals, un pneu → des pneus."},{"id":"nouns-plural-05","type":"gap","prompt":"À la pâtisserie, j'ai acheté deux ___ au chocolat.","base":"gâteau","answers":["gâteaux"],"en":"At the cake shop I bought two chocolate cakes.","why":"Nouns ending in -eau add -x in the plural: gâteau → gâteaux."},{"id":"nouns-plural-06","type":"gap","prompt":"Mon petit frère passe trop de temps à jouer aux ___ vidéo.","base":"jeu","answers":["jeux"],"en":"My little brother spends too much time playing video games.","why":"Nouns ending in -eu add -x in the plural: jeu → jeux."},{"id":"nouns-plural-07","type":"gap","prompt":"Il y a beaucoup d'___ à la ferme de mon oncle.","base":"animal","answers":["animaux"],"en":"There are lots of animals on my uncle's farm.","why":"Most nouns ending in -al change to -aux in the plural: un animal → des animaux."},{"id":"nouns-plural-08","type":"gap","prompt":"Mon grand-père lit deux ___ chaque matin.","base":"journal","answers":["journaux"],"en":"My grandfather reads two newspapers every morning.","why":"-al becomes -aux in the plural: un journal → des journaux."},{"id":"nouns-plural-09","type":"gap","prompt":"Cet été, nous allons à deux ___ de musique.","base":"festival","answers":["festivals"],"en":"This summer we're going to two music festivals.","why":"festival is an exception to the -al → -aux rule: it just adds -s (like carnaval → carnavals)."},{"id":"nouns-plural-10","type":"flip","front":"Give the plural of: un œil, un travail, un genou, monsieur, madame.","back":"des yeux, des travaux, des genoux, messieurs, mesdames. Like genou, a few -ou nouns take -x (bijou → bijoux, chou → choux); most just add -s (un trou → des trous)."},{"id":"nouns-plural-11","type":"gap","prompt":"Ma grand-mère a les ___ bleus.","base":"œil","answers":["yeux"],"en":"My grandmother has blue eyes.","why":"œil has an irregular plural: yeux. French uses les for physical features: elle a les yeux bleus."},{"id":"nouns-plural-12","type":"gap","prompt":"Il y a des ___ dans ma rue, donc c'est très bruyant.","base":"travail","answers":["travaux"],"en":"There are roadworks in my street, so it's very noisy.","why":"travail → travaux (-ail → -aux). In the plural, les travaux often means building work or roadworks."},{"id":"nouns-plural-13","type":"gap","prompt":"Mon frère est tombé de son vélo et il s'est fait mal aux ___.","base":"genou","answers":["genoux"],"en":"My brother fell off his bike and hurt his knees.","why":"genou is one of the few -ou nouns that add -x: genoux (like bijoux and choux)."},{"id":"nouns-plural-14","type":"flip","front":"Which everyday nouns are plural in French but singular in English?","back":"les cheveux (hair), les vacances (holiday), les devoirs (homework), les informations or les infos (the news). So the verb and adjectives are plural: Mes cheveux sont courts – My hair is short."},{"id":"nouns-plural-15","type":"gap","prompt":"Ma sœur a les ___ longs et bruns.","base":"cheveu","answers":["cheveux"],"en":"My sister has long brown hair.","why":"Hair is plural in French: les cheveux (-eu adds -x). The adjectives are masculine plural too: longs, bruns."},{"id":"nouns-plural-16","type":"gap","prompt":"Le dimanche, je rends visite à mes ___.","base":"grand-parent","answers":["grands-parents"],"en":"On Sundays I visit my grandparents.","why":"In an adjective + noun compound, both parts take -s: grands-parents, petits-enfants."},{"id":"nouns-plural-17","type":"transform","instruction":"Put the words in bold into the plural.","prompt":"J'ai acheté **un cadeau** pour **mon neveu**.","answers":["J'ai acheté des cadeaux pour mes neveux."],"en":"I bought presents for my nephews.","why":"-eau and -eu nouns add -x (cadeaux, neveux); un → des and mon → mes."},{"id":"nouns-plural-18","type":"transform","instruction":"Rewrite the whole sentence in the plural.","prompt":"Le château est très beau.","answers":["Les châteaux sont très beaux."],"en":"The castles are very beautiful.","why":"château → châteaux (-eau + x); the verb becomes sont and beau → beaux."}]},{"id":"articles","order":3,"area":"Articles","title":"Definite, indefinite and partitive articles","spec":"Articles: definite, indefinite and partitive, including use of de after negatives","receptive":false,"summary":["the: le (m), la (f), l' (before a vowel or silent h), les (plural): le parc, la gare, l'hôtel, les magasins.","a / some: un (m), une (f), des (plural): un vélo, une maison, des amis.","some / any (the partitive): du (m), de la (f), de l' (before a vowel), des (plural): du pain, de la viande, de l'eau, des fraises. French needs it even when English leaves 'some' out.","à + le = au and à + les = aux: Je vais au cinéma, aux États-Unis. À la and à l' don't change: à la piscine, à l'école.","de + le = du and de + les = des: près du parc, à côté des magasins. De la and de l' don't change: en face de la gare.","After a negative, un, une, des, du, de la and de l' all become de (d' before a vowel): Je n'ai pas de frère. Il n'y a plus d'eau.","After être the article stays: Ce n'est pas un problème.","After quantities use de: beaucoup de touristes, un kilo de pommes, une bouteille d'eau.","With aimer, adorer, préférer and détester use le, la, l', les, even after a negative: J'aime le chocolat. Je n'aime pas les maths.","In careful written French, des becomes de before a plural adjective that comes before the noun: de belles plages."],"cards":[{"id":"articles-01","type":"flip","front":"What are the French words for 'the' and 'a'?","back":"the: le (m), la (f), l' (before a vowel or silent h), les (plural): le parc, la gare, l'hôtel, les magasins. a: un (m), une (f); plural des (some): un vélo, une maison, des amis."},{"id":"articles-02","type":"flip","front":"What do du, de la, de l' and des mean, and when must you use them?","back":"They mean 'some' or 'any' (the partitive): du pain, de la viande, de l'eau, des fraises. English often leaves 'some' out, but French cannot: Je bois du lait – I drink milk."},{"id":"articles-03","type":"gap","prompt":"Le soir, nous mangeons souvent ___ soupe aux légumes.","hint":"(some)","answers":["de la"],"en":"In the evening we often have vegetable soup.","why":"soupe is feminine and means an unspecified amount, so the partitive is de la – never du with a feminine noun."},{"id":"articles-04","type":"gap","prompt":"Après le match, j'avais soif, alors j'ai bu ___.","hint":"(some water)","answers":["de l'eau"],"en":"After the match I was thirsty, so I drank some water.","why":"eau is feminine but starts with a vowel, so the partitive is de l': de l'eau."},{"id":"articles-05","type":"flip","front":"What happens when à or de meets le or les?","back":"à + le = au, à + les = aux; de + le = du, de + les = des. à la, à l', de la and de l' don't change: Je vais au cinéma, à la piscine, aux magasins. C'est près du parc, à côté de la gare."},{"id":"articles-06","type":"gap","prompt":"Ce soir, je vais ___ cinéma avec mes copains.","hint":"(to the)","answers":["au"],"en":"This evening I'm going to the cinema with my friends.","why":"cinéma is masculine, and à + le always becomes au."},{"id":"articles-07","type":"gap","prompt":"Cet été, mes parents vont ___ États-Unis.","hint":"(to the)","answers":["aux"],"en":"This summer my parents are going to the United States.","why":"les États-Unis is plural, and à + les always becomes aux."},{"id":"articles-08","type":"gap","prompt":"La boulangerie est à côté ___ parc.","hint":"(of the)","answers":["du"],"en":"The baker's is next to the park.","why":"à côté de + le parc: de + le always becomes du."},{"id":"articles-09","type":"flip","front":"What happens to un, une, des, du, de la and de l' after a negative or a quantity?","back":"They all become de (d' before a vowel): J'ai un frère → Je n'ai pas de frère. Il y a de l'eau → Il n'y a pas d'eau. After quantities too: beaucoup de touristes, un kilo de pommes, une bouteille d'eau. But le, la, l', les don't change: Je n'aime pas le café."},{"id":"articles-10","type":"gap","prompt":"Il n'y a pas ___ piscine dans mon village.","hint":"(a)","answers":["de"],"en":"There isn't a swimming pool in my village.","why":"After a negative, un and une become de: pas de piscine."},{"id":"articles-11","type":"gap","prompt":"Mon frère est végétarien : il ne mange jamais ___ viande.","hint":"(any)","answers":["de"],"en":"My brother is a vegetarian: he never eats meat.","why":"After ne ... jamais, the partitive de la becomes de."},{"id":"articles-12","type":"gap","prompt":"Nous ne pouvons pas aller au restaurant : nous n'avons plus ___.","hint":"(any money)","answers":["d'argent"],"en":"We can't go to the restaurant: we haven't got any money left.","why":"After ne ... plus, de l' becomes de, shortened to d' before a vowel: plus d'argent."},{"id":"articles-13","type":"gap","prompt":"En été, il y a beaucoup ___ touristes sur la plage.","hint":"(of)","answers":["de"],"en":"In summer there are lots of tourists on the beach.","why":"After expressions of quantity (beaucoup, peu, assez, trop, un kilo) use de, not des."},{"id":"articles-14","type":"flip","front":"Which article do you use after aimer, adorer, préférer and détester – and with jobs?","back":"The definite article (le, la, l', les), even where English has none: J'aime le chocolat. Je déteste les maths. It stays after a negative: Je n'aime pas le poisson. With a job after être there is no article: Mon père est médecin."},{"id":"articles-15","type":"gap","prompt":"Ma sœur adore ___ musique classique.","hint":"(no article in English)","answers":["la"],"en":"My sister loves classical music.","why":"After verbs of liking and disliking, French uses the definite article: adorer la musique."},{"id":"articles-16","type":"transform","instruction":"Make the sentence negative using ne ... pas.","prompt":"J'ai un chien.","answers":["Je n'ai pas de chien."],"en":"I haven't got a dog.","why":"After a negative, un becomes de."},{"id":"articles-17","type":"transform","instruction":"Make the sentence negative using ne ... pas.","prompt":"J'aime le fromage.","answers":["Je n'aime pas le fromage."],"en":"I don't like cheese.","why":"Only un, une, des and the partitive change to de after a negative; le, la, l', les stay: Je n'aime pas le fromage."},{"id":"articles-18","type":"transform","instruction":"Make the sentence negative using ne ... pas.","prompt":"C'est une bonne idée.","answers":["Ce n'est pas une bonne idée."],"en":"It's not a good idea.","why":"After être the article does not change to de: ce n'est pas une bonne idée."}]},{"id":"adj-agreement","order":4,"area":"Adjectives","title":"Adjective agreement and position","spec":"Adjectives: agreement","receptive":false,"summary":["Adjectives agree with the noun in gender and number: add -e for feminine, -s for plural, -es for feminine plural: un pull noir, une jupe noire, des pulls noirs, des jupes noires.","For a mix of masculine and feminine nouns, use the masculine plural: Mon frère et ma sœur sont grands.","If the adjective already ends in -e, don't add another (une maison moderne), but -é still adds -e (fatiguée). If it ends in -s or -x, the masculine plural doesn't change (des garçons français, des enfants heureux).","Feminine patterns: -eux → -euse (heureuse), -if → -ive (sportive), -er → -ère (chère), -on → -onne (bonne), -el → -elle (naturelle), -ien → -ienne (italienne).","Learn the one-offs: blanc → blanche, long → longue, gentil → gentille, frais → fraîche, gros → grosse.","Adjectives in -al have the masculine plural -aux: des problèmes sociaux (but des questions sociales).","beau, nouveau and vieux become bel, nouvel and vieil before a masculine singular noun starting with a vowel or silent h: un bel hôtel, un nouvel ami, un vieil homme. Feminine: belle, nouvelle, vieille.","marron and orange never change: des chaussures marron, une jupe orange. Two-word colours don't change either: une veste bleu foncé.","Most adjectives go after the noun: une voiture rouge, un film français. BAGS adjectives go before: Beauty (beau, joli), Age (jeune, vieux, nouveau), Good/bad (bon, mauvais), Size (grand, petit, gros): une jolie maison, un bon repas.","A few change meaning with position: mon ancien collège (my former school) / un château ancien (an old castle); un grand homme (a great man) / un homme grand (a tall man)."],"cards":[{"id":"adj-agreement-01","type":"flip","front":"What are the four forms of a regular adjective like noir?","back":"noir (m sg), noire (f sg), noirs (m pl), noires (f pl): un pull noir, une jupe noire, des pulls noirs, des jupes noires. The adjective agrees with the noun it describes."},{"id":"adj-agreement-02","type":"gap","prompt":"Ma meilleure amie est très ___ avec moi.","base":"patient","answers":["patiente"],"en":"My best friend is very patient with me.","why":"amie is feminine singular, so add -e: patiente."},{"id":"adj-agreement-03","type":"flip","front":"When does an adjective NOT add -e or -s?","back":"If it already ends in -e, it adds no extra -e: un livre rouge, une robe rouge (but -é does add -e: fatigué → fatiguée). If it ends in -s or -x, it adds no extra -s in the masculine plural: un pull gris → des pulls gris; un enfant heureux → des enfants heureux."},{"id":"adj-agreement-04","type":"gap","prompt":"Mes petites sœurs sont assez ___.","base":"timide","answers":["timides"],"en":"My little sisters are quite shy.","why":"timide already ends in -e, so the feminine plural just adds -s: timides."},{"id":"adj-agreement-05","type":"flip","front":"How do adjectives ending in -eux, -if, -er, -on, -el and -ien form the feminine?","back":"-eux → -euse (heureux → heureuse), -if → -ive (sportif → sportive), -er → -ère (cher → chère), -on → -onne (bon → bonne), -el → -elle (naturel → naturelle), -ien → -ienne (canadien → canadienne)."},{"id":"adj-agreement-06","type":"gap","prompt":"Ma grand-mère est toujours ___ quand nous lui rendons visite.","base":"heureux","answers":["heureuse"],"en":"My grandmother is always happy when we visit her.","why":"-eux becomes -euse in the feminine: heureuse."},{"id":"adj-agreement-07","type":"gap","prompt":"Ma tante est très ___ : elle fait du vélo tous les jours.","base":"sportif","answers":["sportive"],"en":"My aunt is very sporty: she goes cycling every day.","why":"-if becomes -ive in the feminine: sportive."},{"id":"adj-agreement-08","type":"gap","prompt":"Au marché, les fraises sont trop ___ en ce moment.","base":"cher","answers":["chères"],"en":"At the market, strawberries are too expensive at the moment.","why":"fraises is feminine plural: -er becomes -ère, then add -s: chères."},{"id":"adj-agreement-09","type":"gap","prompt":"Cette tarte aux pommes est vraiment ___ !","base":"bon","answers":["bonne"],"en":"This apple tart is really good!","why":"-on doubles the n and adds -e in the feminine: bonne."},{"id":"adj-agreement-10","type":"gap","prompt":"Ma mère préfère la cuisine ___.","base":"traditionnel","answers":["traditionnelle"],"en":"My mother prefers traditional cooking.","why":"-el doubles the l and adds -e in the feminine: traditionnelle."},{"id":"adj-agreement-11","type":"flip","front":"Give the feminine of blanc, long, gentil, frais and gros – and the masculine plural of social.","back":"blanche, longue, gentille, fraîche, grosse. Adjectives in -al have the masculine plural -aux: social → sociaux (but the feminine plural is regular: sociales)."},{"id":"adj-agreement-12","type":"gap","prompt":"Mes grands-parents habitent dans une maison ___ au bord de la mer.","base":"blanc","answers":["blanche"],"en":"My grandparents live in a white house by the sea.","why":"blanc has an irregular feminine: blanche."},{"id":"adj-agreement-13","type":"gap","prompt":"Au lycée, nous parlons souvent des problèmes ___.","base":"social","answers":["sociaux"],"en":"At school we often talk about social problems.","why":"problèmes is masculine plural, and adjectives in -al change to -aux: sociaux."},{"id":"adj-agreement-14","type":"flip","front":"Give all the forms of beau, nouveau and vieux.","back":"beau, bel, belle, beaux, belles; nouveau, nouvel, nouvelle, nouveaux, nouvelles; vieux, vieil, vieille, vieux, vieilles. bel, nouvel and vieil are used only before a masculine singular noun starting with a vowel or silent h: un bel endroit, un nouvel ordinateur, un vieil ami."},{"id":"adj-agreement-15","type":"gap","prompt":"Nous habitons dans un ___ appartement au centre-ville.","base":"beau","answers":["bel"],"en":"We live in a beautiful flat in the town centre.","why":"Before a masculine singular noun starting with a vowel or silent h, beau becomes bel."},{"id":"adj-agreement-16","type":"gap","prompt":"Le ___ hôtel près de la gare est très moderne.","base":"nouveau","answers":["nouvel"],"en":"The new hotel near the station is very modern.","why":"hôtel is masculine and starts with a silent h, so nouveau becomes nouvel."},{"id":"adj-agreement-17","type":"gap","prompt":"Un ___ homme m'a demandé le chemin de la gare.","base":"vieux","answers":["vieil"],"en":"An old man asked me the way to the station.","why":"homme is masculine and starts with a silent h, so vieux becomes vieil."},{"id":"adj-agreement-18","type":"gap","prompt":"Les plages de cette région sont très ___.","base":"beau","answers":["belles"],"en":"The beaches in this region are very beautiful.","why":"plages is feminine plural: belle + s = belles."},{"id":"adj-agreement-19","type":"flip","front":"Which colour adjectives never change?","back":"marron and orange (they are also nouns – a chestnut, an orange): des yeux marron, des chaussettes orange. Two-word colours don't change either: une robe bleu clair. Other colours agree as normal: une veste verte, des baskets blanches."},{"id":"adj-agreement-20","type":"gap","prompt":"Pour la fête, Julie porte des chaussures ___.","base":"marron","answers":["marron"],"en":"For the party, Julie is wearing brown shoes.","why":"marron (like orange) is invariable: it never adds -e or -s."},{"id":"adj-agreement-21","type":"flip","front":"Most adjectives go after the noun. Which ones go before? (BAGS)","back":"Beauty: beau, joli. Age: jeune, vieux, nouveau. Good/bad: bon, mauvais. Size: grand, petit, gros. E.g. une jolie ville, un vieux pont, un bon film, une grande maison. Colours and nationalities always go after: un vélo bleu, une voiture allemande."},{"id":"adj-agreement-22","type":"transform","instruction":"Add both adjectives in brackets, in the correct form and their usual position (without et).","prompt":"Nous avons une voiture. (petit, rouge)","answers":["Nous avons une petite voiture rouge."],"en":"We have a small red car.","why":"petit is a BAGS (size) adjective, so it goes before the noun; colours go after. Both agree with voiture (f): petite, rouge."},{"id":"adj-agreement-23","type":"transform","instruction":"Rewrite the sentence about Marc et Julie instead of Marc.","prompt":"Marc est sportif et généreux.","answers":["Marc et Julie sont sportifs et généreux."],"en":"Marc and Julie are sporty and generous.","why":"For a mixed group (masculine + feminine) the adjective is masculine plural: sportif → sportifs; généreux already ends in -x, so it doesn't change. The verb becomes sont."},{"id":"adj-agreement-24","type":"flip","front":"How does position change the meaning of ancien, cher and grand?","back":"Before the noun: mon ancien collège (my former school), mes chers amis (my dear friends), un grand homme (a great man). After the noun: une maison ancienne (an old house), un hôtel cher (an expensive hotel), un homme grand (a tall man)."}]},{"id":"adj-comparative","order":5,"area":"Adjectives","title":"Comparative and superlative adjectives","spec":"Adjectives: comparative and superlative: regular, including meilleur, pire","receptive":false,"summary":["plus + adjective + que = more ... than: Le train est plus rapide que le bus.","moins + adjective + que = less ... than; aussi + adjective + que = as ... as: Le vélo est moins cher que la voiture. Je suis aussi grand que mon père.","The adjective still agrees with the noun it describes: Ma sœur est plus sportive que mon frère.","After que use a stressed pronoun: Il est plus âgé que moi. Elle est aussi sympa que toi.","Superlative: le/la/les + plus (or moins) + adjective = the most (or least): C'est la plus grande ville de France.","If the adjective normally goes after the noun, so does the superlative, with the article repeated: le film le plus intéressant, les matières les plus difficiles.","After a superlative, 'in' is de: le meilleur élève de la classe, la plus haute tour du monde.","bon → meilleur (better) → le meilleur (the best), agreeing like any adjective: meilleure, meilleurs, meilleures. Never say plus bon.","mauvais → pire (worse) → le pire (the worst); plus mauvais and le plus mauvais are also correct: La pollution est pire qu'avant."],"cards":[{"id":"adj-comparative-01","type":"flip","front":"How do you say 'more ... than', 'less ... than' and 'as ... as' with an adjective?","back":"plus ... que, moins ... que, aussi ... que: Le train est plus rapide que le car. Le vélo est moins cher que la voiture. Mon frère est aussi grand que mon père."},{"id":"adj-comparative-02","type":"gap","prompt":"En ville, le métro est ___ que le bus.","base":"rapide","hint":"(more ... than)","answers":["plus rapide"],"en":"In town the underground is faster than the bus.","why":"more ... than = plus + adjective + que; rapide agrees with le métro (masculine singular), so it stays rapide."},{"id":"adj-comparative-03","type":"flip","front":"Does the adjective agree in a comparison? Which pronoun follows que?","back":"Yes – it agrees with the noun or pronoun it describes: Ma sœur est plus sportive que mon frère. Les fraises sont moins chères que les cerises. After que use moi, toi, lui, elle, nous, vous, eux, elles: Elle est plus âgée que moi."},{"id":"adj-comparative-04","type":"gap","prompt":"Ma sœur est ___ que mon frère : elle joue au foot et au tennis.","base":"sportif","hint":"(more ... than)","answers":["plus sportive"],"en":"My sister is sportier than my brother: she plays football and tennis.","why":"The adjective agrees with ma sœur (feminine): plus sportive que."},{"id":"adj-comparative-05","type":"gap","prompt":"Au marché, les légumes sont ___ qu'au supermarché.","base":"cher","hint":"(less ... than)","answers":["moins chers"],"en":"At the market, vegetables are less expensive than at the supermarket.","why":"less ... than = moins + adjective + que; chers agrees with légumes (masculine plural)."},{"id":"adj-comparative-06","type":"gap","prompt":"Ma petite sœur est déjà ___ que moi !","base":"grand","hint":"(as ... as)","answers":["aussi grande"],"en":"My little sister is already as tall as me!","why":"as ... as = aussi + adjective + que; grande agrees with ma petite sœur."},{"id":"adj-comparative-07","type":"flip","front":"How do you form the superlative ('the most', 'the least') and where does it go?","back":"le/la/les + plus/moins + adjective, agreeing with the noun. Adjectives that go before the noun keep that position: la plus grande ville. Others go after, with the article repeated: le film le plus drôle, les élèves les moins bavards. 'In' after a superlative is de: la plus belle plage de France."},{"id":"adj-comparative-08","type":"gap","prompt":"Le mont Blanc est ___ montagne de France.","base":"haut","hint":"(the highest)","answers":["la plus haute"],"en":"Mont Blanc is the highest mountain in France.","why":"haut goes before the noun, so the superlative does too: la plus haute (agreeing with montagne). 'In' after a superlative is de."},{"id":"adj-comparative-09","type":"gap","prompt":"C'est le film ___ de l'année.","base":"intéressant","hint":"(the most)","answers":["le plus intéressant"],"en":"It's the most interesting film of the year.","why":"intéressant goes after the noun, so the superlative does too, with the article repeated: le film le plus intéressant."},{"id":"adj-comparative-10","type":"gap","prompt":"Pour moi, les matières ___ sont les sciences.","base":"difficile","hint":"(the most)","answers":["les plus difficiles"],"en":"For me, the most difficult subjects are the sciences.","why":"The superlative follows the noun and agrees with matières (feminine plural): les plus difficiles."},{"id":"adj-comparative-11","type":"flip","front":"How do you say 'better' and 'the best' (adjective)?","back":"bon → meilleur (better), le meilleur (the best). It agrees: meilleur, meilleure, meilleurs, meilleures: ma meilleure amie, les meilleurs joueurs. Never say plus bon. (Don't confuse it with the adverb mieux: Elle chante mieux que moi.)"},{"id":"adj-comparative-12","type":"gap","prompt":"Je trouve que la cuisine italienne est ___ que la cuisine anglaise.","base":"bon","hint":"(better)","answers":["meilleure"],"en":"I think Italian food is better than English food.","why":"better = meilleur, never plus bon; it agrees with cuisine (feminine): meilleure."},{"id":"adj-comparative-13","type":"gap","prompt":"Selon les clients, c'est ___ restaurant de la ville.","base":"bon","hint":"(the best)","answers":["le meilleur"],"en":"According to the customers, it's the best restaurant in town.","why":"the best = le meilleur (masculine singular to match restaurant); 'in' after a superlative is de."},{"id":"adj-comparative-14","type":"flip","front":"How do you say 'worse' and 'the worst'?","back":"mauvais → pire (worse), le/la pire, les pires (the worst). plus mauvais and le plus mauvais are also correct. Le temps est pire qu'hier. C'est la pire journée de ma vie."},{"id":"adj-comparative-15","type":"gap","prompt":"Aujourd'hui, le temps est ___ qu'hier : il pleut et il fait froid.","base":"mauvais","hint":"(worse)","answers":["pire","plus mauvais"],"en":"Today the weather is worse than yesterday: it's raining and it's cold.","why":"worse = pire (plus mauvais is also correct)."},{"id":"adj-comparative-16","type":"gap","prompt":"Le dernier jour, il a plu sans arrêt : c'était ___ journée des vacances.","base":"mauvais","hint":"(the worst)","answers":["la pire","la plus mauvaise"],"en":"On the last day it rained non-stop: it was the worst day of the holiday.","why":"the worst = la pire (or la plus mauvaise), agreeing with journée (feminine)."},{"id":"adj-comparative-17","type":"transform","instruction":"Combine into one sentence using plus ... que and the adjective in brackets.","prompt":"Léa a seize ans. Thomas a quatorze ans. (âgé)","answers":["Léa est plus âgée que Thomas."],"en":"Léa is older than Thomas.","why":"plus + adjective + que; âgée agrees with Léa (feminine)."},{"id":"adj-comparative-18","type":"transform","instruction":"Rewrite using the superlative: 'It's the most interesting town.'","prompt":"C'est une ville intéressante.","answers":["C'est la ville la plus intéressante."],"en":"It's the most interesting town.","why":"intéressante normally follows the noun, so the superlative does too, with the article repeated: la ville la plus intéressante."}]},{"id":"adj-demonstrative","order":6,"area":"Adjectives","title":"Demonstrative adjectives (ce, cet, cette, ces)","spec":"Adjectives: demonstrative (ce, cet, cette, ces)","receptive":false,"summary":["ce + masculine singular noun: ce village, ce garçon.","cet + masculine singular noun starting with a vowel or silent h: cet hôtel, cet ami, cet été.","cette + feminine singular noun, even before a vowel: cette ville, cette école.","ces + any plural noun, masculine or feminine: ces magasins, ces filles, ces hôtels.","They mean 'this' or 'that' (ces = 'these' or 'those'); the context tells you which.","Choose ce or cet by the very next word: ce nouvel hôtel (n is a consonant), cet énorme gâteau (é is a vowel).","Add -ci (here) or -là (there) to the noun to contrast two things: ce pull-ci (this jumper) / ce pull-là (that jumper).","Useful time phrases: ce matin, ce soir, ce week-end, cet été, cet hiver, cette semaine, cette année."],"cards":[{"id":"adj-demonstrative-01","type":"flip","front":"What are the four forms of the demonstrative adjective (this / that / these / those)?","back":"ce (m sg): ce livre; cet (m sg before a vowel or silent h): cet arbre, cet hôtel; cette (f sg): cette rue; ces (all plurals): ces livres, ces rues."},{"id":"adj-demonstrative-02","type":"gap","prompt":"Tu as déjà vu ___ film ?","base":"ce","answers":["ce"],"en":"Have you already seen this film?","why":"film is masculine singular and starts with a consonant: ce."},{"id":"adj-demonstrative-03","type":"gap","prompt":"J'adore ___ chanson !","base":"ce","answers":["cette"],"en":"I love this song!","why":"chanson is feminine singular: cette."},{"id":"adj-demonstrative-04","type":"gap","prompt":"___ chaussures sont très confortables.","base":"ce","answers":["Ces"],"en":"These shoes are very comfortable.","why":"chaussures is plural: ces is used for all plurals, masculine or feminine."},{"id":"adj-demonstrative-05","type":"flip","front":"When do you use cet rather than ce?","back":"Before a masculine singular word starting with a vowel or silent h, so the sounds run together: cet ordinateur, cet homme, cet été, cet hiver. Feminine nouns always take cette, even before a vowel: cette école, cette amie."},{"id":"adj-demonstrative-06","type":"gap","prompt":"___ hôtel est trop cher pour nous.","base":"ce","answers":["Cet"],"en":"This hotel is too expensive for us.","why":"hôtel is masculine singular and starts with a silent h: cet."},{"id":"adj-demonstrative-07","type":"gap","prompt":"Nous allons faire du ski ___ hiver.","base":"ce","answers":["cet"],"en":"We're going skiing this winter.","why":"hiver is masculine and starts with a silent h: cet hiver (like cet été)."},{"id":"adj-demonstrative-08","type":"gap","prompt":"___ année, je passe mes examens.","base":"ce","answers":["Cette"],"en":"This year I'm taking my exams.","why":"année is feminine, so cette – never cet, even though it starts with a vowel."},{"id":"adj-demonstrative-09","type":"flip","front":"Ce or cet? ___ nouvel appartement / ___ énorme gâteau","back":"Look at the very next word, not the noun: ce nouvel appartement (nouvel starts with a consonant), cet énorme gâteau (énorme starts with a vowel)."},{"id":"adj-demonstrative-10","type":"gap","prompt":"Regarde ___ énorme gâteau !","base":"ce","answers":["cet"],"en":"Look at this enormous cake!","why":"gâteau is masculine and the next word, énorme, starts with a vowel: cet."},{"id":"adj-demonstrative-11","type":"gap","prompt":"Regarde ___ nouvel appartement !","base":"ce","answers":["ce"],"en":"Look at this new flat!","why":"The next word, nouvel, starts with a consonant, so ce – even though appartement starts with a vowel."},{"id":"adj-demonstrative-12","type":"flip","front":"How do you contrast 'this one (here)' with 'that one (there)'?","back":"Add -ci or -là to the noun with a hyphen: Je prends ce pull-ci, pas ce pull-là (this jumper, not that one). Cette robe-ci est plus chère que cette robe-là."},{"id":"adj-demonstrative-13","type":"gap","prompt":"Tu connais ___ acteurs ?","base":"ce","answers":["ces"],"en":"Do you know these actors?","why":"acteurs is plural, so ces – there is no special form before a vowel in the plural (never 'cets' or 'cettes')."},{"id":"adj-demonstrative-14","type":"flip","front":"How do you say this morning, this evening, this week, this summer and this year?","back":"ce matin, ce soir, cette semaine, cet été, cette année. Also: ce week-end, cet hiver, cet après-midi."},{"id":"adj-demonstrative-15","type":"transform","instruction":"Replace the article in bold with the correct form of ce.","prompt":"**L'**ordinateur est très rapide.","answers":["Cet ordinateur est très rapide."],"en":"This computer is very fast.","why":"ordinateur is masculine singular and starts with a vowel: cet."},{"id":"adj-demonstrative-16","type":"transform","instruction":"Replace the article in bold with the correct form of ce.","prompt":"**L'**école est très grande.","answers":["Cette école est très grande."],"en":"This school is very big.","why":"école is feminine, so cette. L' hides the gender – the adjective grande shows it."}]},{"id":"adj-indefinite","order":7,"area":"Adjectives","title":"Indefinite adjectives (chaque, quelque, tout…)","spec":"Adjectives: indefinite (e.g. chaque, quelque)","receptive":false,"summary":["chaque (each, every) never changes and is followed by a singular noun with no article: chaque matin, chaque fille.","quelques (a few, some) is plural and goes before the noun: quelques amis, quelques idées.","plusieurs (several) never changes and is always plural: plusieurs fois, plusieurs villes.","tout agrees with the noun and is followed by the article: tout le temps, toute la journée, tous les jours, toutes les semaines.","tous les / toutes les + time word = every: tous les samedis = chaque samedi.","autre agrees in number; des becomes d' in front of it: un autre jour, d'autres pays.","même before a noun means same and agrees in number: la même école, les mêmes vêtements.","certains / certaines (some, certain) agree with a plural noun: certains profs, certaines matières.","tout le monde means everyone and takes a singular verb: tout le monde est là."],"cards":[{"id":"adj-indefinite-01","type":"flip","front":"What does chaque mean, and does it ever change form?","back":"chaque = each / every. It never changes and is always followed by a singular noun with no article: chaque jour, chaque semaine, chaque élève."},{"id":"adj-indefinite-02","type":"flip","front":"Give the four forms of tout + the definite article.","back":"tout le (masc. sing.), toute la (fem. sing.), tous les (masc. plural), toutes les (fem. plural): tout le week-end, toute la classe, tous les garçons, toutes les filles."},{"id":"adj-indefinite-03","type":"gap","prompt":"Ma mère travaille ___ la journée.","base":"tout","answers":["toute"],"en":"My mother works all day.","why":"journée is feminine singular, so tout becomes toute."},{"id":"adj-indefinite-04","type":"gap","prompt":"Nous avons cours de français ___ les jours.","base":"tout","answers":["tous"],"en":"We have French lessons every day.","why":"jours is masculine plural, so tout becomes tous; tous les jours = every day."},{"id":"adj-indefinite-05","type":"gap","prompt":"Dans ma classe, ___ les filles aiment la natation.","base":"tout","answers":["toutes"],"en":"In my class, all the girls like swimming.","why":"filles is feminine plural, so tout becomes toutes."},{"id":"adj-indefinite-06","type":"gap","prompt":"Mon petit frère a mangé ___ le gâteau !","base":"tout","answers":["tout"],"en":"My little brother ate the whole cake!","why":"gâteau is masculine singular, so tout stays as it is: tout le gâteau = the whole cake."},{"id":"adj-indefinite-07","type":"transform","instruction":"Rewrite the sentence using chaque instead of the words in bold.","prompt":"Je fais du sport **tous les matins**.","answers":["Je fais du sport chaque matin.","Chaque matin, je fais du sport."],"en":"I do sport every morning.","why":"chaque is followed by a singular noun with no article: tous les matins = chaque matin."},{"id":"adj-indefinite-08","type":"flip","front":"quelques or plusieurs: what is the difference?","back":"quelques = a few / some (a small number): quelques minutes. plusieurs = several (more than one; it never changes): plusieurs semaines. Both go before a plural noun with no article."},{"id":"adj-indefinite-09","type":"gap","prompt":"J'ai acheté ___ cartes postales pour mes grands-parents.","base":"quelque","answers":["quelques"],"en":"I bought a few postcards for my grandparents.","why":"Before a plural noun quelque takes an -s: quelques cartes = a few cards."},{"id":"adj-indefinite-10","type":"gap","prompt":"Nous sommes allés à Paris ___ fois.","hint":"(several)","answers":["plusieurs"],"en":"We have been to Paris several times.","why":"plusieurs (several) is always plural and never changes form."},{"id":"adj-indefinite-11","type":"flip","front":"Why do you say d'autres pays and not des autres pays for 'other countries'?","back":"When an adjective comes before a plural noun, des becomes de (d' before a vowel): d'autres pays, d'autres idées. Singular: un autre jour, une autre fois."},{"id":"adj-indefinite-12","type":"gap","prompt":"L'année prochaine, je voudrais visiter d'___ pays.","base":"autre","answers":["autres"],"en":"Next year I would like to visit other countries.","why":"autre agrees in number with the plural noun pays, so it adds -s; des becomes d' before it."},{"id":"adj-indefinite-13","type":"transform","instruction":"Make the words in bold plural.","prompt":"J'ai **un autre stylo**.","answers":["J'ai d'autres stylos."],"en":"I have other pens.","why":"The plural of un is normally des, but des becomes d' before the adjective autres; autre and stylo both add -s."},{"id":"adj-indefinite-14","type":"flip","front":"What does même mean before a noun, and how does it agree?","back":"Before a noun même = same. It agrees in number only (no feminine change, as it already ends in -e): le même prof, la même équipe, les mêmes idées."},{"id":"adj-indefinite-15","type":"gap","prompt":"Mes amis et moi portons les ___ baskets.","base":"même","answers":["mêmes"],"en":"My friends and I wear the same trainers.","why":"même agrees in number with the plural noun baskets, so it adds -s: les mêmes baskets."},{"id":"adj-indefinite-16","type":"gap","prompt":"Pour moi, ___ matières sont plus faciles que d'autres.","base":"certain","answers":["certaines"],"en":"For me, some subjects are easier than others.","why":"certain agrees with matières, which is feminine plural: certaines."},{"id":"adj-indefinite-17","type":"flip","front":"What does tout le monde mean, and is the verb singular or plural?","back":"tout le monde = everyone / everybody. It takes a singular verb: Tout le monde est content. Tout le monde aime les vacances."},{"id":"adj-indefinite-18","type":"transform","instruction":"Rewrite the sentence using the correct form of tout + les instead of chaque. Change the verb too.","prompt":"**Chaque maison** a un jardin.","answers":["Toutes les maisons ont un jardin."],"en":"All the houses have a garden.","why":"maison is feminine, so chaque maison becomes toutes les maisons; the subject is now plural, so a becomes ont."}]},{"id":"adj-possessive","order":8,"area":"Adjectives","title":"Possessive adjectives","spec":"Adjectives: possessive","receptive":false,"summary":["Possessive adjectives agree with the thing owned, not with the owner: mon frère, ma sœur, mes parents.","my: mon, ma, mes; your (tu): ton, ta, tes; his/her/its: son, sa, ses.","our: notre, nos; your (vous): votre, vos; their: leur, leurs.","Before a feminine singular word starting with a vowel or silent h, use mon, ton, son: mon amie, ton école, son histoire.","If the next word starts with a consonant, go back to ma, ta, sa: ma meilleure amie.","son, sa and ses can mean his, her or its; only the noun owned decides the form: Paul aime sa mère (his), Julie aime son père (her).","leur goes with one thing, leurs with more than one: leur maison, leurs enfants.","With parts of the body French usually uses le, la, les instead: J'ai mal à la tête. Je me lave les mains."],"cards":[{"id":"adj-possessive-01","type":"flip","front":"Give all the possessive adjectives (my, your, his/her, our, your, their).","back":"my: mon / ma / mes; your (tu): ton / ta / tes; his, her, its: son / sa / ses; our: notre / nos; your (vous): votre / vos; their: leur / leurs. (Order: masculine singular / feminine singular / plural; notre, votre and leur are the same for both genders.)"},{"id":"adj-possessive-02","type":"gap","prompt":"J'habite avec ___ mère et mon beau-père.","base":"mon","answers":["ma"],"en":"I live with my mother and my stepfather.","why":"mère is feminine singular and starts with a consonant: ma."},{"id":"adj-possessive-03","type":"gap","prompt":"___ parents sont assez stricts.","base":"mon","answers":["Mes"],"en":"My parents are quite strict.","why":"parents is plural: mes."},{"id":"adj-possessive-04","type":"gap","prompt":"Tu as fini ___ devoirs ?","base":"ton","answers":["tes"],"en":"Have you finished your homework?","why":"devoirs is plural (homework is plural in French): tes."},{"id":"adj-possessive-05","type":"flip","front":"Why do you say mon amie and ton école, even though amie and école are feminine?","back":"Before a feminine singular word starting with a vowel or silent h, ma/ta/sa become mon/ton/son so the vowels don't clash: mon amie, ton école, son histoire. If an adjective starting with a consonant comes first, go back to ma/ta/sa: ma meilleure amie."},{"id":"adj-possessive-06","type":"gap","prompt":"Je vais au parc avec ___ amie Sarah.","base":"mon","answers":["mon"],"en":"I'm going to the park with my friend Sarah.","why":"amie is feminine but starts with a vowel, so ma becomes mon."},{"id":"adj-possessive-07","type":"gap","prompt":"Samedi, je vais en ville avec ___ meilleure amie.","base":"mon","answers":["ma"],"en":"On Saturday I'm going into town with my best friend.","why":"The next word, meilleure, starts with a consonant, so the feminine ma is used."},{"id":"adj-possessive-08","type":"flip","front":"Does son / sa / ses mean 'his' or 'her'?","back":"Either – it agrees with the thing owned, not with the owner. Paul range sa chambre (his room). Julie adore son frère (her brother). Context tells you whether it means his or her."},{"id":"adj-possessive-09","type":"gap","prompt":"Paul range ___ chambre.","base":"son","hint":"(his)","answers":["sa"],"en":"Paul is tidying his bedroom.","why":"chambre is feminine, so sa – even though Paul is male."},{"id":"adj-possessive-10","type":"gap","prompt":"Julie adore ___ petit frère.","base":"son","hint":"(her)","answers":["son"],"en":"Julie loves her little brother.","why":"frère is masculine, so son – even though Julie is female."},{"id":"adj-possessive-11","type":"gap","prompt":"Cet été, nous passons ___ vacances en Italie.","base":"notre","answers":["nos"],"en":"This summer we're spending our holiday in Italy.","why":"vacances is plural, so nos."},{"id":"adj-possessive-12","type":"flip","front":"leur or leurs? And what do you use with parts of the body?","back":"leur + one thing (leur chien), leurs + more than one (leurs enfants). Don't confuse it with the pronoun leur (to them), which never takes -s. With parts of the body use le, la, les: Il se brosse les dents. J'ai mal au dos."},{"id":"adj-possessive-13","type":"gap","prompt":"Les enfants promènent ___ chien tous les soirs.","base":"leur","answers":["leur"],"en":"The children walk their dog every evening.","why":"They have one dog, so leur (singular), even though there are several owners."},{"id":"adj-possessive-14","type":"gap","prompt":"Mes cousins ont vendu ___ vélos.","base":"leur","answers":["leurs"],"en":"My cousins sold their bikes.","why":"vélos is plural, so leurs."},{"id":"adj-possessive-15","type":"gap","prompt":"Monsieur, vous avez oublié ___ clés !","base":"votre","answers":["vos"],"en":"Sir, you've forgotten your keys!","why":"clés is plural, so vos."},{"id":"adj-possessive-16","type":"transform","instruction":"Rewrite using a possessive adjective instead of de + the owner.","prompt":"C'est le livre de Marie.","answers":["C'est son livre."],"en":"It's her book.","why":"livre is masculine, so son – even though Marie is female."},{"id":"adj-possessive-17","type":"transform","instruction":"Rewrite using a possessive adjective instead of de + the owner.","prompt":"C'est la maison de mes grands-parents.","answers":["C'est leur maison."],"en":"It's their house.","why":"One house belonging to several people: leur."},{"id":"adj-possessive-18","type":"transform","instruction":"Rewrite using a possessive adjective instead of de + the owner.","prompt":"Ce sont les chaussures de Thomas.","answers":["Ce sont ses chaussures."],"en":"They're his shoes.","why":"chaussures is plural, so ses."}]},{"id":"adj-interrogative","order":9,"area":"Adjectives","title":"Interrogative adjective quel","spec":"Adjectives: interrogative (e.g. quel, quelle, quels, quelles)","receptive":false,"summary":["quel means 'which' or 'what' and agrees with its noun: quel (m sg), quelle (f sg), quels (m pl), quelles (f pl).","All four forms sound the same, so the spelling depends on the noun: Quel sport ? Quelle matière ? Quels films ? Quelles chaussures ?","quel can go straight before a noun: Quel temps fait-il ? Quelle heure est-il ?","With être, quel agrees with the noun after the verb: Quelle est ta couleur préférée ? Quels sont tes passe-temps ?","quel can follow a preposition: À quelle heure ? De quelle couleur ? Dans quel pays ?","In exclamations, quel + noun means 'What a ...!' or 'What ...!', with no un or une: Quelle belle vue ! Quel dommage !","quel always goes with a noun; for 'what' with just a verb use qu'est-ce que: Qu'est-ce que tu fais ?"],"cards":[{"id":"adj-interrogative-01","type":"flip","front":"What are the four forms of quel, and why do they matter if they sound the same?","back":"quel (m sg), quelle (f sg), quels (m pl), quelles (f pl). They are all pronounced the same, but in writing quel must agree with its noun: Quel film ? Quelle émission ? Quels jeux ? Quelles couleurs ?"},{"id":"adj-interrogative-02","type":"gap","prompt":"___ sport préfères-tu ?","base":"quel","answers":["Quel"],"en":"Which sport do you prefer?","why":"sport is masculine singular: quel."},{"id":"adj-interrogative-03","type":"gap","prompt":"___ matière est-ce que tu détestes ?","base":"quel","answers":["Quelle"],"en":"Which subject do you hate?","why":"matière is feminine singular: quelle."},{"id":"adj-interrogative-04","type":"gap","prompt":"___ films aimes-tu regarder ?","base":"quel","answers":["Quels"],"en":"What films do you like watching?","why":"films is masculine plural: quels."},{"id":"adj-interrogative-05","type":"gap","prompt":"___ chaussures vas-tu acheter pour la fête ?","base":"quel","answers":["Quelles"],"en":"Which shoes are you going to buy for the party?","why":"chaussures is feminine plural: quelles."},{"id":"adj-interrogative-06","type":"gap","prompt":"Dans ___ pays est-ce que ton père est né ?","base":"quel","answers":["quel"],"en":"Which country was your father born in?","why":"pays is masculine and singular here (a person is born in one country) – the -s is part of the word and doesn't make it plural: quel."},{"id":"adj-interrogative-07","type":"flip","front":"How does quel agree in a question with être, such as 'What is your favourite colour?'","back":"quel agrees with the noun after être: Quelle est ta couleur préférée ? (couleur, f sg). Quels sont tes passe-temps ? (m pl). Quelles sont tes matières préférées ? (f pl)."},{"id":"adj-interrogative-08","type":"gap","prompt":"___ est ta couleur préférée ?","base":"quel","answers":["Quelle"],"en":"What is your favourite colour?","why":"quel agrees with the noun after être: couleur is feminine singular, so quelle."},{"id":"adj-interrogative-09","type":"gap","prompt":"___ sont tes passe-temps ?","base":"quel","answers":["Quels"],"en":"What are your hobbies?","why":"passe-temps is masculine, and sont shows it is plural here: quels."},{"id":"adj-interrogative-10","type":"gap","prompt":"___ sont les avantages d'habiter à la campagne ?","base":"quel","answers":["Quels"],"en":"What are the advantages of living in the countryside?","why":"avantages is masculine plural: quels."},{"id":"adj-interrogative-11","type":"gap","prompt":"À ___ heure commence le film ?","base":"quel","answers":["quelle"],"en":"What time does the film start?","why":"heure is feminine singular: à quelle heure."},{"id":"adj-interrogative-12","type":"flip","front":"How do you use quel in exclamations?","back":"quel + noun (+ adjective) means 'What a ...!' or 'What ...!', with no un or une: Quel dommage ! (What a pity!) Quelle belle journée ! (What a lovely day!) Quels beaux paysages ! (What beautiful scenery!)"},{"id":"adj-interrogative-13","type":"gap","prompt":"___ belle vue depuis ta chambre !","base":"quel","answers":["Quelle"],"en":"What a beautiful view from your bedroom!","why":"Exclamatory quel agrees with vue (feminine singular) and needs no article: Quelle belle vue !"},{"id":"adj-interrogative-14","type":"flip","front":"quel or qu'est-ce que? How do you say 'What are you doing?' and 'What film are you watching?'","back":"Qu'est-ce que tu fais ? – 'what' with just a verb. Quel film regardes-tu ? – 'what' or 'which' + a noun. quel always goes with a noun (or with être + a noun)."},{"id":"adj-interrogative-15","type":"transform","instruction":"Write the question this sentence answers, using quel + the noun in brackets and the tu form of préférer.","prompt":"Je préfère les maths. (matière)","answers":["Quelle matière préfères-tu ?","Quelle matière est-ce que tu préfères ?","Tu préfères quelle matière ?","Quelle matière tu préfères ?"],"en":"Which subject do you prefer?","why":"matière is feminine singular, so quelle; then invert (préfères-tu) or use est-ce que; in informal French you can also keep the normal word order (Quelle matière tu préfères ? / Tu préfères quelle matière ?)."},{"id":"adj-interrogative-16","type":"transform","instruction":"Rewrite as an exclamation beginning with quel, keeping the adjective after the noun.","prompt":"Le temps est horrible.","answers":["Quel temps horrible !"],"en":"What horrible weather!","why":"Exclamatory quel agrees with temps (masculine singular) and takes no article."}]},{"id":"adv-formation-comparison","order":10,"area":"Adverbs","title":"Forming adverbs; comparative and superlative (mieux, le mieux)","spec":"Adverbs: comparative and superlative: regular, including mieux, le mieux","receptive":false,"summary":["Most adverbs are the feminine adjective + -ment: lent → lente → lentement; heureux → heureuse → heureusement.","If the masculine adjective ends in a vowel, add -ment to the masculine: vrai → vraiment, poli → poliment, facile → facilement.","Adjectives in -ant change to -amment and those in -ent to -emment (both said 'amment'): courant → couramment, évident → évidemment.","Learn the irregular ones: bon → bien, mauvais → mal, rapide → vite (or rapidement), gentil → gentiment.","Comparative: plus / moins / aussi + adverb + que: Il court plus vite que moi.","Superlative: le plus / le moins + adverb, always with le: C'est Léa qui nage le plus vite.","bien → mieux (better) → le mieux (best): Je chante mieux que mon frère.","meilleur is the adjective (with a noun, agrees); mieux is the adverb (with a verb, never changes): une meilleure note, elle joue mieux."],"cards":[{"id":"adv-formation-comparison-01","type":"flip","front":"How are most French adverbs formed from adjectives?","back":"Take the feminine form of the adjective and add -ment: lent → lente → lentement (slowly); doux → douce → doucement (gently); heureux → heureuse → heureusement (luckily)."},{"id":"adv-formation-comparison-02","type":"gap","prompt":"Mon grand-père marche très ___.","base":"lent","answers":["lentement"],"en":"My grandfather walks very slowly.","why":"Feminine adjective lente + -ment gives the adverb lentement."},{"id":"adv-formation-comparison-03","type":"gap","prompt":"___, il ne pleut pas aujourd'hui !","base":"heureux","answers":["Heureusement"],"en":"Luckily, it isn't raining today!","why":"The feminine of heureux is heureuse; add -ment: heureusement."},{"id":"adv-formation-comparison-04","type":"flip","front":"When do you add -ment to the masculine adjective instead of the feminine?","back":"When the masculine adjective already ends in a vowel: vrai → vraiment, poli → poliment, absolu → absolument, facile → facilement, rapide → rapidement."},{"id":"adv-formation-comparison-05","type":"gap","prompt":"Après le match, je suis ___ fatigué.","base":"vrai","answers":["vraiment"],"en":"After the match, I'm really tired.","why":"vrai ends in a vowel, so -ment is added straight to the masculine: vraiment."},{"id":"adv-formation-comparison-06","type":"flip","front":"How do adjectives ending in -ant and -ent form their adverbs?","back":"-ant → -amment and -ent → -emment, both pronounced 'amment': courant → couramment, évident → évidemment, récent → récemment, patient → patiemment. Watch out: lent → lentement."},{"id":"adv-formation-comparison-07","type":"gap","prompt":"Ma correspondante parle anglais ___.","base":"courant","answers":["couramment"],"en":"My penfriend speaks English fluently.","why":"Adjectives ending in -ant form their adverb with -amment: courant → couramment."},{"id":"adv-formation-comparison-08","type":"transform","instruction":"Replace the words in bold with one adverb.","prompt":"Le prof répond **avec patience**.","answers":["Le prof répond patiemment."],"en":"The teacher answers patiently.","why":"patient ends in -ent, so the adverb ends in -emment: patiemment."},{"id":"adv-formation-comparison-09","type":"flip","front":"What are the adverbs from bon, mauvais and rapide?","back":"bon → bien (well), mauvais → mal (badly), rapide → vite or rapidement (quickly). Also gentil → gentiment (kindly)."},{"id":"adv-formation-comparison-10","type":"gap","prompt":"Hier soir, j'ai ___ dormi à cause du bruit.","base":"mauvais","answers":["mal"],"en":"Last night I slept badly because of the noise.","why":"The adverb from mauvais is irregular: mal. Short adverbs go between avoir and the past participle."},{"id":"adv-formation-comparison-11","type":"flip","front":"How do you compare adverbs, and which article does the superlative use?","back":"plus / moins / aussi + adverb + que: Il conduit plus lentement que moi. Superlative: le plus / le moins + adverb, always le, whatever the subject: Ma sœur court le plus vite."},{"id":"adv-formation-comparison-12","type":"gap","prompt":"Mon père conduit ___ que ma mère.","base":"prudent","hint":"(more carefully)","answers":["plus prudemment"],"en":"My father drives more carefully than my mother.","why":"Comparative of an adverb: plus + adverb + que; prudent → prudemment (-ent → -emment)."},{"id":"adv-formation-comparison-13","type":"gap","prompt":"Léa court ___ de toute l'équipe.","base":"vite","hint":"(the fastest)","answers":["le plus vite"],"en":"Léa runs the fastest in the whole team.","why":"Superlative of an adverb: le plus + adverb. It is always le, even with a female subject."},{"id":"adv-formation-comparison-14","type":"gap","prompt":"Mon copain nage ___ que moi.","base":"bien","hint":"(as well)","answers":["aussi bien"],"en":"My mate swims as well as me.","why":"Comparison of equality: aussi + adverb + que. bien itself does not change here."},{"id":"adv-formation-comparison-15","type":"flip","front":"meilleur or mieux: how do you choose?","back":"meilleur is an adjective: it describes a noun and agrees (un meilleur film, une meilleure note). mieux is an adverb: it describes a verb and never changes (elle chante mieux). bien → mieux → le mieux."},{"id":"adv-formation-comparison-16","type":"gap","prompt":"Depuis mon séjour en France, je parle ___ qu'avant.","base":"bien","hint":"(better)","answers":["mieux"],"en":"Since my stay in France, I speak better than before.","why":"'Better' describes the verb parler, so use the adverb mieux (never plus bien)."},{"id":"adv-formation-comparison-17","type":"gap","prompt":"Dans ma famille, c'est ma mère qui cuisine ___.","base":"bien","hint":"(the best)","answers":["le mieux"],"en":"In my family, it's my mother who cooks the best.","why":"The superlative of the adverb bien is le mieux; it stays le even though the subject is feminine."},{"id":"adv-formation-comparison-18","type":"gap","prompt":"Ma sœur a eu une ___ note que moi en maths.","base":"bon","hint":"(better)","answers":["meilleure"],"en":"My sister got a better mark than me in maths.","why":"'Better' describes the noun note, so use the adjective meilleur, which agrees with the feminine noun: meilleure."},{"id":"adv-formation-comparison-19","type":"gap","prompt":"Cette année, je fais du sport ___ que l'année dernière.","base":"régulier","hint":"(less regularly)","answers":["moins régulièrement"],"en":"This year I do sport less regularly than last year.","why":"Comparative of inferiority: moins + adverb + que. régulier → feminine régulière → régulièrement (keep the grave accent)."}]},{"id":"adv-question-time-place","order":11,"area":"Adverbs","title":"Question adverbs, adverbs of time and place, adverbial phrases","spec":"Adverbs: interrogative (e.g. comment, quand); adverbs of time and place (e.g. aujourd'hui, demain, ici, là-bas); common adverbial phrases","receptive":false,"summary":["Question words: comment (how), quand (when), où (where), pourquoi (why), combien (how much / how many): Où habites-tu ?","combien de + noun with no article: Combien de frères as-tu ?","Three ways to ask with a question word: Où vas-tu ? / Où est-ce que tu vas ? / Tu vas où ?","où (where) has a grave accent; ou without an accent means or.","Time adverbs: hier, aujourd'hui, demain, déjà, bientôt, souvent, toujours (always or still), maintenant: Demain, je vais à Paris.","Place adverbs: ici (here), là (there), là-bas (over there), partout (everywhere): Il y a des fleurs partout.","Short adverbs like déjà, souvent, toujours go between avoir/être and the past participle: J'ai déjà mangé.","Useful adverbial phrases: de temps en temps (from time to time), tout de suite (straight away), d'habitude (usually), en ce moment (at the moment), à l'avenir (in the future)."],"cards":[{"id":"adv-question-time-place-01","type":"flip","front":"Give the French for: how, when, where, why, how much / how many.","back":"comment, quand, où, pourquoi, combien. Comment vas-tu ? Quand pars-tu ? Où habites-tu ? Pourquoi ris-tu ? Combien ça coûte ?"},{"id":"adv-question-time-place-02","type":"gap","prompt":"___ t'appelles-tu ?","hint":"(how)","answers":["Comment"],"en":"What's your name?","why":"comment = how; Comment t'appelles-tu ? literally means 'How do you call yourself?'"},{"id":"adv-question-time-place-03","type":"gap","prompt":"___ habites-tu ? — J'habite à Lyon.","hint":"(where)","answers":["Où"],"en":"Where do you live? — I live in Lyon.","why":"où = where and needs its grave accent; ou without an accent means or."},{"id":"adv-question-time-place-04","type":"gap","prompt":"___ es-tu en retard ? — Parce que j'ai raté le bus.","hint":"(why)","answers":["Pourquoi"],"en":"Why are you late? — Because I missed the bus.","why":"pourquoi = why; the answer usually starts with parce que (because)."},{"id":"adv-question-time-place-05","type":"gap","prompt":"___ est-ce que tu pars en vacances ? — Le 3 août.","hint":"(when)","answers":["Quand"],"en":"When are you going on holiday? — On 3rd August.","why":"quand = when; it can be followed by est-ce que or by inversion (Quand pars-tu ?)."},{"id":"adv-question-time-place-06","type":"flip","front":"How do you use combien, and what are the three ways to ask a question with a question word?","back":"combien de + noun, no article: Combien de cousins as-tu ? Three ways: Où vas-tu ? (inversion) / Où est-ce que tu vas ? / Tu vas où ? (informal)."},{"id":"adv-question-time-place-07","type":"gap","prompt":"___ de frères et sœurs as-tu ?","hint":"(how many)","answers":["Combien"],"en":"How many brothers and sisters have you got?","why":"combien de + noun = how many; there is no article after de."},{"id":"adv-question-time-place-08","type":"transform","instruction":"Write the question that this sentence answers, using a question word for the words in bold. Use tu.","prompt":"Je vais **au stade**.","answers":["Où vas-tu ?","Où est-ce que tu vas ?","Tu vas où ?"],"en":"Where are you going?","why":"The words in bold give a place, so the question word is où; it can go with inversion, est-ce que, or at the end in speech."},{"id":"adv-question-time-place-09","type":"transform","instruction":"Write the question that this sentence answers, using a question word for the words in bold.","prompt":"Elle a **deux** chats.","answers":["Combien de chats a-t-elle ?","Combien a-t-elle de chats ?","Combien de chats est-ce qu'elle a ?","Combien est-ce qu'elle a de chats ?","Elle a combien de chats ?"],"en":"How many cats has she got?","why":"A number is asked for with combien de + noun; inversion needs -t- between a and elle: a-t-elle."},{"id":"adv-question-time-place-10","type":"flip","front":"Give the French for: yesterday, today, tomorrow, already, soon, often, always/still, here, there, over there, everywhere.","back":"hier, aujourd'hui, demain, déjà, bientôt, souvent, toujours, ici, là, là-bas, partout. Note toujours also means still: Il pleut toujours = It's still raining."},{"id":"adv-question-time-place-11","type":"gap","prompt":"___, je suis allé au marché avec ma mère.","hint":"(yesterday)","answers":["Hier"],"en":"Yesterday I went to the market with my mother.","why":"hier = yesterday; time words like hier, aujourd'hui and demain usually go at the start or end of the sentence."},{"id":"adv-question-time-place-12","type":"gap","prompt":"Tu vois le grand bâtiment ___ ? C'est la mairie.","hint":"(over there)","answers":["là-bas"],"en":"Can you see the big building over there? It's the town hall.","why":"là-bas = over there: grave accent on là and a hyphen."},{"id":"adv-question-time-place-13","type":"flip","front":"Where do short adverbs such as déjà, souvent and toujours go in the perfect tense?","back":"Between the auxiliary (avoir/être) and the past participle: J'ai déjà fini. Nous sommes souvent allés à la plage. Il a toujours aimé le sport."},{"id":"adv-question-time-place-14","type":"transform","instruction":"Add déjà (already) in the correct place.","prompt":"J'ai visité le château.","answers":["J'ai déjà visité le château."],"en":"I have already visited the castle.","why":"In the perfect tense a short adverb goes between avoir and the past participle."},{"id":"adv-question-time-place-15","type":"flip","front":"What do these phrases mean: de temps en temps, tout de suite, d'habitude, en ce moment, à l'avenir?","back":"from time to time, straight away, usually, at the moment, in the future. D'habitude, je prends le bus. En ce moment, je révise. À l'avenir, je voudrais voyager."},{"id":"adv-question-time-place-16","type":"gap","prompt":"Je vais au cinéma ___, mais pas très souvent.","hint":"(from time to time)","answers":["de temps en temps","de temps à autre"],"en":"I go to the cinema from time to time, but not very often.","why":"de temps en temps = from time to time, an adverbial phrase of frequency."},{"id":"adv-question-time-place-17","type":"gap","prompt":"___, je prends le bus pour aller au collège, mais aujourd'hui j'y vais à pied.","hint":"(usually)","answers":["D'habitude","Normalement","Généralement","Habituellement","En général"],"en":"Usually I take the bus to school, but today I'm walking there.","why":"d'habitude = usually; normalement, généralement and en général are also correct."},{"id":"adv-question-time-place-18","type":"gap","prompt":"Range ta chambre ___ !","hint":"(straight away)","answers":["tout de suite","immédiatement"],"en":"Tidy your room straight away!","why":"tout de suite = straight away / right now; immédiatement means the same."}]},{"id":"quantifiers","order":12,"area":"Quantifiers/intensifiers","title":"Quantifiers and intensifiers","spec":"Quantifiers/intensifiers: e.g. très, assez, beaucoup, peu, trop","receptive":false,"summary":["Intensifiers go in front of an adjective or adverb: très (very), assez (quite), trop (too), vraiment (really), si (so), un peu (a bit): Le film était très long.","beaucoup (a lot) goes with a verb, never with an adjective: J'aime beaucoup le sport. Never say très beaucoup.","Before a noun, beaucoup de, trop de, assez de, peu de and un peu de always take plain de (d' before a vowel), never du, de la or des: beaucoup de devoirs, peu d'argent.","peu de = not much / few (negative idea); un peu de = a little (positive idea): J'ai peu de temps. J'ai un peu de temps.","assez means quite (assez cher) or enough (assez de temps); trop means too (trop cher) or too much / too many (trop de bruit).","si and tellement mean so in front of an adjective or adverb: Elle est si drôle ! Il parle tellement vite !","In the perfect tense beaucoup, trop and assez go between avoir and the past participle: J'ai trop mangé.","la plupart (most) is the exception: it takes de + the definite article: la plupart des élèves ont un portable (plural verb), la plupart du temps (most of the time)."],"cards":[{"id":"quantifiers-01","type":"flip","front":"très or beaucoup: when do you use each?","back":"très goes in front of an adjective or adverb: très grand, très vite. beaucoup goes with a verb (J'aime beaucoup lire) or with de + noun (beaucoup de livres). Never say très beaucoup."},{"id":"quantifiers-02","type":"gap","prompt":"Ce pull est ___ cher ; je ne peux pas l'acheter.","hint":"(too)","answers":["trop"],"en":"This jumper is too expensive; I can't buy it.","why":"trop (too) goes in front of the adjective cher."},{"id":"quantifiers-03","type":"gap","prompt":"Ma chambre est ___ grande, mais je la partage avec ma sœur.","hint":"(quite)","answers":["assez","plutôt"],"en":"My bedroom is quite big, but I share it with my sister.","why":"assez (quite) goes in front of the adjective; plutôt (rather) also works."},{"id":"quantifiers-04","type":"gap","prompt":"Il fait ___ froid aujourd'hui !","hint":"(really)","answers":["vraiment"],"en":"It's really cold today!","why":"vraiment (really) intensifies the adjective froid and goes in front of it."},{"id":"quantifiers-05","type":"gap","prompt":"J'aime ___ jouer au foot avec mes copains.","hint":"(a lot)","answers":["beaucoup"],"en":"I like playing football with my mates a lot.","why":"beaucoup modifies the verb aimer and goes straight after it."},{"id":"quantifiers-06","type":"flip","front":"What comes after beaucoup, trop, assez and peu when they are followed by a noun?","back":"Always plain de (d' before a vowel or silent h), never du, de la or des, whatever the gender or number: beaucoup de monde, trop de sucre, assez de chaises, peu d'argent."},{"id":"quantifiers-07","type":"gap","prompt":"Il y a ___ voitures dans le centre-ville.","hint":"(too many)","answers":["trop de"],"en":"There are too many cars in the town centre.","why":"trop de + noun = too much / too many; de does not change to des before a plural noun."},{"id":"quantifiers-08","type":"gap","prompt":"Je mange ___ légumes parce que c'est bon pour la santé.","hint":"(a lot of)","answers":["beaucoup de"],"en":"I eat a lot of vegetables because it's good for my health.","why":"beaucoup de + noun, with plain de even though légumes is plural."},{"id":"quantifiers-09","type":"gap","prompt":"Je n'ai pas ___ temps pour faire du sport.","hint":"(enough)","answers":["assez de"],"en":"I don't have enough time to do sport.","why":"assez de + noun = enough; the quantity word is followed by plain de."},{"id":"quantifiers-10","type":"transform","instruction":"Replace the word in bold with beaucoup de.","prompt":"Il y a **des** touristes en été.","answers":["Il y a beaucoup de touristes en été."],"en":"There are a lot of tourists in summer.","why":"After a quantity word, des becomes de: beaucoup de touristes."},{"id":"quantifiers-11","type":"flip","front":"What is the difference between peu de and un peu de?","back":"peu de = not much / few, a negative idea: J'ai peu d'amis (I haven't got many friends). un peu de = a little, a positive idea: Je voudrais un peu de sucre (I'd like a bit of sugar)."},{"id":"quantifiers-12","type":"gap","prompt":"Ma famille mange ___ viande ; nous sommes presque végétariens.","hint":"(not much)","answers":["peu de"],"en":"My family doesn't eat much meat; we are almost vegetarian.","why":"peu de + noun = not much / little, followed by plain de, not de la."},{"id":"quantifiers-13","type":"gap","prompt":"Je voudrais ___ lait dans mon thé, s'il vous plaît.","hint":"(a little)","answers":["un peu de"],"en":"I'd like a little milk in my tea, please.","why":"un peu de + noun = a little (positive), followed by plain de, not du."},{"id":"quantifiers-14","type":"transform","instruction":"Rewrite the sentence using peu de instead of beaucoup de.","prompt":"Il y a beaucoup d'espaces verts dans ma ville.","answers":["Il y a peu d'espaces verts dans ma ville."],"en":"There are few green spaces in my town.","why":"peu de works like beaucoup de; de becomes d' before a vowel: peu d'espaces."},{"id":"quantifiers-15","type":"flip","front":"How do you say 'so' in front of an adjective, as in 'she is so funny'?","back":"si or tellement before the adjective or adverb: Elle est si drôle ! Il parle tellement vite ! Often followed by que: Il était si fatigué qu'il s'est endormi."},{"id":"quantifiers-16","type":"gap","prompt":"Le voyage était ___ long que je me suis endormi dans le train.","hint":"(so)","answers":["si","tellement"],"en":"The journey was so long that I fell asleep on the train.","why":"si or tellement (so) goes in front of the adjective long; ... que = ... that."},{"id":"quantifiers-17","type":"flip","front":"Where do beaucoup, trop and assez go in the perfect tense?","back":"Between avoir/être and the past participle: J'ai beaucoup aimé le film. Tu as trop mangé. Nous avons assez travaillé."},{"id":"quantifiers-18","type":"gap","prompt":"Hier soir, j'ai ___ mangé et maintenant j'ai mal au ventre.","hint":"(too much)","answers":["trop"],"en":"Last night I ate too much and now I've got stomach ache.","why":"In the perfect tense trop goes between the auxiliary avoir and the past participle mangé."},{"id":"quantifiers-19","type":"gap","prompt":"___ élèves de ma classe ont un portable.","hint":"(most)","answers":["La plupart des"],"en":"Most pupils in my class have a mobile phone.","why":"la plupart (most) is followed by de + the definite article (des), not plain de like beaucoup de; the verb after it is plural: ont."}]},{"id":"pron-subject","order":13,"area":"Pronouns","title":"Subject pronouns, on, tu and vous","spec":"Pronouns: personal: all subjects, including on; Verbs: modes of address: tu, vous","receptive":false,"summary":["The subject pronouns are je, tu, il, elle, on, nous, vous, ils, elles.","je becomes j' before a vowel or silent h: j'aime, j'habite.","il and elle also mean it, matching the gender of the noun: Le vélo ? Il est neuf. La voiture ? Elle est rouge.","ils is used for a group of males or a mixed group; elles only for an all-female group: Paul et Julie → ils.","on means we (very common in speech), one, or people in general, and always takes the il/elle form of the verb: on va, on mange.","tu is for one person you know well (friend, family member, child, pet).","vous is for one person you speak to politely (a stranger, a teacher, an adult you don't know) and for any group of people.","Changing nous to on: nous allons → on va; nous jouons → on joue."],"cards":[{"id":"pron-subject-01","type":"flip","front":"List the nine French subject pronouns with their English meanings.","back":"je (I), tu (you, informal), il (he/it), elle (she/it), on (we/one/people), nous (we), vous (you, polite or plural), ils (they, masc. or mixed), elles (they, all female)."},{"id":"pron-subject-02","type":"gap","prompt":"Ma sœur et moi, ___ allons au collège à pied.","hint":"(we)","answers":["nous"],"en":"My sister and I walk to school.","why":"Ma sœur et moi = we; the verb allons is the nous form."},{"id":"pron-subject-03","type":"flip","front":"When does je become j'?","back":"Before a vowel or a silent h: j'aime, j'écoute, j'habite. Not before a consonant: je joue, je vais, je suis."},{"id":"pron-subject-04","type":"transform","instruction":"Rewrite the sentence with je instead of nous.","prompt":"Nous habitons à Londres.","answers":["J'habite à Londres."],"en":"I live in London.","why":"je becomes j' before the silent h of habite; the verb changes to the je form."},{"id":"pron-subject-05","type":"flip","front":"ils or elles: which do you use for a mixed group?","back":"ils. elles is only for an all-female group (or all feminine nouns). Marc et ses sœurs → ils; Léa et Chloé → elles. Even one male in a group of ten makes it ils."},{"id":"pron-subject-06","type":"gap","prompt":"Ma tante et mon oncle ? ___ viennent ce week-end.","hint":"(they)","answers":["Ils"],"en":"My aunt and uncle? They're coming this weekend.","why":"A mixed group of male and female takes ils."},{"id":"pron-subject-07","type":"gap","prompt":"Mes sœurs et ma mère ? ___ adorent faire du shopping.","hint":"(they)","answers":["Elles"],"en":"My sisters and my mother? They love going shopping.","why":"An all-female group takes elles."},{"id":"pron-subject-08","type":"transform","instruction":"Replace the words in bold with a subject pronoun.","prompt":"**Le livre et la lampe** sont sur la table.","answers":["Ils sont sur la table."],"en":"They are on the table.","why":"A masculine and a feminine noun together count as masculine plural: ils."},{"id":"pron-subject-09","type":"gap","prompt":"Où est ton vélo ? — ___ est dans le garage.","hint":"(it)","answers":["Il"],"en":"Where's your bike? — It's in the garage.","why":"vélo is masculine, so 'it' is il."},{"id":"pron-subject-10","type":"gap","prompt":"Tu aimes ma nouvelle robe ? — Oui, ___ est très jolie.","hint":"(it)","answers":["elle"],"en":"Do you like my new dress? — Yes, it's very pretty.","why":"robe is feminine, so 'it' is elle."},{"id":"pron-subject-11","type":"flip","front":"What can on mean, and which verb form does it take?","back":"on = we (very common in speech), one / you in general, or people / they in general. It always takes the il/elle form of the verb: On va au cinéma ? En France, on mange tard."},{"id":"pron-subject-12","type":"gap","prompt":"Le week-end, on ___ souvent au parc avec nos copains.","base":"aller","hint":"present tense","answers":["va"],"en":"At the weekend we often go to the park with our friends.","why":"on always takes the third-person singular (il/elle) form of the verb: on va."},{"id":"pron-subject-13","type":"gap","prompt":"En France, on ___ beaucoup de pain.","base":"manger","hint":"present tense","answers":["mange"],"en":"In France, people eat a lot of bread.","why":"Here on means people in general; it still takes the il/elle form: on mange."},{"id":"pron-subject-14","type":"transform","instruction":"Rewrite the sentence with nous instead of on.","prompt":"On joue au tennis le mercredi.","answers":["Nous jouons au tennis le mercredi."],"en":"We play tennis on Wednesdays.","why":"on takes the il/elle form; nous takes the -ons form: on joue → nous jouons."},{"id":"pron-subject-15","type":"transform","instruction":"Rewrite the sentence with on instead of nous.","prompt":"Nous allons à la plage.","answers":["On va à la plage."],"en":"We're going to the beach.","why":"on meaning we takes the il/elle form of the verb: nous allons → on va."},{"id":"pron-subject-16","type":"flip","front":"tu or vous: when do you use each?","back":"tu: one person you know well: a friend, a family member, a child, a pet. vous: one person you address politely (a stranger, shop assistant, teacher, older adult) and always for more than one person."},{"id":"pron-subject-17","type":"transform","instruction":"You are now asking a stranger. Rewrite the question using vous.","prompt":"Tu as l'heure ?","answers":["Vous avez l'heure ?","Avez-vous l'heure ?","Est-ce que vous avez l'heure ?"],"en":"Have you got the time?","why":"A stranger is addressed with vous, so the verb changes to the vous form: vous avez."},{"id":"pron-subject-18","type":"transform","instruction":"You are now asking a friend. Rewrite the question using tu.","prompt":"Vous voulez venir au cinéma ce soir ?","answers":["Tu veux venir au cinéma ce soir ?","Veux-tu venir au cinéma ce soir ?","Est-ce que tu veux venir au cinéma ce soir ?"],"en":"Do you want to come to the cinema tonight?","why":"A friend is addressed with tu, so the verb changes to the tu form: tu veux."}]},{"id":"pron-reflexive","order":14,"area":"Pronouns","title":"Reflexive pronouns and reflexive verbs","spec":"Pronouns: reflexive; Verbs: regular and irregular forms of verbs, including reflexive verbs","receptive":false,"summary":["A reflexive verb has an extra pronoun that refers back to the subject: se laver (to wash oneself) → je me lave.","The reflexive pronouns are me, te, se, nous, vous, se: je me couche, tu te couches, il se couche, nous nous couchons, vous vous couchez, elles se couchent.","me, te and se become m', t', s' before a vowel or silent h: je m'appelle, tu t'habilles, elle s'amuse. nous and vous never shorten.","In the negative, ne goes before the reflexive pronoun and pas after the verb: je ne me lève pas.","In the perfect tense every reflexive verb takes être, and the past participle normally agrees with the subject: elle s'est levée, nous nous sommes amusés. No agreement when a body part follows: elle s'est brossé les dents.","In the negative perfect, ne ... pas goes round the pronoun and être: je ne me suis pas réveillé.","After another verb, the reflexive pronoun matches the subject and goes before the infinitive: je vais me coucher, nous voulons nous reposer.","In positive commands the pronoun goes after the verb with a hyphen, and te becomes toi: lève-toi, dépêchons-nous, asseyez-vous.","In negative commands the pronoun stays before the verb: ne te lève pas, ne vous inquiétez pas."],"cards":[{"id":"pron-reflexive-01","type":"flip","front":"What is a reflexive verb, and what are the six reflexive pronouns?","back":"A verb with an extra pronoun that refers back to the subject, e.g. se laver (to wash oneself). je me lave, tu te laves, il/elle/on se lave, nous nous lavons, vous vous lavez, ils/elles se lavent."},{"id":"pron-reflexive-02","type":"gap","prompt":"Le matin, je ___ à sept heures.","base":"se réveiller","answers":["me réveille"],"en":"In the morning I wake up at seven o'clock.","why":"With je, the reflexive pronoun is me, and the verb takes the normal je ending: je me réveille."},{"id":"pron-reflexive-03","type":"flip","front":"When do me, te and se become m', t' and s'?","back":"Before a vowel or silent h: je m'appelle, tu t'habilles, il s'intéresse au sport, elles s'entendent bien. nous and vous never shorten: nous nous habillons."},{"id":"pron-reflexive-04","type":"gap","prompt":"Ma petite sœur ___ Chloé.","base":"s'appeler","answers":["s'appelle"],"en":"My little sister is called Chloé.","why":"se becomes s' before a vowel; appeler doubles the l in the il/elle form: elle s'appelle."},{"id":"pron-reflexive-05","type":"gap","prompt":"Tu ___ bien avec tes parents ?","base":"s'entendre","answers":["t'entends"],"en":"Do you get on well with your parents?","why":"te becomes t' before a vowel, and entendre takes the tu ending -s: tu t'entends."},{"id":"pron-reflexive-06","type":"gap","prompt":"Le samedi, nous ___ dans le parc avec nos amis.","base":"se promener","answers":["nous promenons"],"en":"On Saturdays we go for a walk in the park with our friends.","why":"The nous form needs nous twice, subject and reflexive pronoun: nous nous promenons. There is no accent in the nous form of promener."},{"id":"pron-reflexive-07","type":"flip","front":"Where do ne and pas go with a reflexive verb in the present tense?","back":"ne goes before the reflexive pronoun and pas after the verb, so the pronoun stays next to its verb: je ne me lève pas, il ne s'ennuie jamais, nous ne nous disputons pas."},{"id":"pron-reflexive-08","type":"transform","instruction":"Make the sentence negative using ne ... pas.","prompt":"Je me lève tôt le dimanche.","answers":["Je ne me lève pas tôt le dimanche."],"en":"I don't get up early on Sundays.","why":"ne goes before the reflexive pronoun and pas after the verb: je ne me lève pas."},{"id":"pron-reflexive-09","type":"flip","front":"How do reflexive verbs form the perfect tense?","back":"Always with être, with the reflexive pronoun before être; the past participle agrees with the subject: je me suis levé(e), tu t'es levé(e), il s'est levé, elle s'est levée, nous nous sommes levé(e)s, vous vous êtes levé(e)(s), ils se sont levés, elles se sont levées. Trap: no agreement when a body part follows the verb: elle s'est lavé les mains, elle s'est brossé les dents."},{"id":"pron-reflexive-10","type":"gap","prompt":"Hier, Sophie ___ à six heures.","base":"se lever","answers":["s'est levée"],"en":"Yesterday Sophie got up at six o'clock.","why":"Reflexive verbs take être in the perfect; the participle agrees with the feminine singular subject: elle s'est levée."},{"id":"pron-reflexive-11","type":"gap","prompt":"Samedi dernier, mes amis et moi, nous ___ à la fête.","base":"s'amuser","answers":["nous sommes amusés"],"en":"Last Saturday my friends and I had fun at the party.","why":"Perfect with être: nous nous sommes + participle. mes amis et moi is a masculine (mixed) plural subject, so amusés."},{"id":"pron-reflexive-12","type":"transform","instruction":"Put the sentence into the perfect tense.","prompt":"Elle se couche à dix heures.","answers":["Elle s'est couchée à dix heures."],"en":"She went to bed at ten o'clock.","why":"se coucher takes être in the perfect: s'est (se shortens before est), and the participle agrees with elle: couchée."},{"id":"pron-reflexive-13","type":"transform","instruction":"Make the sentence negative using ne ... pas.","prompt":"Je me suis réveillé à l'heure.","answers":["Je ne me suis pas réveillé à l'heure."],"en":"I didn't wake up on time.","why":"In the perfect, ne goes before the reflexive pronoun and pas after être: je ne me suis pas réveillé."},{"id":"pron-reflexive-14","type":"flip","front":"What happens to the reflexive pronoun when a reflexive verb is an infinitive after another verb?","back":"It stays, matches the subject and goes just before the infinitive: je vais me coucher, tu dois te dépêcher, nous voulons nous reposer, elles aiment se baigner. Never 'je vais se coucher'."},{"id":"pron-reflexive-15","type":"gap","prompt":"Ce soir, tu dois ___ tôt parce que tu as un examen demain.","base":"se coucher","answers":["te coucher"],"en":"Tonight you must go to bed early because you have an exam tomorrow.","why":"After devoir the reflexive verb is an infinitive, but its pronoun still matches the subject tu: tu dois te coucher."},{"id":"pron-reflexive-16","type":"flip","front":"How do you give a command with a reflexive verb, positive and negative?","back":"Positive: pronoun after the verb with a hyphen, and te becomes toi: lève-toi !, dépêchons-nous !, asseyez-vous ! Negative: pronoun back before the verb: ne te lève pas !, ne vous inquiétez pas !"},{"id":"pron-reflexive-17","type":"gap","prompt":"Il est sept heures et demie ! ___, tu vas être en retard !","base":"se dépêcher","hint":"(command, tu form)","answers":["Dépêche-toi"],"en":"It's half past seven! Hurry up, you're going to be late!","why":"Positive command: the pronoun follows the verb with a hyphen and te becomes toi; -er verbs drop the -s in the tu command: dépêche-toi."},{"id":"pron-reflexive-18","type":"transform","instruction":"Make the command negative.","prompt":"Lève-toi !","answers":["Ne te lève pas !"],"en":"Don't get up!","why":"In a negative command the pronoun goes back before the verb and toi becomes te: ne te lève pas."}]},{"id":"pron-object","order":15,"area":"Pronouns","title":"Direct and indirect object pronouns, y and en","spec":"Pronouns: object: direct and indirect; use of y, en","receptive":false,"summary":["Direct object pronouns replace a noun that the verb acts on directly: le (him/it), la (her/it), les (them): Je regarde le match → Je le regarde.","le and la become l' before a vowel or silent h: J'aime cette chanson → Je l'aime.","me, te, nous, vous can be direct or indirect: Il me voit (he sees me), Il me parle (he speaks to me). me and te become m' and t' before a vowel.","Indirect object pronouns replace à + a person: lui (to him / to her), leur (to them): Je parle à ma mère → Je lui parle. leur never adds an -s here.","Common verbs with à + person: parler à, téléphoner à, dire à, demander à, donner à, offrir à, envoyer à, écrire à, répondre à.","y replaces à + a place or thing, or a place after en, dans, chez etc.: Je vais au parc → J'y vais. Je joue au foot → J'y joue.","en replaces de + noun (du, de la, de l', des): Je bois du lait → J'en bois. J'ai besoin d'argent → J'en ai besoin.","With a number or quantity, use en and keep the number or quantity at the end: J'ai deux sœurs → J'en ai deux.","In simple tenses all these pronouns go straight before the verb: Je les vois. Elle leur téléphone. Nous y allons."],"cards":[{"id":"pron-object-01","type":"flip","front":"What are the direct object pronouns, and where do they go?","back":"me (me), te (you), le (him / it), la (her / it), nous (us), vous (you), les (them). me, te, le, la become m', t', l' before a vowel or silent h. They go straight before the verb: Je le vois. Il m'aide."},{"id":"pron-object-02","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Je regarde **la télévision** le soir.","answers":["Je la regarde le soir."],"en":"I watch it in the evening.","why":"la télévision is feminine singular, so the direct object pronoun is la, placed before the verb."},{"id":"pron-object-03","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Nous attendons **le bus** devant le collège.","answers":["Nous l'attendons devant le collège."],"en":"We wait for it in front of the school.","why":"attendre takes a direct object (no preposition, unlike English 'wait for'), so le bus becomes le, which shortens to l' before the vowel."},{"id":"pron-object-04","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"J'adore **mes grands-parents**.","answers":["Je les adore."],"en":"I love them.","why":"mes grands-parents is plural, so the pronoun is les. je no longer shortens because les starts with a consonant."},{"id":"pron-object-05","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Elle achète **l'ordinateur** en ligne.","answers":["Elle l'achète en ligne."],"en":"She buys it online.","why":"l'ordinateur is masculine singular (le), and le becomes l' before the vowel of achète."},{"id":"pron-object-06","type":"gap","prompt":"Tu vois souvent ton cousin ? — Oui, je ___ vois tous les week-ends.","hint":"(him)","answers":["le"],"en":"Do you often see your cousin? — Yes, I see him every weekend.","why":"voir takes a direct object, so 'him' is le, placed before the verb."},{"id":"pron-object-07","type":"gap","prompt":"Ton frère ___ cherche partout !","hint":"(you, informal)","answers":["te"],"en":"Your brother is looking for you everywhere!","why":"chercher takes a direct object, and 'you' (tu form) as an object pronoun is te, before the verb."},{"id":"pron-object-08","type":"flip","front":"What are lui and leur, and when do you use them?","back":"Indirect object pronouns: they replace à + a person. lui = to him or to her; leur = to them. Je parle à mon père → Je lui parle. Je téléphone à mes amis → Je leur téléphone. leur as a pronoun never takes an -s."},{"id":"pron-object-09","type":"flip","front":"Name some common verbs followed by à + person (so they take lui / leur).","back":"parler à, téléphoner à, dire à, demander à, donner à, offrir à, envoyer à, écrire à, répondre à, prêter à, ressembler à. Watch out: English 'I phone her' and 'I ask him' are je lui téléphone and je lui demande in French."},{"id":"pron-object-10","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Je téléphone **à ma grand-mère** le dimanche.","answers":["Je lui téléphone le dimanche."],"en":"I phone her on Sundays.","why":"téléphoner à + person takes an indirect object pronoun: à ma grand-mère → lui."},{"id":"pron-object-11","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Nous offrons un cadeau **à nos professeurs**.","answers":["Nous leur offrons un cadeau."],"en":"We give them a present.","why":"à + plural people becomes leur, which goes before the verb."},{"id":"pron-object-12","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Le prof explique la règle **aux élèves**.","answers":["Le prof leur explique la règle."],"en":"The teacher explains the rule to them.","why":"aux élèves = à + les élèves, plural people, so the indirect object pronoun is leur."},{"id":"pron-object-13","type":"gap","prompt":"Mes copains m'ont envoyé un message, alors je ___ ai répondu tout de suite.","hint":"(to them)","answers":["leur"],"en":"My friends sent me a message, so I replied to them straight away.","why":"répondre à + people takes leur, which goes before avoir in the perfect."},{"id":"pron-object-14","type":"flip","front":"What does y replace, and what does it mean?","back":"à + a place or thing, or a place after en, dans, chez, sur etc. It means 'there' or 'about it / to it'. Je vais au cinéma → J'y vais. Elle habite en Suisse → Elle y habite. Je pense à l'examen → J'y pense."},{"id":"pron-object-15","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Je vais **à la piscine** le mercredi.","answers":["J'y vais le mercredi."],"en":"I go there on Wednesdays.","why":"à + a place becomes y, before the verb; je shortens to j' before y."},{"id":"pron-object-16","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Mes cousins habitent **au Canada**.","answers":["Mes cousins y habitent."],"en":"My cousins live there.","why":"au Canada is a place introduced by à (au = à + le), so it becomes y."},{"id":"pron-object-17","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Il joue **au tennis** le samedi.","answers":["Il y joue le samedi."],"en":"He plays it on Saturdays.","why":"jouer à + a sport is à + a thing, so au tennis becomes y."},{"id":"pron-object-18","type":"gap","prompt":"Le Maroc ? Nous ___ allons cet été.","hint":"(there)","answers":["y"],"en":"Morocco? We're going there this summer.","why":"'there' referring to a place already mentioned is y, placed before the verb."},{"id":"pron-object-19","type":"flip","front":"What does en replace, and what does it mean?","back":"de + noun, including du, de la, de l', des and verbs with de (avoir besoin de, parler de). It means 'some', 'any', 'of it' or 'of them'. Je bois du jus → J'en bois. Il a besoin d'aide → Il en a besoin. Je n'en veux pas."},{"id":"pron-object-20","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Je mange **des fruits** tous les jours.","answers":["J'en mange tous les jours."],"en":"I eat some every day.","why":"des + noun is replaced by en, before the verb; je shortens to j' before en."},{"id":"pron-object-21","type":"gap","prompt":"Des frites ? Mon petit frère ___ mange tous les jours !","hint":"(some)","answers":["en"],"en":"Chips? My little brother eats them every day!","why":"The understood object is des frites (des + noun), so the pronoun is en, not les."},{"id":"pron-object-22","type":"flip","front":"How do you use en with numbers and quantities?","back":"Replace the noun with en and keep the number or quantity word after the verb: J'ai deux sœurs → J'en ai deux. Il y a beaucoup de touristes → Il y en a beaucoup. J'ai une voiture → J'en ai une. English often leaves 'of them' out, but French cannot leave out en."},{"id":"pron-object-23","type":"transform","instruction":"Replace the word in bold with a pronoun, keeping the number.","prompt":"J'ai trois **frères**.","answers":["J'en ai trois."],"en":"I've got three (of them).","why":"With a number, the noun becomes en before the verb and the number stays at the end: j'en ai trois."},{"id":"pron-object-24","type":"transform","instruction":"Replace the words in bold with a pronoun, keeping the quantity.","prompt":"Elle achète un kilo **de tomates**.","answers":["Elle en achète un kilo."],"en":"She buys a kilo (of them).","why":"de + noun after a quantity becomes en before the verb; the quantity un kilo stays after the verb."}]},{"id":"pron-order","order":16,"area":"Pronouns","title":"Position and order of object pronouns","spec":"Pronouns: position and order of object pronouns","receptive":false,"summary":["In simple tenses, object pronouns go straight before the verb: Je le vois. Elle leur parle.","In the perfect (and other compound tenses), they go before avoir or être: Je l'ai vu. Nous y sommes allés.","With a verb + infinitive, they go before the infinitive they belong to: Je vais le faire. Tu peux m'aider ?","In negatives, ne goes before the pronoun(s) and pas after the verb or auxiliary: Je ne le vois pas. Je ne l'ai pas vu.","In positive commands, pronouns go after the verb with hyphens, and me / te become moi / toi: Prends-le ! Aide-moi ! Donne-le-moi !","In negative commands, they go back before the verb: Ne le prends pas ! Ne me parle pas !","With two pronouns before the verb, the order is me/te/se/nous/vous → le/la/les → lui/leur → y → en: Il me le donne. Je le lui donne. Il y en a.","In the perfect with avoir, the past participle agrees with a direct object pronoun placed before it: Les photos ? Je les ai vues.","There is no agreement with lui, leur, y or en: Je leur ai parlé. Des pommes ? J'en ai acheté."],"cards":[{"id":"pron-order-01","type":"flip","front":"Where does an object pronoun go: (a) present, (b) perfect, (c) verb + infinitive, (d) positive command?","back":"(a) before the verb: je le vois. (b) before avoir / être: je l'ai vu. (c) before the infinitive: je vais le voir. (d) after the verb with a hyphen: regarde-le !"},{"id":"pron-order-02","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"J'ai vu **le film** hier.","answers":["Je l'ai vu hier."],"en":"I saw it yesterday.","why":"In the perfect the pronoun goes before avoir; le shortens to l' before ai."},{"id":"pron-order-03","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Nous avons téléphoné **à nos cousins**.","answers":["Nous leur avons téléphoné."],"en":"We phoned them.","why":"à + people becomes leur, which goes before avoir in the perfect. No agreement with an indirect pronoun."},{"id":"pron-order-04","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Je vais acheter **ce jean**.","answers":["Je vais l'acheter."],"en":"I'm going to buy it.","why":"With verb + infinitive, the pronoun goes before the infinitive it belongs to: l'acheter (le shortens before a vowel)."},{"id":"pron-order-05","type":"flip","front":"Where do ne and pas go when there is an object pronoun?","back":"ne goes before the pronoun(s); pas goes after the verb, or after avoir / être in the perfect: je ne le connais pas, je ne l'ai pas vu. With verb + infinitive, ne ... pas goes round the first verb: je ne vais pas le faire."},{"id":"pron-order-06","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Je ne regarde pas **les infos**.","answers":["Je ne les regarde pas."],"en":"I don't watch it (the news).","why":"les infos is plural, so les; it goes between ne and the verb: je ne les regarde pas."},{"id":"pron-order-07","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Je ne vais pas inviter **Lucas**.","answers":["Je ne vais pas l'inviter."],"en":"I'm not going to invite him.","why":"ne ... pas goes round aller, and the pronoun goes before the infinitive: l'inviter."},{"id":"pron-order-08","type":"flip","front":"Where do object pronouns go in commands (imperatives)?","back":"Positive: after the verb, joined by hyphens; me → moi, te → toi: Regarde-le ! Écoutez-moi ! With two pronouns, direct before indirect: Donne-le-moi ! Envoie-la-lui ! Negative: back before the verb in the normal order: Ne le regarde pas ! Ne me le donne pas !"},{"id":"pron-order-09","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Prends **ton manteau** !","answers":["Prends-le !"],"en":"Take it!","why":"In a positive command the pronoun follows the verb with a hyphen: prends-le."},{"id":"pron-order-10","type":"transform","instruction":"Make the command negative.","prompt":"Achète-les !","answers":["Ne les achète pas !"],"en":"Don't buy them!","why":"In a negative command the pronoun goes back before the verb: ne les achète pas."},{"id":"pron-order-11","type":"gap","prompt":"Passe-___ le sel, s'il te plaît !","hint":"(me)","answers":["moi"],"en":"Pass me the salt, please!","why":"After a positive command, me becomes moi: passe-moi."},{"id":"pron-order-12","type":"flip","front":"In what order do two object pronouns go before the verb?","back":"me / te / se / nous / vous → le / la / les → lui / leur → y → en. Il me le prête (he lends it to me). Je la leur montre (I show it to them). Je lui en ai parlé (I told him / her about it). Il y en a trois (there are three of them)."},{"id":"pron-order-13","type":"transform","instruction":"Replace the words in bold with pronouns.","prompt":"Je donne **le cadeau à ma mère**.","answers":["Je le lui donne."],"en":"I give it to her.","why":"le cadeau → le, à ma mère → lui; le comes before lui: je le lui donne."},{"id":"pron-order-14","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Mon père me prête **sa voiture**.","answers":["Mon père me la prête."],"en":"My dad lends it to me.","why":"sa voiture → la; me comes before la in the pronoun order: me la prête."},{"id":"pron-order-15","type":"gap","prompt":"Il y a des œufs ? — Oui, il y ___ a six.","hint":"(of them)","answers":["en"],"en":"Are there any eggs? — Yes, there are six (of them).","why":"With a number, the noun is replaced by en, and y always comes before en: il y en a six."},{"id":"pron-order-16","type":"flip","front":"When does a past participle agree with an object pronoun?","back":"In the perfect with avoir, it agrees with a direct object pronoun (le, la, l', les, me, te, nous, vous) placed before it: Ta robe ? Je l'ai achetée. Mes clés ? Je les ai perdues. No agreement with lui, leur, y or en: Je leur ai écrit. Des pommes ? J'en ai acheté."},{"id":"pron-order-17","type":"gap","prompt":"Les photos de la fête ? Je les ai ___ sur Instagram.","base":"voir","answers":["vues"],"en":"The photos from the party? I saw them on Instagram.","why":"les stands for les photos (feminine plural) and comes before avoir, so the participle agrees: vues."},{"id":"pron-order-18","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Je n'ai pas fait **mes devoirs**.","answers":["Je ne les ai pas faits."],"en":"I haven't done it (my homework).","why":"les goes between ne and avoir; it stands for mes devoirs (masculine plural) and comes before avoir, so fait agrees: faits."}]},{"id":"pron-disjunctive","order":17,"area":"Pronouns","title":"Emphatic (disjunctive) pronouns","spec":"Pronouns: disjunctive/emphatic","receptive":false,"summary":["The emphatic pronouns are moi, toi, lui, elle, nous, vous, eux, elles.","Use them after prepositions: avec moi, pour toi, sans lui, à côté d'elle, chez nous.","chez + emphatic pronoun = at / to someone's house: chez moi (at my place), chez eux (at their house).","Use them for emphasis, usually with the subject pronoun as well: Moi, je préfère le rap. Lui, il est très sportif.","Use them after c'est and ce sont: C'est moi ! C'est lui qui a gagné. Ce sont elles.","Use them after que in comparisons: Mon frère est plus grand que moi.","Use them on their own and with aussi / non plus: Qui veut du gâteau ? — Moi ! Moi aussi. Moi non plus.","lui means him only (her is elle); eux is them for males or a mixed group, elles for females.","Add -même(s) for -self: moi-même (myself), elle-même (herself), eux-mêmes (themselves)."],"cards":[{"id":"pron-disjunctive-01","type":"flip","front":"List the eight emphatic (disjunctive) pronouns with their meanings.","back":"moi (me), toi (you, informal), lui (him), elle (her), nous (us), vous (you, polite or plural), eux (them, masc. or mixed), elles (them, all female)."},{"id":"pron-disjunctive-02","type":"gap","prompt":"Tu veux venir au cinéma avec ___ ce soir ?","hint":"(me)","answers":["moi"],"en":"Do you want to come to the cinema with me tonight?","why":"After a preposition such as avec, use the emphatic pronoun: avec moi."},{"id":"pron-disjunctive-03","type":"gap","prompt":"Mon frère ? Je vais au match avec ___ samedi.","hint":"(him)","answers":["lui"],"en":"My brother? I'm going to the match with him on Saturday.","why":"After a preposition, 'him' is the emphatic pronoun lui."},{"id":"pron-disjunctive-04","type":"gap","prompt":"Maman, ce cadeau est pour ___ !","hint":"(you, informal)","answers":["toi"],"en":"Mum, this present is for you!","why":"After pour, the informal 'you' is toi (not tu)."},{"id":"pron-disjunctive-05","type":"flip","front":"What does chez + emphatic pronoun mean?","back":"At or to someone's house: chez moi (at my place / home), chez toi, chez lui, chez elle, chez nous, chez vous, chez eux, chez elles. Je rentre chez moi = I'm going home."},{"id":"pron-disjunctive-06","type":"gap","prompt":"Mes grands-parents ? Nous passons Noël chez ___.","hint":"(them)","answers":["eux"],"en":"My grandparents? We spend Christmas at their house.","why":"Grandparents are a mixed group, so 'them' after chez is eux."},{"id":"pron-disjunctive-07","type":"transform","instruction":"Replace the words in bold with an emphatic pronoun.","prompt":"Nous dînons chez **ma grand-mère**.","answers":["Nous dînons chez elle."],"en":"We are having dinner at her house.","why":"ma grand-mère is feminine singular, so the emphatic pronoun after chez is elle."},{"id":"pron-disjunctive-08","type":"flip","front":"eux or elles? And how do you say 'her' after a preposition?","back":"eux = them for males or a mixed group (avec eux); elles = them for females only (avec elles). 'Her' after a preposition is elle (pour elle); lui only ever means him here."},{"id":"pron-disjunctive-09","type":"gap","prompt":"Mes cousines ? L'été dernier, je suis parti en vacances avec ___.","hint":"(them)","answers":["elles"],"en":"My cousins? Last summer I went on holiday with them.","why":"cousines are all female, so 'them' after avec is elles."},{"id":"pron-disjunctive-10","type":"transform","instruction":"Replace the words in bold with an emphatic pronoun.","prompt":"Je joue au tennis avec **mes copains**.","answers":["Je joue au tennis avec eux."],"en":"I play tennis with them.","why":"mes copains is masculine plural, so the emphatic pronoun after avec is eux."},{"id":"pron-disjunctive-11","type":"flip","front":"Apart from after prepositions, when else do you use emphatic pronouns?","back":"For emphasis: Moi, je préfère le jazz. After c'est / ce sont: C'est lui ! In comparisons after que: plus grand que toi. On their own: Qui a faim ? — Moi !"},{"id":"pron-disjunctive-12","type":"gap","prompt":"___, je préfère la musique classique, mais mon frère adore le rap.","hint":"(me, for emphasis)","answers":["Moi"],"en":"Personally, I prefer classical music, but my brother loves rap.","why":"For emphasis, the emphatic pronoun goes at the start, followed by the subject pronoun: Moi, je..."},{"id":"pron-disjunctive-13","type":"gap","prompt":"C'est ___ qui a gagné le match.","hint":"(him)","answers":["lui"],"en":"It was him who won the match.","why":"After c'est, use the emphatic pronoun: c'est lui."},{"id":"pron-disjunctive-14","type":"transform","instruction":"Replace the words in bold with an emphatic pronoun.","prompt":"Ma sœur est plus grande que **mon frère**.","answers":["Ma sœur est plus grande que lui."],"en":"My sister is taller than him.","why":"In comparisons, the pronoun after que is emphatic: que lui."},{"id":"pron-disjunctive-15","type":"flip","front":"How do you say 'me too' and 'me neither'?","back":"Moi aussi (agreeing with a positive): J'adore le chocolat. — Moi aussi ! Moi non plus (agreeing with a negative): Je n'aime pas le foot. — Moi non plus. Also toi aussi, lui non plus, etc."},{"id":"pron-disjunctive-16","type":"gap","prompt":"Je n'aime pas les films d'horreur. — ___ non plus.","hint":"(me)","answers":["Moi"],"en":"I don't like horror films. — Me neither.","why":"On its own or with non plus, the pronoun must be emphatic: Moi non plus."},{"id":"pron-disjunctive-17","type":"flip","front":"How do you say myself, herself, themselves with même?","back":"Emphatic pronoun + hyphen + même(s): moi-même, toi-même, lui-même, elle-même, nous-mêmes, vous-même(s), eux-mêmes, elles-mêmes. J'ai fait ce gâteau moi-même."},{"id":"pron-disjunctive-18","type":"gap","prompt":"Mes parents ont repeint la maison ___.","hint":"(themselves)","answers":["eux-mêmes"],"en":"My parents repainted the house themselves.","why":"Emphatic pronoun + -même, which adds -s in the plural: eux-mêmes (parents is a mixed group)."}]},{"id":"pron-demonstrative","order":18,"area":"Pronouns","title":"Demonstrative pronouns (ça, cela, celui…)","spec":"Pronouns: demonstrative (e.g. ça, cela, celui)","receptive":false,"summary":["ça and cela mean 'that' or 'it' and refer to an idea, an activity or something not named; ça is everyday, cela more formal: Ça me plaît. Cela dépend.","ceci means 'this' and is mostly written: Lisez ceci attentivement.","ce is used with être; it becomes c' before e and é: C'est génial. C'était nul. Ce sont mes amis.","For a general comment, use c'est + masculine adjective: La natation, c'est bon pour la santé.","celui (masc. sing.), celle (fem. sing.), ceux (masc. pl.), celles (fem. pl.) mean 'the one(s)' and agree with the noun they replace.","celui never stands alone: it is followed by -ci (this one / these) or -là (that one / those), by qui / que, or by de: Quel pull ? Celui-ci.","celui + qui / que = the one who / that: J'ai deux frères ; celui qui joue au rugby s'appelle Tom.","celui + de shows who something belongs to: Ce n'est pas mon vélo, c'est celui de ma sœur (my sister's)."],"cards":[{"id":"pron-demonstrative-01","type":"flip","front":"What do ça, cela and ceci mean, and when are they used?","back":"ça = that / it (everyday), cela = that / it (more formal or written), ceci = this. They refer to an idea, an activity or something not named, and never change form: Ça coûte combien ? Cela m'intéresse. Ça ne fait rien."},{"id":"pron-demonstrative-02","type":"gap","prompt":"Faire du shopping avec mes parents ? Non, ___ m'énerve !","hint":"(that)","answers":["ça","cela"],"en":"Going shopping with my parents? No, that annoys me!","why":"An activity or idea is referred to with ça (or the more formal cela), not il or elle."},{"id":"pron-demonstrative-03","type":"gap","prompt":"Je voudrais un billet pour Paris. — D'accord, ___ fait quarante euros.","hint":"(that)","answers":["ça","cela"],"en":"I'd like a ticket to Paris. — OK, that comes to forty euros.","why":"ça (or cela) refers to the whole situation, here the price of what was asked for: ça fait..."},{"id":"pron-demonstrative-04","type":"flip","front":"How is ce used with être?","back":"c'est (it is / that is), ce sont (they are / these are), c'était (it was), ce sera (it will be). ce becomes c' before e and é. For a general comment use c'est + masculine adjective: Le ski, c'est fatigant. La musique, c'est important."},{"id":"pron-demonstrative-05","type":"gap","prompt":"La natation, ___ bon pour la santé.","hint":"(it is)","answers":["c'est"],"en":"Swimming is good for your health.","why":"A general comment about an activity uses c'est + masculine adjective: c'est bon (not elle est bonne)."},{"id":"pron-demonstrative-06","type":"gap","prompt":"Regarde la photo : ___ mes cousins de Lyon.","hint":"(these are)","answers":["ce sont"],"en":"Look at the photo: these are my cousins from Lyon.","why":"Before a plural noun, written French uses ce sont rather than c'est."},{"id":"pron-demonstrative-07","type":"flip","front":"What are the four forms of celui, and what do they mean?","back":"celui (masc. sing.), celle (fem. sing.), ceux (masc. pl.), celles (fem. pl.) = the one / the ones. They agree with the noun they replace and must be followed by -ci / -là, qui / que or de."},{"id":"pron-demonstrative-08","type":"flip","front":"What is the difference between celui-ci and celui-là?","back":"-ci = this one / these (nearer), -là = that one / those (further away): Quel gâteau veux-tu ? — Celui-ci. Je préfère ces chaussures-là → je préfère celles-là."},{"id":"pron-demonstrative-09","type":"gap","prompt":"Quelle veste préfères-tu ? — ___, la noire.","hint":"(that one)","answers":["Celle-là"],"en":"Which jacket do you prefer? — That one, the black one.","why":"veste is feminine singular, so celle; -là means 'that one'."},{"id":"pron-demonstrative-10","type":"gap","prompt":"Ces baskets-là sont trop chères. Je vais prendre ___.","hint":"(these ones)","answers":["celles-ci"],"en":"Those trainers are too expensive. I'm going to take these ones.","why":"baskets is feminine plural, so celles; -ci means 'these (ones)'."},{"id":"pron-demonstrative-11","type":"transform","instruction":"Replace the words in bold with a demonstrative pronoun.","prompt":"Je vais acheter **ce sac-ci**.","answers":["Je vais acheter celui-ci."],"en":"I'm going to buy this one.","why":"sac is masculine singular, so ce sac-ci becomes celui-ci."},{"id":"pron-demonstrative-12","type":"flip","front":"What do celui qui and celui que mean?","back":"The one who / that. Use qui when a verb follows, que when a subject follows: celle qui chante (the one who is singing), celui que je préfère (the one I prefer), ceux qui recyclent (those who recycle)."},{"id":"pron-demonstrative-13","type":"gap","prompt":"J'ai deux sœurs : ___ qui habite à Londres s'appelle Emma.","hint":"(the one)","answers":["celle"],"en":"I have two sisters: the one who lives in London is called Emma.","why":"It refers to one sister (feminine singular), so celle; celle qui = the one who."},{"id":"pron-demonstrative-14","type":"gap","prompt":"J'aime bien les films d'action, mais ___ que je préfère, ce sont les comédies.","hint":"(the ones)","answers":["ceux"],"en":"I quite like action films, but the ones I prefer are comedies.","why":"It refers to films (masculine plural), so ceux; ceux que = the ones that."},{"id":"pron-demonstrative-15","type":"gap","prompt":"___ qui fument mettent leur santé en danger.","hint":"(those)","answers":["Ceux"],"en":"Those who smoke put their health at risk.","why":"For people in general, 'those who' is ceux qui (masculine plural)."},{"id":"pron-demonstrative-16","type":"flip","front":"How do you say 'my brother's' or 'Léa's' without repeating the noun?","back":"celui / celle / ceux / celles + de: Ce n'est pas mon vélo, c'est celui de mon frère (my brother's). Mes notes sont meilleures que celles de Léa (Léa's). French has no 's, so de shows who owns it."},{"id":"pron-demonstrative-17","type":"transform","instruction":"Replace the words in bold with a demonstrative pronoun.","prompt":"Ma chambre est plus grande que **la chambre** de ma sœur.","answers":["Ma chambre est plus grande que celle de ma sœur."],"en":"My bedroom is bigger than my sister's.","why":"chambre is feminine singular, so la chambre de becomes celle de."},{"id":"pron-demonstrative-18","type":"gap","prompt":"Ce n'est pas mon portable, c'est ___ de Thomas.","hint":"(the one)","answers":["celui"],"en":"It's not my mobile, it's Thomas's.","why":"portable is masculine singular, so celui; celui de = the one belonging to."}]},{"id":"pron-possessive","order":19,"area":"Pronouns","title":"Possessive pronouns (le mien…)","spec":"Pronouns: possessive (e.g. le mien)","receptive":false,"summary":["Possessive pronouns mean mine, yours, his, hers, ours, theirs. They replace a possessive adjective + noun: mon vélo → le mien.","They agree with the thing owned, not with the owner: Paul a perdu sa clé → Paul a perdu la sienne.","mine: le mien, la mienne, les miens, les miennes. yours (tu): le tien, la tienne, les tiens, les tiennes. his / hers: le sien, la sienne, les siens, les siennes.","ours: le nôtre, la nôtre, les nôtres. yours (vous): le vôtre, la vôtre, les vôtres. theirs: le leur, la leur, les leurs.","le nôtre and le vôtre have a circumflex, unlike the adjectives notre and votre: notre maison → la nôtre.","le and les combine with à and de: à + le mien = au mien, à + les miens = aux miens, de + le mien = du mien.","After être you can also show ownership with à + emphatic pronoun: Ce livre est à moi (this book is mine)."],"cards":[{"id":"pron-possessive-01","type":"flip","front":"What is a possessive pronoun? Give an example.","back":"A word for mine, yours, his, hers, ours or theirs that replaces a possessive adjective + noun. It always includes le, la or les: Ce n'est pas ton stylo, c'est le mien (it's mine)."},{"id":"pron-possessive-02","type":"flip","front":"Give all four forms of mine, yours (tu) and his / hers.","back":"mine: le mien, la mienne, les miens, les miennes. yours (tu): le tien, la tienne, les tiens, les tiennes. his / hers: le sien, la sienne, les siens, les siennes. (Order: masc. sing., fem. sing., masc. pl., fem. pl.)"},{"id":"pron-possessive-03","type":"flip","front":"Give the forms of ours, yours (vous) and theirs.","back":"ours: le nôtre, la nôtre, les nôtres. yours (vous): le vôtre, la vôtre, les vôtres. theirs: le leur, la leur, les leurs. Note the circumflex on nôtre / vôtre, which the adjectives notre / votre do not have."},{"id":"pron-possessive-04","type":"gap","prompt":"Ta maison est grande, mais ___ est petite.","base":"le mien","answers":["la mienne"],"en":"Your house is big, but mine is small.","why":"It replaces ma maison (feminine singular), so le mien becomes la mienne."},{"id":"pron-possessive-05","type":"gap","prompt":"Tes parents sont stricts ? ___ sont plutôt sympas.","base":"le mien","answers":["Les miens"],"en":"Are your parents strict? Mine are quite nice.","why":"It replaces mes parents (masculine plural), so les miens."},{"id":"pron-possessive-06","type":"gap","prompt":"J'ai oublié ma calculatrice. Je peux emprunter ___ ?","base":"le tien","answers":["la tienne"],"en":"I've forgotten my calculator. Can I borrow yours?","why":"It replaces ta calculatrice (feminine singular), so le tien becomes la tienne."},{"id":"pron-possessive-07","type":"flip","front":"Does le sien mean 'his' or 'hers'?","back":"Either. Like son / sa / ses, it agrees with the thing owned, not the owner: Luc a pris sa veste → Luc a pris la sienne (his). Marie a pris son manteau → Marie a pris le sien (hers)."},{"id":"pron-possessive-08","type":"gap","prompt":"Ma sœur a apporté ses baskets, mais mon frère a oublié ___.","base":"le sien","answers":["les siennes"],"en":"My sister has brought her trainers, but my brother has forgotten his.","why":"It replaces ses baskets (une basket is feminine), so les siennes. It agrees with the trainers, not the owner: the owner is a boy, but the form is feminine."},{"id":"pron-possessive-09","type":"gap","prompt":"Notre école est moderne. Et ___ ?","base":"le vôtre","answers":["la vôtre"],"en":"Our school is modern. What about yours?","why":"It replaces votre école (feminine singular), so la vôtre, with a circumflex."},{"id":"pron-possessive-10","type":"gap","prompt":"Vos enfants sont sages, mais ___ sont bruyants !","base":"le nôtre","answers":["les nôtres"],"en":"Your children are well behaved, but ours are noisy!","why":"It replaces nos enfants (plural), so les nôtres, with a circumflex."},{"id":"pron-possessive-11","type":"gap","prompt":"Mes cousins ont une maison à la campagne ; ___ est plus grande que la nôtre.","base":"le leur","answers":["la leur"],"en":"My cousins have a house in the country; theirs is bigger than ours.","why":"It replaces leur maison (feminine singular, one house), so la leur."},{"id":"pron-possessive-12","type":"gap","prompt":"Ces places sont à nous ; ___ sont au fond de la salle.","base":"le leur","answers":["les leurs"],"en":"These seats are ours; theirs are at the back of the hall.","why":"It replaces leurs places (plural), so les leurs."},{"id":"pron-possessive-13","type":"flip","front":"What happens to le mien after à or de?","back":"le and les combine as usual: à + le mien = au mien, à + les miens = aux miens, de + le mien = du mien, de + les miens = des miens. la stays: à la mienne. Tu parles souvent à tes parents ? Moi, je parle tous les jours aux miens."},{"id":"pron-possessive-14","type":"gap","prompt":"Tu ressembles à ton père ? Moi, je ne ressemble pas du tout ___.","base":"le mien","hint":"(ressembler à)","answers":["au mien"],"en":"Do you look like your dad? I don't look like mine at all.","why":"ressembler is followed by à, and à + le mien combines to au mien."},{"id":"pron-possessive-15","type":"transform","instruction":"Replace the words in bold with a possessive pronoun.","prompt":"Ce n'est pas mon sac, c'est **ton sac**.","answers":["Ce n'est pas mon sac, c'est le tien."],"en":"It's not my bag, it's yours.","why":"ton sac is masculine singular, so it becomes le tien."},{"id":"pron-possessive-16","type":"transform","instruction":"Replace the words in bold with a possessive pronoun.","prompt":"Mes notes sont meilleures que **tes notes**.","answers":["Mes notes sont meilleures que les tiennes."],"en":"My marks are better than yours.","why":"tes notes is feminine plural, so it becomes les tiennes."},{"id":"pron-possessive-17","type":"transform","instruction":"Replace the words in bold with a possessive pronoun.","prompt":"Je préfère ma ville à **sa ville**.","answers":["Je préfère ma ville à la sienne."],"en":"I prefer my town to his (or hers).","why":"sa ville is feminine singular, so it becomes la sienne; à la does not combine."},{"id":"pron-possessive-18","type":"flip","front":"What is another way to say 'it's mine' after être?","back":"être à + emphatic pronoun: Ce portable est à moi (this mobile is mine). Also à toi, à lui, à elle, à nous, à vous, à eux, à elles. C'est à qui ? = Whose is it?"}]},{"id":"pron-relative","order":20,"area":"Pronouns","title":"Relative pronouns (qui, que, où, lequel, dont)","spec":"Pronouns: relative: qui, que, où, lequel, auquel, duquel, dont (R)","receptive":false,"summary":["Relative pronouns link two ideas and refer back to a noun: J'ai un frère qui s'appelle Hugo.","qui (who, which, that) is the subject of the next verb, so a verb follows it: la fille qui chante. qui never shortens.","que (who(m), which, that) is the object, so a subject + verb follows it: le film que j'ai vu. que becomes qu' before a vowel: le livre qu'il lit.","où means where, and also when after a time expression: la ville où j'habite, le jour où je suis né.","After a preposition, use lequel, laquelle, lesquels, lesquelles for things, agreeing with the noun: le stylo avec lequel j'écris. For people, use qui: l'ami avec qui je joue.","à + lequel = auquel (auxquels, auxquelles; à laquelle does not change): le concours auquel j'ai participé.","de + lequel = duquel (desquels, desquelles; de laquelle does not change), used after près de, à côté de, en face de: le parc près duquel j'habite.","dont means whose, of which or about which, and replaces de + noun: le garçon dont le père est pilote. You only need to recognise and translate it.","ce qui and ce que mean 'what' (the thing that): Ce qui m'intéresse, c'est la musique. Je fais ce que je veux."],"cards":[{"id":"pron-relative-01","type":"flip","front":"How do you choose between qui and que?","back":"qui is the subject, so a verb follows it: le prof qui parle. que is the object, so a subject + verb follows it: le prof que j'aime. Quick test: if the verb comes next (possibly after ne or an object pronoun: la fille qui me parle), use qui. que becomes qu' before a vowel (le cadeau qu'il a acheté); qui never shortens."},{"id":"pron-relative-02","type":"gap","prompt":"J'ai une sœur ___ joue du violon.","hint":"(who)","answers":["qui"],"en":"I have a sister who plays the violin.","why":"The next word is a verb (joue), so the relative pronoun is the subject: qui."},{"id":"pron-relative-03","type":"gap","prompt":"Le film ___ nous avons vu hier était nul.","hint":"(that / which)","answers":["que"],"en":"The film (that) we saw yesterday was rubbish.","why":"A subject (nous) follows, so the pronoun is the object of the verb: que."},{"id":"pron-relative-04","type":"transform","instruction":"Join the two sentences using qui or que.","prompt":"J'ai un chien. Il s'appelle Max.","answers":["J'ai un chien qui s'appelle Max."],"en":"I have a dog called Max.","why":"The dog is the subject of s'appelle, so qui replaces il."},{"id":"pron-relative-05","type":"transform","instruction":"Join the two sentences using qui or que.","prompt":"Voici le cadeau. Anna a acheté ce cadeau.","answers":["Voici le cadeau qu'Anna a acheté.","Voici le cadeau qu'a acheté Anna."],"en":"Here is the present (that) Anna bought.","why":"The present is the object of a acheté, so que; it shortens to qu' before the vowel of Anna."},{"id":"pron-relative-06","type":"flip","front":"What are the two meanings of the relative pronoun où?","back":"Where (place): le collège où je vais, la ville où elle habite. When (after a time expression such as le jour, l'année, le moment): le jour où je suis né, l'été où nous sommes allés en Italie. Never use quand after a time noun."},{"id":"pron-relative-07","type":"gap","prompt":"Je me souviens du jour ___ nous sommes arrivés en France.","hint":"(when)","answers":["où"],"en":"I remember the day (when) we arrived in France.","why":"After a time expression such as le jour, 'when' is où, not quand."},{"id":"pron-relative-08","type":"flip","front":"Which relative pronoun do you use after a preposition (avec, sur, pour, dans...)?","back":"For things: lequel (masc. sing.), laquelle (fem. sing.), lesquels (masc. pl.), lesquelles (fem. pl.), agreeing with the noun: la boîte dans laquelle..., les raisons pour lesquelles... For people, qui is usual: la fille avec qui je danse."},{"id":"pron-relative-09","type":"gap","prompt":"C'est le stylo avec ___ j'ai écrit ma lettre.","hint":"(which)","answers":["lequel"],"en":"It's the pen I wrote my letter with.","why":"After a preposition, a thing needs lequel; stylo is masculine singular."},{"id":"pron-relative-10","type":"gap","prompt":"La table sur ___ j'ai posé mon portable est cassée.","hint":"(which)","answers":["laquelle"],"en":"The table I put my phone on is broken.","why":"After the preposition sur, a feminine singular thing (table) needs laquelle."},{"id":"pron-relative-11","type":"gap","prompt":"Voici les raisons pour ___ je veux devenir médecin.","hint":"(which)","answers":["lesquelles"],"en":"Here are the reasons why I want to become a doctor.","why":"After pour, raisons (feminine plural) needs lesquelles."},{"id":"pron-relative-12","type":"flip","front":"What are auquel and duquel?","back":"à + lequel = auquel (auxquels, auxquelles; à laquelle unchanged), after verbs with à such as participer à, penser à: le match auquel j'ai assisté. de + lequel = duquel (desquels, desquelles; de laquelle unchanged), after près de, à côté de, en face de: l'hôtel en face duquel il y a un parc."},{"id":"pron-relative-13","type":"gap","prompt":"Le concours ___ j'ai participé était difficile.","hint":"(in which: participer à)","answers":["auquel"],"en":"The competition I took part in was difficult.","why":"participer is followed by à, and à + lequel (concours is masculine singular) combines to auquel."},{"id":"pron-relative-14","type":"gap","prompt":"Le parc près ___ nous habitons est très calme.","hint":"(which)","answers":["duquel"],"en":"The park we live near is very quiet.","why":"près de + lequel (parc is masculine singular) combines to près duquel."},{"id":"pron-relative-15","type":"flip","front":"What does dont mean? (Recognise it; you don't need to use it.)","back":"whose, of which, about which: it replaces de + noun. le garçon dont le père est pilote (the boy whose father is a pilot); le livre dont j'ai besoin (the book I need: avoir besoin de); la ville dont je parle (the town I'm talking about: parler de)."},{"id":"pron-relative-16","type":"flip","front":"Translate: Mon amie Inès, dont la mère est infirmière, veut travailler dans un hôpital.","back":"My friend Inès, whose mother is a nurse, wants to work in a hospital. (dont + noun = whose + noun.)"},{"id":"pron-relative-17","type":"flip","front":"What do ce qui and ce que mean, and how do you choose?","back":"Both mean 'what' (the thing that). ce qui is the subject, so a verb follows: Ce qui m'énerve, c'est le bruit. ce que is the object, so a subject + verb follows: Je ne sais pas ce que je veux faire."},{"id":"pron-relative-18","type":"gap","prompt":"Je ne comprends pas ___ tu dis.","hint":"(what)","answers":["ce que"],"en":"I don't understand what you're saying.","why":"'what' meaning 'the thing that' is ce que here, because a subject (tu) follows."}]},{"id":"pron-indefinite-interrogative","order":21,"area":"Pronouns","title":"Indefinite and interrogative pronouns","spec":"Pronouns: indefinite (e.g. quelqu'un); interrogative (e.g. qui, que)","receptive":false,"summary":["quelqu'un = someone / anyone; quelque chose = something / anything: Quelqu'un a appelé. Tu veux quelque chose ?","tout le monde (everybody) and chacun / chacune (each one) take a singular verb: Tout le monde est là. Chacun a son portable.","plusieurs = several; certains / certaines = some (people or things): Certains aiment le sport, d'autres préfèrent la lecture.","personne (nobody) and rien (nothing) need ne before the verb: Je ne vois personne. Il n'y a rien. As subject: Personne n'est venu. Rien ne marche.","In the perfect, rien goes before the past participle but personne goes after it: Je n'ai rien mangé. Je n'ai vu personne.","An adjective after quelque chose, rien, quelqu'un or personne takes de and stays masculine singular: quelque chose de nouveau, rien d'intéressant.","Questions: qui ? = who?, also after a preposition (Avec qui sors-tu ?); que + inversion or qu'est-ce que + subject + verb = what? (object): Que fais-tu ? Qu'est-ce que tu fais ?","qu'est-ce qui ? = what? when 'what' is the subject: Qu'est-ce qui se passe ? quoi = what after a preposition: De quoi as-tu besoin ?","lequel ? laquelle ? lesquels ? lesquelles ? = which one(s)?, agreeing with the noun: Voici deux robes. Laquelle préfères-tu ?"],"cards":[{"id":"pron-indefinite-interrogative-01","type":"flip","front":"What do quelqu'un, quelque chose, tout le monde, chacun, plusieurs and certains mean?","back":"quelqu'un = someone / anyone; quelque chose = something / anything; tout le monde = everybody (singular verb); chacun / chacune = each one; plusieurs = several; certains / certaines = some (of them). Tout le monde aime les vacances."},{"id":"pron-indefinite-interrogative-02","type":"gap","prompt":"Il y a ___ à la porte !","hint":"(someone)","answers":["quelqu'un"],"en":"There's someone at the door!","why":"'someone' is quelqu'un: one word, with an apostrophe."},{"id":"pron-indefinite-interrogative-03","type":"gap","prompt":"En été, ___ va à la plage.","hint":"(everybody)","answers":["tout le monde"],"en":"In summer everybody goes to the beach.","why":"'everybody' is tout le monde, which takes a singular verb: va."},{"id":"pron-indefinite-interrogative-04","type":"gap","prompt":"Mes deux sœurs ont un vélo ; ___ a le sien.","hint":"(each one)","answers":["chacune"],"en":"My two sisters have a bike; each one has her own.","why":"'each one' is chacun, which becomes chacune for females and takes a singular verb."},{"id":"pron-indefinite-interrogative-05","type":"gap","prompt":"J'ai invité dix amis, mais ___ n'ont pas pu venir.","hint":"(several)","answers":["plusieurs"],"en":"I invited ten friends, but several couldn't come.","why":"'several' is plusieurs, which never changes and takes a plural verb."},{"id":"pron-indefinite-interrogative-06","type":"flip","front":"How do you use personne (nobody) and rien (nothing)?","back":"Both need ne before the verb: Je ne connais personne. Il ne fait rien. As the subject they come first: Personne ne m'a appelé. Rien n'est gratuit. In the perfect, rien goes before the participle (je n'ai rien fait), personne after it (je n'ai vu personne)."},{"id":"pron-indefinite-interrogative-07","type":"transform","instruction":"Make the sentence negative by replacing the words in bold with ne ... rien.","prompt":"Il mange **quelque chose**.","answers":["Il ne mange rien."],"en":"He doesn't eat anything.","why":"ne goes before the verb and rien replaces quelque chose after it."},{"id":"pron-indefinite-interrogative-08","type":"transform","instruction":"Make the sentence negative by replacing the words in bold with ne ... rien.","prompt":"J'ai acheté **quelque chose** au marché.","answers":["Je n'ai rien acheté au marché."],"en":"I didn't buy anything at the market.","why":"In the perfect, ne ... rien goes round avoir, so rien comes before the participle: je n'ai rien acheté."},{"id":"pron-indefinite-interrogative-09","type":"transform","instruction":"Make the sentence negative by replacing the words in bold with ne ... personne.","prompt":"Nous avons rencontré **quelqu'un** en ville.","answers":["Nous n'avons rencontré personne en ville."],"en":"We didn't meet anyone in town.","why":"Unlike rien, personne goes after the past participle: nous n'avons rencontré personne."},{"id":"pron-indefinite-interrogative-10","type":"gap","prompt":"___ n'est venu à ma fête.","hint":"(nobody)","answers":["Personne"],"en":"Nobody came to my party.","why":"As a subject, personne comes first and still needs ne before the verb (no pas): Personne n'est venu."},{"id":"pron-indefinite-interrogative-11","type":"gap","prompt":"Ma mère a préparé quelque chose de ___ pour le dîner.","base":"délicieux","answers":["délicieux"],"en":"My mum has made something delicious for dinner.","why":"After quelque chose de, the adjective stays masculine singular, even though chose looks feminine."},{"id":"pron-indefinite-interrogative-12","type":"flip","front":"How do you ask 'who?' and 'what?' in French?","back":"Who? qui: Qui parle ? Qui as-tu vu ? What? (object): que + inversion (Que fais-tu ?) or qu'est-ce que + subject + verb (Qu'est-ce que tu fais ?). What? (subject): qu'est-ce qui + verb (Qu'est-ce qui se passe ?). After a preposition: quoi (Avec quoi ? De quoi parles-tu ?)."},{"id":"pron-indefinite-interrogative-13","type":"gap","prompt":"___ tu fais ce week-end ?","hint":"(what)","answers":["Qu'est-ce que"],"en":"What are you doing this weekend?","why":"A subject + verb follows with no inversion, so 'what' (object) is qu'est-ce que."},{"id":"pron-indefinite-interrogative-14","type":"gap","prompt":"___ fais-tu après les cours ?","hint":"(what)","answers":["Que"],"en":"What do you do after lessons?","why":"The verb and subject are inverted (fais-tu), so 'what' (object) is que."},{"id":"pron-indefinite-interrogative-15","type":"gap","prompt":"___ s'est passé hier soir ?","hint":"(what)","answers":["Qu'est-ce qui"],"en":"What happened last night?","why":"'what' is the subject of the verb here, so it is qu'est-ce qui."},{"id":"pron-indefinite-interrogative-16","type":"gap","prompt":"De ___ avez-vous besoin ?","hint":"(what)","answers":["quoi"],"en":"What do you need?","why":"After a preposition (de), 'what' is quoi."},{"id":"pron-indefinite-interrogative-17","type":"flip","front":"How do you ask 'which one?' or 'which ones?'","back":"lequel ? (masc. sing.), laquelle ? (fem. sing.), lesquels ? (masc. pl.), lesquelles ? (fem. pl.), agreeing with the noun meant: Voici deux robes. Laquelle préfères-tu ? Tu as vu ses films ? Lesquels ?"},{"id":"pron-indefinite-interrogative-18","type":"gap","prompt":"J'ai deux pulls, un rouge et un vert. ___ préfères-tu ?","hint":"(which one)","answers":["Lequel"],"en":"I've got two jumpers, a red one and a green one. Which one do you prefer?","why":"'which one' refers to un pull (masculine singular), so lequel."},{"id":"pron-indefinite-interrogative-19","type":"gap","prompt":"Avec ___ vas-tu au concert samedi ?","hint":"(who)","answers":["qui"],"en":"Who are you going to the concert with on Saturday?","why":"'who' is qui, even after a preposition: avec qui ? quoi is only for things: avec quoi ? (with what?)."}]},{"id":"verbs-present","order":22,"area":"Verbs","title":"Present tense (regular and irregular)","spec":"Verbs: regular and irregular forms of verbs; all persons of verbs, singular and plural; tenses: present","receptive":false,"summary":["Regular -er verbs: drop -er and add -e, -es, -e, -ons, -ez, -ent: je joue, nous jouons, ils jouent.","Regular -ir verbs (like finir): -is, -is, -it, -issons, -issez, -issent: je finis, nous finissons, elles choisissent.","Regular -re verbs (like vendre): -s, -s, no ending, -ons, -ez, -ent: je vends, il vend, nous attendons, ils répondent.","Learn the key irregulars by heart: être (je suis, nous sommes, ils sont), avoir (j'ai, ils ont), aller (je vais, ils vont), faire (je fais, vous faites, ils font).","pouvoir, vouloir, devoir and savoir are irregular and are followed by an infinitive: je peux sortir, ils veulent partir, nous devons travailler, elle sait nager.","prendre: je prends, nous prenons, ils prennent (apprendre and comprendre work the same). venir: je viens, nous venons, ils viennent (devenir and revenir work the same).","sortir, partir and dormir lose their last stem consonant in the singular: je sors, il part, tu dors; but nous sortons, ils partent, ils dorment.","Spelling changes keep the sound: -ger verbs add e before -ons (nous mangeons) and -cer verbs take ç before -ons (nous commençons).","acheter, appeler and préférer change their stem when the ending is silent (je, tu, il, ils): j'achète, il appelle, ils préfèrent; but nous achetons, vous appelez, nous préférons.","The present means 'I play', 'I am playing' and 'I do play'. With depuis it means 'have been doing': J'apprends le français depuis cinq ans."],"cards":[{"id":"verbs-present-01","type":"flip","front":"How do you form the present tense of a regular -er verb like jouer?","back":"Remove -er and add -e, -es, -e, -ons, -ez, -ent: je joue, tu joues, il/elle/on joue, nous jouons, vous jouez, ils/elles jouent. The -e, -es and -ent endings are all silent."},{"id":"verbs-present-02","type":"gap","prompt":"Le samedi, mes parents ___ au tennis avec leurs amis.","base":"jouer","answers":["jouent"],"en":"On Saturdays my parents play tennis with their friends.","why":"Regular -er verb with a plural subject (mes parents = ils): stem jou- + -ent."},{"id":"verbs-present-03","type":"flip","front":"What are the present-tense endings of regular -ir and -re verbs?","back":"-ir (finir): je finis, tu finis, il finit, nous finissons, vous finissez, ils finissent. -re (vendre): je vends, tu vends, il vend, nous vendons, vous vendez, ils vendent. Watch out: the il/elle form of -re verbs has no ending at all (il vend)."},{"id":"verbs-present-04","type":"gap","prompt":"À la cantine, nous ___ toujours le menu végétarien.","base":"choisir","answers":["choisissons"],"en":"In the canteen we always choose the vegetarian menu.","why":"Regular -ir verbs add -iss- in the plural: nous choisissons."},{"id":"verbs-present-05","type":"gap","prompt":"Mon frère ___ le bus devant la poste tous les matins.","base":"attendre","answers":["attend"],"en":"My brother waits for the bus outside the post office every morning.","why":"Regular -re verb: the il/elle form is just the stem with no ending: il attend."},{"id":"verbs-present-06","type":"flip","front":"Give the present tense of être, avoir, aller and faire for je, nous and ils.","back":"être: je suis, nous sommes, ils sont. avoir: j'ai, nous avons, ils ont. aller: je vais, nous allons, ils vont. faire: je fais, nous faisons, ils font (and vous faites, never 'faisez')."},{"id":"verbs-present-07","type":"gap","prompt":"Mes cousins ___ en vacances en Espagne chaque été.","base":"aller","answers":["vont"],"en":"My cousins go on holiday to Spain every summer.","why":"aller is irregular: ils/elles vont."},{"id":"verbs-present-08","type":"gap","prompt":"Qu'est-ce que vous ___ le week-end ?","base":"faire","answers":["faites"],"en":"What do you do at the weekend?","why":"faire is irregular in the vous form: vous faites (like vous êtes and vous dites)."},{"id":"verbs-present-09","type":"flip","front":"Give the present of pouvoir, vouloir, devoir and savoir. What follows them?","back":"pouvoir: je peux, il peut, nous pouvons, ils peuvent. vouloir: je veux, il veut, nous voulons, ils veulent. devoir: je dois, il doit, nous devons, ils doivent. savoir: je sais, il sait, nous savons, ils savent. All four are followed by an infinitive: Je dois partir. Elle sait nager."},{"id":"verbs-present-10","type":"gap","prompt":"Les élèves ne ___ pas utiliser leur portable en classe.","base":"pouvoir","answers":["peuvent"],"en":"Pupils can't use their mobile phones in class.","why":"pouvoir is irregular: ils peuvent. The second verb (utiliser) stays in the infinitive."},{"id":"verbs-present-11","type":"gap","prompt":"Ma petite sœur ne ___ pas encore nager.","base":"savoir","answers":["sait"],"en":"My little sister can't swim yet.","why":"savoir: je sais, tu sais, il/elle sait. savoir + infinitive means 'to know how to'."},{"id":"verbs-present-12","type":"gap","prompt":"Le matin, nous ___ le train de sept heures pour aller au lycée.","base":"prendre","answers":["prenons"],"en":"In the morning we take the seven o'clock train to go to school.","why":"prendre: nous prenons with one n; only ils/elles prennent has two."},{"id":"verbs-present-13","type":"gap","prompt":"Mes grands-parents ___ nous voir tous les dimanches.","base":"venir","answers":["viennent"],"en":"My grandparents come to see us every Sunday.","why":"venir: ils viennent (stem vienn- + -ent). Only nous venons and vous venez keep the ven- stem."},{"id":"verbs-present-14","type":"gap","prompt":"Le vendredi soir, je ___ avec mes copains.","base":"sortir","answers":["sors"],"en":"On Friday evenings I go out with my friends.","why":"sortir drops the t in the singular: je sors, tu sors, il sort; the plural keeps it: nous sortons, ils sortent."},{"id":"verbs-present-15","type":"flip","front":"Give the je, nous and ils forms of mettre, dire, voir, lire, écrire and boire.","back":"mettre: je mets, nous mettons, ils mettent. dire: je dis, nous disons, ils disent (vous dites). voir: je vois, nous voyons, ils voient. lire: je lis, nous lisons, ils lisent. écrire: j'écris, nous écrivons, ils écrivent. boire: je bois, nous buvons, ils boivent."},{"id":"verbs-present-16","type":"transform","instruction":"Rewrite the sentence with nous as the subject.","prompt":"Je mets la table et j'écris le menu.","answers":["Nous mettons la table et nous écrivons le menu.","Nous mettons la table et écrivons le menu."],"en":"We lay the table and write the menu.","why":"mettre: nous mettons (double t); écrire adds a v in the plural: nous écrivons."},{"id":"verbs-present-17","type":"transform","instruction":"Rewrite the sentence with ils as the subject.","prompt":"Il boit du thé et lit le journal.","answers":["Ils boivent du thé et lisent le journal.","Ils boivent du thé et ils lisent le journal."],"en":"They drink tea and read the newspaper.","why":"boire: il boit → ils boivent; lire: il lit → ils lisent (an s appears in the plural)."},{"id":"verbs-present-18","type":"flip","front":"Which verbs change their spelling in the present tense, and why?","back":"-ger verbs add e before -ons to keep the soft g: nous mangeons, nous nageons. -cer verbs use ç before -ons to keep the soft c: nous commençons. acheter, appeler and préférer change the stem when the ending is silent (je, tu, il, ils): j'achète, il appelle, ils préfèrent; but nous achetons, vous appelez, nous préférons."},{"id":"verbs-present-19","type":"gap","prompt":"Nous ___ au restaurant italien le vendredi soir.","base":"manger","answers":["mangeons"],"en":"We eat at the Italian restaurant on Friday evenings.","why":"-ger verbs keep an e before -ons so the g stays soft: nous mangeons."},{"id":"verbs-present-20","type":"gap","prompt":"Nous ___ les cours à huit heures et demie.","base":"commencer","answers":["commençons"],"en":"We start lessons at half past eight.","why":"-cer verbs need ç before o to keep the soft s sound: nous commençons."},{"id":"verbs-present-21","type":"gap","prompt":"Ma mère ___ toujours des légumes bio au marché.","base":"acheter","answers":["achète"],"en":"My mother always buys organic vegetables at the market.","why":"acheter takes a grave accent when the ending is silent: elle achète (but nous achetons)."},{"id":"verbs-present-22","type":"gap","prompt":"Mon frère ___ souvent ses amis le soir.","base":"appeler","answers":["appelle"],"en":"My brother often phones his friends in the evening.","why":"appeler doubles the l when the ending is silent: il appelle (but nous appelons)."},{"id":"verbs-present-23","type":"gap","prompt":"Mes amis ___ le foot au rugby.","base":"préférer","answers":["préfèrent"],"en":"My friends prefer football to rugby.","why":"The second é of préférer becomes è when the ending is silent: ils préfèrent (but vous préférez)."},{"id":"verbs-present-24","type":"gap","prompt":"Mon frère et moi, nous ___ l'espagnol depuis deux ans.","base":"apprendre","answers":["apprenons"],"en":"My brother and I have been learning Spanish for two years.","why":"depuis + present tense describes something that started in the past and is still going on. apprendre works like prendre: nous apprenons."}]},{"id":"verbs-negatives","order":23,"area":"Verbs","title":"Negative forms","spec":"Verbs: negative forms","receptive":false,"summary":["ne goes before the verb and pas goes after it: Je ne mange pas de viande. ne becomes n' before a vowel or silent h: Il n'aime pas le sport.","Other negatives work the same way: ne...jamais (never), ne...plus (no longer), ne...rien (nothing), ne...personne (nobody), ne...que (only), ne...pas encore (not yet), ne...aucun(e) (no, not a single), ne...ni...ni (neither...nor).","After a negative, un, une, du, de la, de l' and des become de (d' before a vowel): J'ai un chien → Je n'ai pas de chien. Il boit du café → Il ne boit jamais de café.","le, la, l' and les do not change: Je n'aime pas les maths. After être the article stays too: Ce n'est pas un problème.","ne...que is not a true negative, so the article stays: Je ne mange que des légumes.","In the perfect tense the negative goes round the auxiliary: Je n'ai pas fini. Elle n'est jamais allée en France. Nous n'avons rien acheté.","But personne, que, aucun(e) and ni...ni go after the past participle: Je n'ai vu personne. Il n'a mangé qu'une pomme.","Object and reflexive pronouns stay next to the verb, inside the negative: Je ne le vois pas. Je ne l'ai pas vu. Elle ne se lève jamais tôt.","Before an infinitive, both parts go together in front of it: Ne pas fumer. J'ai décidé de ne plus manger de viande.","personne and rien can be the subject: Personne n'est venu. Rien ne marche. They can also be one-word answers: Qu'est-ce que tu fais ? – Rien."],"cards":[{"id":"verbs-negatives-01","type":"flip","front":"Where do ne and pas go in a present-tense sentence?","back":"Round the conjugated verb: ne before, pas after. Je ne regarde pas la télé. ne shortens to n' before a vowel or silent h: Nous n'habitons pas en ville."},{"id":"verbs-negatives-02","type":"transform","instruction":"Make this sentence negative using ne...pas.","prompt":"Mon frère aime les maths.","answers":["Mon frère n'aime pas les maths."],"en":"My brother doesn't like maths.","why":"ne becomes n' before the vowel of aime. les is a definite article, so it does not change after the negative."},{"id":"verbs-negatives-03","type":"flip","front":"What do ne...jamais, ne...plus, ne...rien, ne...personne, ne...que, ne...pas encore, ne...aucun(e) and ne...ni...ni mean?","back":"never; no longer / not any more; nothing; nobody; only; not yet; no / not a single; neither...nor. Je ne fume jamais. Il ne travaille plus. Je ne fais rien. Je ne connais personne. Elle n'a que dix euros. Je n'ai pas encore mangé. Il n'a aucun ami. Je n'aime ni le thé ni le café."},{"id":"verbs-negatives-04","type":"flip","front":"What happens to un, une, du, de la and des after a negative?","back":"They all become de (d' before a vowel): J'ai une sœur → Je n'ai pas de sœur. Il mange du pain → Il ne mange pas de pain. Nous avons des animaux → Nous n'avons pas d'animaux. Exceptions: le, la, les never change (Je n'aime pas les carottes), and after être or ne...que the article stays (Ce n'est pas un problème)."},{"id":"verbs-negatives-05","type":"transform","instruction":"Make this sentence negative using ne...pas.","prompt":"Il y a une piscine dans mon village.","answers":["Il n'y a pas de piscine dans mon village."],"en":"There isn't a swimming pool in my village.","why":"With il y a, n' goes before y and pas after a. une becomes de after the negative."},{"id":"verbs-negatives-06","type":"transform","instruction":"Make this sentence negative using ne...plus.","prompt":"Mon père boit du café.","answers":["Mon père ne boit plus de café."],"en":"My father doesn't drink coffee any more.","why":"ne...plus goes round the verb, and du becomes de after a negative."},{"id":"verbs-negatives-07","type":"transform","instruction":"Rewrite the sentence using ne...que instead of seulement.","prompt":"Elle mange seulement des légumes.","answers":["Elle ne mange que des légumes."],"en":"She only eats vegetables.","why":"ne...que means 'only' and que goes directly before the thing it limits. It is not a true negative, so des does not change to de."},{"id":"verbs-negatives-08","type":"transform","instruction":"Make this sentence negative using ne...aucun(e).","prompt":"J'ai une idée.","answers":["Je n'ai aucune idée."],"en":"I have no idea.","why":"aucun(e) replaces the article and agrees with the noun: idée is feminine, so aucune."},{"id":"verbs-negatives-09","type":"transform","instruction":"Make this sentence negative using ne...ni...ni.","prompt":"Il aime le thé et le café.","answers":["Il n'aime ni le thé ni le café."],"en":"He likes neither tea nor coffee.","why":"ne goes before the verb and ni replaces et, going before each noun. The definite articles stay."},{"id":"verbs-negatives-10","type":"flip","front":"Where does the negative go in the perfect tense?","back":"Round the auxiliary (avoir or être): Je n'ai pas mangé. Elle n'est jamais venue. Nous n'avons rien acheté. BUT personne, que, aucun(e) and ni...ni go after the past participle: Je n'ai vu personne. Il n'a mangé qu'une pomme."},{"id":"verbs-negatives-11","type":"transform","instruction":"Make this sentence negative using ne...pas encore.","prompt":"J'ai fini mes devoirs.","answers":["Je n'ai pas encore fini mes devoirs."],"en":"I haven't finished my homework yet.","why":"In the perfect tense, ne...pas encore goes round the auxiliary: n'ai pas encore + fini."},{"id":"verbs-negatives-12","type":"transform","instruction":"Make this sentence negative using ne...jamais.","prompt":"Nous sommes allés en Italie.","answers":["Nous ne sommes jamais allés en Italie."],"en":"We have never been to Italy.","why":"jamais goes between the auxiliary (sommes) and the past participle (allés)."},{"id":"verbs-negatives-13","type":"transform","instruction":"Make this sentence negative using ne...rien (rien replaces quelque chose).","prompt":"Elle a acheté quelque chose au marché.","answers":["Elle n'a rien acheté au marché."],"en":"She didn't buy anything at the market.","why":"rien behaves like pas: it goes between the auxiliary and the past participle."},{"id":"verbs-negatives-14","type":"transform","instruction":"Make this sentence negative using ne...personne (personne replaces quelqu'un).","prompt":"J'ai vu quelqu'un dans le parc.","answers":["Je n'ai vu personne dans le parc."],"en":"I didn't see anyone in the park.","why":"Unlike pas and rien, personne goes after the past participle: n'ai vu personne."},{"id":"verbs-negatives-15","type":"transform","instruction":"Make this sentence negative using ne...pas.","prompt":"Je l'ai invitée à ma fête.","answers":["Je ne l'ai pas invitée à ma fête."],"en":"I didn't invite her to my party.","why":"The object pronoun stays attached to the auxiliary: ne + l' + ai + pas + participle."},{"id":"verbs-negatives-16","type":"transform","instruction":"Make this sentence negative using ne...jamais.","prompt":"Mon frère se lève tôt le dimanche.","answers":["Mon frère ne se lève jamais tôt le dimanche."],"en":"My brother never gets up early on Sundays.","why":"With a reflexive verb, ne goes before the reflexive pronoun: ne se lève jamais."},{"id":"verbs-negatives-17","type":"flip","front":"How do you make an infinitive negative?","back":"Put both parts of the negative together in front of the infinitive: Ne pas fumer. Ne pas marcher sur la pelouse. J'ai décidé de ne plus manger de viande. J'essaie de ne jamais arriver en retard."},{"id":"verbs-negatives-18","type":"transform","instruction":"Make the infinitive negative using ne pas.","prompt":"Le prof nous demande de parler en classe.","answers":["Le prof nous demande de ne pas parler en classe."],"en":"The teacher asks us not to talk in class.","why":"Before an infinitive, ne pas goes together in front of it: de ne pas parler."}]},{"id":"verbs-questions","order":24,"area":"Verbs","title":"Asking questions","spec":"Verbs: interrogative forms","receptive":false,"summary":["Intonation: say a statement with a rising voice and add a question mark: Tu viens ce soir ? It is informal but very common in speech.","est-ce que in front of a statement makes a question: Est-ce que tu viens ce soir ? Before a vowel it becomes est-ce qu': Est-ce qu'il pleut ?","Inversion: swap the subject pronoun and the verb and join them with a hyphen: Viens-tu ce soir ? Aimez-vous le sport ?","If the verb ends in a vowel and the pronoun is il, elle or on, add -t- between them: A-t-il un frère ? Va-t-elle au marché ? Parle-t-on anglais ici ?","With a noun subject, keep the noun first and add a pronoun after the verb: Ton frère joue-t-il au foot ? Or use est-ce que: Est-ce que ton frère joue au foot ?","Question words go first, followed by est-ce que or inversion: Où est-ce que tu habites ? Où habites-tu ? Quand pars-tu ? Pourquoi est-ce qu'il pleure ?","Qu'est-ce que = what (as the object), with normal word order: Qu'est-ce que tu fais ? With inversion use que: Que fais-tu ? Qu'est-ce qui = what (as the subject): Qu'est-ce qui se passe ?","In the perfect tense, invert the auxiliary only: As-tu fini ? Est-elle partie ? A-t-il mangé ?","In casual speech the question word may come at the end (Tu habites où ?), but in written answers use est-ce que or inversion."],"cards":[{"id":"verbs-questions-01","type":"flip","front":"What are the three ways to turn 'Tu aimes le sport.' into a yes/no question?","back":"1 Intonation: Tu aimes le sport ? 2 est-ce que: Est-ce que tu aimes le sport ? 3 Inversion: Aimes-tu le sport ? All three mean 'Do you like sport?'. Intonation is the most informal; inversion the most formal."},{"id":"verbs-questions-02","type":"transform","instruction":"Turn this statement into a question using est-ce que.","prompt":"Tu as un animal.","answers":["Est-ce que tu as un animal ?"],"en":"Do you have a pet?","why":"Put est-ce que in front of the statement; the word order does not change."},{"id":"verbs-questions-03","type":"transform","instruction":"Turn this statement into a question using est-ce que.","prompt":"Il fait beau aujourd'hui.","answers":["Est-ce qu'il fait beau aujourd'hui ?"],"en":"Is the weather nice today?","why":"que elides to qu' before a vowel: est-ce qu'il."},{"id":"verbs-questions-04","type":"flip","front":"How does inversion work, and when do you add -t-?","back":"Swap the subject pronoun and the verb and add a hyphen: Vous parlez → Parlez-vous ? If the verb ends in a vowel and the pronoun is il, elle or on, insert -t-: Il a → A-t-il ? Elle va → Va-t-elle ? On mange → Mange-t-on ? No -t- if the verb already ends in -t or -d: Est-il ? Prend-elle ? Inversion is avoided with je, except in set phrases like Puis-je... ?"},{"id":"verbs-questions-05","type":"transform","instruction":"Turn this statement into a question using inversion.","prompt":"Vous habitez près d'ici.","answers":["Habitez-vous près d'ici ?"],"en":"Do you live near here?","why":"Swap the pronoun and the verb and join them with a hyphen: Habitez-vous."},{"id":"verbs-questions-06","type":"transform","instruction":"Turn this statement into a question using inversion.","prompt":"Elle a une sœur.","answers":["A-t-elle une sœur ?"],"en":"Does she have a sister?","why":"a ends in a vowel, so -t- is added before elle to make it easier to say: A-t-elle."},{"id":"verbs-questions-07","type":"transform","instruction":"Turn this statement into a question using inversion.","prompt":"Il joue au tennis.","answers":["Joue-t-il au tennis ?"],"en":"Does he play tennis?","why":"joue ends in a vowel, so -t- goes between the verb and il: Joue-t-il."},{"id":"verbs-questions-08","type":"flip","front":"Give the French for: where, when, how, why, how much / how many, who, what, which.","back":"où, quand, comment, pourquoi, combien (de + noun), qui, que / qu'est-ce que (quoi after a preposition), quel / quelle / quels / quelles + noun. Remember the accent on où: ou without it means 'or'."},{"id":"verbs-questions-09","type":"gap","prompt":"___ est-ce que tu vas au collège ? – En bus.","hint":"(how)","answers":["Comment"],"en":"How do you get to school? – By bus.","why":"comment = how. The question word goes first, followed by est-ce que and normal word order."},{"id":"verbs-questions-10","type":"gap","prompt":"___ habites-tu ? – À Lyon.","hint":"(where)","answers":["Où"],"en":"Where do you live? – In Lyon.","why":"où = where, followed here by inversion (habites-tu). It needs its grave accent: ou means 'or'."},{"id":"verbs-questions-11","type":"gap","prompt":"___ de frères et sœurs as-tu ?","hint":"(how many)","answers":["Combien"],"en":"How many brothers and sisters do you have?","why":"combien de + noun = how many / how much. de does not change for masculine, feminine or plural nouns, but it becomes d' before a vowel: combien d'élèves."},{"id":"verbs-questions-12","type":"flip","front":"qu'est-ce que, que, qu'est-ce qui, quoi: what's the difference?","back":"All mean 'what'. qu'est-ce que + normal word order: Qu'est-ce que tu manges ? que + inversion: Que manges-tu ? qu'est-ce qui when 'what' is the subject of the verb: Qu'est-ce qui se passe ? quoi after a preposition: À quoi penses-tu ? De quoi parles-tu ?"},{"id":"verbs-questions-13","type":"gap","prompt":"___ tu fais le week-end ?","hint":"(what)","answers":["Qu'est-ce que"],"en":"What do you do at the weekend?","why":"The word order after the gap is normal (tu fais), so 'what' must be qu'est-ce que. que on its own needs inversion: Que fais-tu ?"},{"id":"verbs-questions-14","type":"transform","instruction":"Rewrite the question using inversion.","prompt":"Qu'est-ce que tu manges à midi ?","answers":["Que manges-tu à midi ?"],"en":"What do you eat at lunchtime?","why":"With inversion, qu'est-ce que becomes que and the pronoun follows the verb: Que manges-tu."},{"id":"verbs-questions-15","type":"transform","instruction":"Make a question using the question word in brackets. Use est-ce que or inversion.","prompt":"Tu pars en vacances. (quand)","answers":["Quand est-ce que tu pars en vacances ?","Quand pars-tu en vacances ?"],"en":"When are you going on holiday?","why":"The question word goes first, then either est-ce que + normal order or inversion."},{"id":"verbs-questions-16","type":"transform","instruction":"Make a question using the words in brackets. Use est-ce que or inversion.","prompt":"Il arrive. (à quelle heure)","answers":["À quelle heure est-ce qu'il arrive ?","À quelle heure arrive-t-il ?"],"en":"What time is he arriving?","why":"est-ce que elides before il (est-ce qu'il); with inversion, arrive ends in a vowel so -t- is added: arrive-t-il."},{"id":"verbs-questions-17","type":"transform","instruction":"Turn this statement into a question using inversion.","prompt":"Tu as fini tes devoirs.","answers":["As-tu fini tes devoirs ?"],"en":"Have you finished your homework?","why":"In the perfect tense, only the auxiliary is inverted: As-tu + fini."},{"id":"verbs-questions-18","type":"transform","instruction":"Turn this statement into a question using inversion.","prompt":"Ta sœur aime la musique.","answers":["Ta sœur aime-t-elle la musique ?"],"en":"Does your sister like music?","why":"With a noun subject, keep the noun first and add the matching pronoun after the verb; aime ends in a vowel, so add -t-: aime-t-elle."}]},{"id":"verbs-impersonal","order":25,"area":"Verbs","title":"Impersonal verbs (il faut, il y a…)","spec":"Verbs: impersonal verbs (e.g. il faut)","receptive":false,"summary":["Impersonal verbs are only used with il, which means 'it' or 'there', never 'he': il faut, il pleut, il y a.","il faut + infinitive = you must / we must / it is necessary to: Il faut recycler le plastique. il ne faut pas = you mustn't: Il ne faut pas jeter les déchets par terre.","il faut + noun = you need: Il faut un passeport pour voyager. Past: il fallait; future: il faudra.","il y a = there is / there are: Il y a un cinéma en ville. Past description: il y avait; future: il y aura; negative: il n'y a pas de...","il y a + a length of time = ago: Je suis arrivé ici il y a deux ans.","Weather: il pleut, il neige, il fait beau / chaud / froid / mauvais, il y a du vent / du soleil. Past: il pleuvait, il faisait beau; future: il pleuvra, il fera chaud.","il est + adjective + de + infinitive = it is ... to ...: Il est important de manger équilibré. Il est difficile de trouver un emploi.","il vaut mieux + infinitive = it's better to: Il vaut mieux prendre le train.","il reste = there is / are ... left (always singular): Il reste deux places. il s'agit de = it's about: Dans ce livre, il s'agit d'une famille pauvre."],"cards":[{"id":"verbs-impersonal-01","type":"flip","front":"What does il faut mean, and what follows it?","back":"It means 'you must / we must / it is necessary to' and never changes for the person. Followed by an infinitive: Il faut protéger l'environnement. Followed by a noun it means 'you need': Il faut un billet pour entrer."},{"id":"verbs-impersonal-02","type":"gap","prompt":"Il ___ éteindre la lumière quand on quitte une pièce.","base":"falloir","hint":"(present tense)","answers":["faut"],"en":"You must switch off the light when you leave a room.","why":"falloir is only used with il. In the present it is il faut, followed by an infinitive."},{"id":"verbs-impersonal-03","type":"transform","instruction":"Rewrite the sentence using il ne faut pas + infinitive.","prompt":"On ne doit pas fumer ici.","answers":["Il ne faut pas fumer ici."],"en":"You mustn't smoke here.","why":"il ne faut pas + infinitive means 'you mustn't': ne...pas goes round faut."},{"id":"verbs-impersonal-04","type":"gap","prompt":"Demain, il ___ partir à six heures pour prendre l'avion.","base":"falloir","hint":"(simple future)","answers":["faudra"],"en":"Tomorrow we'll have to leave at six to catch the plane.","why":"The simple future of il faut is il faudra; demain points to the future."},{"id":"verbs-impersonal-05","type":"gap","prompt":"Quand j'étais à l'école primaire, il ___ porter un uniforme.","base":"falloir","answers":["fallait"],"en":"When I was at primary school, we had to wear a uniform.","why":"A rule that applied over a period in the past → imperfect: il fallait."},{"id":"verbs-impersonal-06","type":"flip","front":"What do il y a, il y avait and il y aura mean?","back":"il y a = there is / there are; il y avait = there was / there were (imperfect, for description); il y aura = there will be. Negative: il n'y a pas de... With a length of time, il y a means 'ago': il y a trois ans = three years ago."},{"id":"verbs-impersonal-07","type":"gap","prompt":"Quand j'étais petit, il y ___ un parc derrière ma maison.","base":"avoir","answers":["avait"],"en":"When I was little, there was a park behind my house.","why":"Describing how things were in the past → imperfect: il y avait."},{"id":"verbs-impersonal-08","type":"gap","prompt":"L'année prochaine, il y ___ une nouvelle piscine dans notre ville.","base":"avoir","hint":"(simple future)","answers":["aura"],"en":"Next year there will be a new swimming pool in our town.","why":"The simple future of il y a is il y aura."},{"id":"verbs-impersonal-09","type":"gap","prompt":"Mes parents ont acheté cette maison ___ dix ans.","hint":"(ago)","answers":["il y a"],"en":"My parents bought this house ten years ago.","why":"il y a + a length of time means 'ago'. It goes in front of the time (il y a dix ans), and the verb is in a past tense."},{"id":"verbs-impersonal-10","type":"flip","front":"How do you say: it's raining, it's snowing, the weather's nice, it's windy? And in the past and future?","back":"il pleut, il neige, il fait beau, il y a du vent (also il fait chaud / froid / mauvais, il y a du soleil / du brouillard). Past description: il pleuvait, il neigeait, il faisait beau. Future: il pleuvra, il neigera, il fera beau."},{"id":"verbs-impersonal-11","type":"gap","prompt":"Prends ton parapluie, il ___ depuis ce matin !","base":"pleuvoir","answers":["pleut"],"en":"Take your umbrella, it's been raining since this morning!","why":"depuis + present tense for something still going on: il pleut."},{"id":"verbs-impersonal-12","type":"gap","prompt":"Selon la météo, demain il ___ froid dans le nord.","base":"faire","hint":"(simple future)","answers":["fera"],"en":"According to the forecast, tomorrow it will be cold in the north.","why":"Weather uses il fait + adjective; the simple future of faire is il fera."},{"id":"verbs-impersonal-13","type":"flip","front":"How does il est + adjective + de work?","back":"il est + adjective + de + infinitive = it is ... to ...: Il est important de dormir huit heures. Il est interdit de fumer. Il est difficile de trouver un petit boulot. de becomes d' before a vowel or silent h: Il est essentiel d'économiser l'énergie."},{"id":"verbs-impersonal-14","type":"transform","instruction":"Rewrite the sentence using il est + adjective + de + infinitive.","prompt":"Manger des fruits, c'est important.","answers":["Il est important de manger des fruits."],"en":"It is important to eat fruit.","why":"il est + adjective + de + infinitive: Il est important de manger."},{"id":"verbs-impersonal-15","type":"flip","front":"What do il vaut mieux, il reste and il s'agit de mean?","back":"il vaut mieux + infinitive = it's better to: Il vaut mieux réserver à l'avance. il reste = there is / are ... left: Il reste trois billets. il s'agit de = it's about / it's a question of: Dans ce film, il s'agit d'une famille qui déménage. The subject is always il: never say 'ce film s'agit de'."},{"id":"verbs-impersonal-16","type":"gap","prompt":"Le concert est presque complet : il ne ___ que deux places.","base":"rester","answers":["reste"],"en":"The concert is almost sold out: there are only two seats left.","why":"il reste is impersonal, so the verb stays singular even before a plural noun: il reste deux places, not 'restent'."},{"id":"verbs-impersonal-17","type":"gap","prompt":"Il ___ mieux prendre le train que la voiture en ville.","base":"valoir","hint":"(present tense)","answers":["vaut"],"en":"It's better to take the train than the car in town.","why":"il vaut mieux + infinitive = it's better to (valoir in the present: il vaut). You will also meet the conditional il vaudrait mieux = it would be better to."},{"id":"verbs-impersonal-18","type":"gap","prompt":"Dans ce roman, il ___ d'une fille qui part vivre en Afrique.","base":"s'agir","answers":["s'agit"],"en":"This novel is about a girl who goes to live in Africa.","why":"il s'agit de = it's about. It is only used with il, so the reflexive pronoun is s': il s'agit."}]},{"id":"verbs-infinitive","order":26,"area":"Verbs","title":"Verbs followed by an infinitive","spec":"Verbs: verbs followed by an infinitive, with or without a preposition; dependent infinitives (faire réparer) (R)","receptive":false,"summary":["When two verbs come together, only the first is conjugated and the second stays in the infinitive: J'aime nager. Nous allons sortir.","No preposition after aimer, adorer, détester, préférer, vouloir, pouvoir, devoir, savoir, aller, espérer: Je préfère lire. Elle espère devenir médecin.","à + infinitive after commencer, apprendre, aider, réussir, continuer: J'apprends à conduire. Il a réussi à trouver un emploi.","de + infinitive after décider, essayer, oublier, arrêter, finir, choisir, refuser and avoir envie / besoin / peur: J'ai décidé de partir. de becomes d' before a vowel: J'ai oublié d'acheter du pain.","pour + infinitive = (in order) to: Je travaille pour gagner de l'argent. sans + infinitive = without ...ing: Il est parti sans dire au revoir.","English '-ing' after a preposition is an infinitive in French: avant de manger (before eating), au lieu de travailler (instead of working).","Object pronouns go in front of the infinitive they belong to: Je vais le faire. Je veux lui parler.","Recognise only: faire + infinitive = to have something done: Je fais réparer mon vélo (I'm having my bike repaired)."],"cards":[{"id":"verbs-infinitive-01","type":"flip","front":"Which common verbs are followed directly by an infinitive, with no preposition?","back":"aimer, adorer, détester, préférer, vouloir, pouvoir, devoir, savoir, aller, espérer (and il faut): J'adore danser. Je sais nager. Nous allons voyager. Elle espère devenir médecin."},{"id":"verbs-infinitive-02","type":"gap","prompt":"Ma sœur ___ devenir vétérinaire plus tard.","base":"vouloir","hint":"(present tense)","answers":["veut"],"en":"My sister wants to become a vet later on.","why":"vouloir is followed directly by an infinitive. Only the first verb is conjugated: elle veut + devenir."},{"id":"verbs-infinitive-03","type":"transform","instruction":"Rewrite the sentence using the verb in brackets + infinitive.","prompt":"Je fais du ski. (adorer)","answers":["J'adore faire du ski."],"en":"I love skiing.","why":"adorer + infinitive with no preposition; je becomes j' before the vowel of adore. English '-ing' is an infinitive here."},{"id":"verbs-infinitive-04","type":"flip","front":"Name five verbs followed by à + infinitive.","back":"commencer à, apprendre à, aider à, réussir à, continuer à (also s'habituer à and hésiter à): J'ai commencé à jouer du piano. Il m'aide à faire mes devoirs. Elle a réussi à trouver un stage."},{"id":"verbs-infinitive-05","type":"gap","prompt":"Mon petit frère apprend ___ nager à la piscine municipale.","hint":"(à or de?)","answers":["à"],"en":"My little brother is learning to swim at the local swimming pool.","why":"apprendre is followed by à + infinitive: apprendre à nager."},{"id":"verbs-infinitive-06","type":"gap","prompt":"Est-ce que tu peux m'aider ___ ranger ma chambre ?","hint":"(à or de?)","answers":["à"],"en":"Can you help me tidy my room?","why":"aider quelqu'un à + infinitive = to help someone (to) do something."},{"id":"verbs-infinitive-07","type":"flip","front":"Name verbs and expressions followed by de + infinitive.","back":"décider de, essayer de, oublier de, arrêter de, finir de, choisir de, refuser de, avoir envie de, avoir besoin de, avoir peur de: J'ai décidé de faire un apprentissage. de becomes d' before a vowel or silent h: J'ai oublié d'apporter mon livre."},{"id":"verbs-infinitive-08","type":"gap","prompt":"J'essaie ___ manger cinq fruits et légumes par jour.","hint":"(à or de?)","answers":["de"],"en":"I try to eat five portions of fruit and vegetables a day.","why":"essayer is followed by de + infinitive."},{"id":"verbs-infinitive-09","type":"gap","prompt":"Mon père a arrêté ___ fumer l'année dernière.","hint":"(à or de?)","answers":["de"],"en":"My father stopped smoking last year.","why":"arrêter is followed by de + infinitive. English 'stopped smoking' becomes arrêter de fumer."},{"id":"verbs-infinitive-10","type":"gap","prompt":"Nous avons envie ___ partir au bord de la mer.","hint":"(à or de?)","answers":["de"],"en":"We feel like going to the seaside.","why":"avoir envie de + infinitive = to feel like doing / to want to do."},{"id":"verbs-infinitive-11","type":"transform","instruction":"Rewrite the sentence using réussir à + infinitive in the perfect tense.","prompt":"Je trouve un petit boulot.","answers":["J'ai réussi à trouver un petit boulot."],"en":"I managed to find a part-time job.","why":"réussir à + infinitive; in the perfect only réussir changes (j'ai réussi) and trouver stays in the infinitive."},{"id":"verbs-infinitive-12","type":"transform","instruction":"Rewrite the sentence using décider de + infinitive in the perfect tense.","prompt":"Je mange moins de sucre.","answers":["J'ai décidé de manger moins de sucre."],"en":"I decided to eat less sugar.","why":"décider de + infinitive; the perfect is j'ai décidé, and manger stays in the infinitive."},{"id":"verbs-infinitive-13","type":"flip","front":"How do you say 'in order to', 'without ...ing' and 'before ...ing' with a verb?","back":"pour + infinitive: Je fais du baby-sitting pour gagner de l'argent. sans + infinitive: Elle est partie sans dire au revoir. avant de + infinitive: Lave-toi les mains avant de manger."},{"id":"verbs-infinitive-14","type":"gap","prompt":"Je mets de l'argent de côté ___ acheter une voiture.","hint":"(in order to)","answers":["pour","afin d'"],"en":"I'm saving money (in order) to buy a car.","why":"pour + infinitive expresses purpose: in order to. (afin de, shortened to afin d' before a vowel, means the same but is more formal.)"},{"id":"verbs-infinitive-15","type":"gap","prompt":"Il est sorti ___ fermer la porte à clé.","hint":"(without)","answers":["sans"],"en":"He went out without locking the door.","why":"sans + infinitive = without ...ing. French uses the infinitive where English uses '-ing'."},{"id":"verbs-infinitive-16","type":"transform","instruction":"Join the two sentences using pour + infinitive.","prompt":"Je travaille le samedi. Je gagne de l'argent.","answers":["Je travaille le samedi pour gagner de l'argent.","Pour gagner de l'argent, je travaille le samedi."],"en":"I work on Saturdays to earn money.","why":"pour + infinitive gives the purpose: the second verb becomes the infinitive gagner."},{"id":"verbs-infinitive-17","type":"flip","front":"Recognise: what does faire + infinitive mean? (e.g. Je fais réparer mon vélo.)","back":"To have something done, or to make someone do something. Je fais réparer mon vélo = I'm having my bike repaired. Nous avons fait construire un garage = We had a garage built. Le prof nous fait travailler = The teacher makes us work. You need to understand this, not produce it."},{"id":"verbs-infinitive-18","type":"flip","front":"Recognise: what does 'Elle s'est fait couper les cheveux' mean?","back":"She had her hair cut. se faire + infinitive = to have something done to or for yourself: Il s'est fait opérer = He had an operation. Recognise it in reading and listening."}]},{"id":"verbs-perfect","order":27,"area":"Verbs","title":"Perfect tense (passé composé)","spec":"Verbs: tenses: perfect","receptive":false,"summary":["The perfect tense describes a completed action in the past: J'ai joué au foot = I played / I have played football.","Most verbs use the present of avoir + past participle: j'ai mangé, tu as fini, il a vendu, nous avons regardé, ils ont choisi.","Regular past participles: -er → -é (parler → parlé), -ir → -i (finir → fini), -re → -u (vendre → vendu).","Learn the irregular participles: fait, pris, mis, vu, lu, écrit, bu, eu, été, pu, voulu, dû, dit, ouvert, reçu, venu: j'ai fait, elle a pris, nous avons bu.","About 16 verbs of movement or change of state take être (MRS VANDERTRAMP): aller, venir, arriver, partir, entrer, sortir, monter, descendre, naître, mourir, rester, tomber, retourner, rentrer, devenir, revenir: je suis allé(e).","With être, the participle agrees with the subject like an adjective: il est parti, elle est partie, ils sont partis, elles sont parties. A mixed group is masculine plural: Paul et Marie sont arrivés.","With avoir, the participle does not agree with the subject: elle a mangé, nous avons fini. (It only agrees with a direct object placed before it: Ta robe ? Je l'ai achetée.)","All reflexive verbs take être and agree: je me suis levé(e), elle s'est couchée, ils se sont amusés.","Negatives go round the auxiliary: je n'ai pas mangé, elle n'est jamais venue. Object pronouns go before the auxiliary: je l'ai vu."],"cards":[{"id":"verbs-perfect-01","type":"flip","front":"How do you form the perfect tense of most verbs?","back":"Present of avoir + past participle: j'ai joué, tu as joué, il/elle a joué, nous avons joué, vous avez joué, ils/elles ont joué. Regular participles: -er → -é (manger → mangé), -ir → -i (choisir → choisi), -re → -u (attendre → attendu). It means 'I played' or 'I have played'."},{"id":"verbs-perfect-02","type":"gap","prompt":"Hier soir, nous ___ un match de foot à la télé.","base":"regarder","answers":["avons regardé"],"en":"Last night we watched a football match on TV.","why":"hier soir → perfect: nous avons + regardé (-er verbs → -é)."},{"id":"verbs-perfect-03","type":"gap","prompt":"Le week-end dernier, Lucas ___ ses devoirs très vite.","base":"finir","answers":["a fini"],"en":"Last weekend Lucas finished his homework very quickly.","why":"A single completed action → perfect: il a + fini (-ir verbs → -i)."},{"id":"verbs-perfect-04","type":"gap","prompt":"Mes parents ___ leur vieille voiture le mois dernier.","base":"vendre","answers":["ont vendu"],"en":"My parents sold their old car last month.","why":"le mois dernier → perfect: ils ont + vendu (-re verbs → -u)."},{"id":"verbs-perfect-05","type":"flip","front":"Give the past participles of faire, prendre, mettre, voir, lire, écrire, boire, avoir and être.","back":"fait, pris, mis, vu, lu, écrit, bu, eu, été: j'ai fait, j'ai pris, j'ai mis, j'ai vu, j'ai lu, j'ai écrit, j'ai bu, j'ai eu, j'ai été. All of these take avoir."},{"id":"verbs-perfect-06","type":"flip","front":"Give the past participles of pouvoir, vouloir, devoir, dire, ouvrir, recevoir and venir.","back":"pu, voulu, dû, dit, ouvert, reçu, venu. Watch the circumflex on dû and the cedilla on reçu. venir takes être: elle est venue."},{"id":"verbs-perfect-07","type":"gap","prompt":"Hier, au zoo, ma sœur ___ cinquante photos.","base":"prendre","answers":["a pris"],"en":"Yesterday at the zoo, my sister took fifty photos.","why":"prendre has an irregular participle: pris. elle a pris."},{"id":"verbs-perfect-08","type":"gap","prompt":"Samedi dernier, nous ___ du vélo à la campagne.","base":"faire","answers":["avons fait"],"en":"Last Saturday we went cycling in the countryside.","why":"faire has an irregular participle: fait. nous avons fait."},{"id":"verbs-perfect-09","type":"gap","prompt":"Hier, Chloé ___ un long message à sa correspondante.","base":"écrire","answers":["a écrit"],"en":"Yesterday Chloé wrote a long message to her penfriend.","why":"écrire has an irregular participle: écrit. It takes avoir, so there is no agreement with Chloé."},{"id":"verbs-perfect-10","type":"gap","prompt":"Est-ce que tu ___ mon message hier soir ?","base":"recevoir","answers":["as reçu"],"en":"Did you get my message last night?","why":"recevoir has the irregular participle reçu, with a cedilla to keep the soft c sound."},{"id":"verbs-perfect-11","type":"gap","prompt":"Hier, Thomas ___ rester au lit toute la journée.","base":"devoir","hint":"(perfect tense)","answers":["a dû"],"en":"Yesterday Thomas had to stay in bed all day.","why":"devoir has the irregular participle dû, with a circumflex (du without it means 'some')."},{"id":"verbs-perfect-12","type":"transform","instruction":"Rewrite the sentence in the perfect tense.","prompt":"Je lis un roman.","answers":["J'ai lu un roman."],"en":"I read a novel.","why":"lire has the irregular participle lu: j'ai lu."},{"id":"verbs-perfect-13","type":"flip","front":"Which verbs take être in the perfect tense?","back":"All reflexive verbs, plus about 16 verbs of movement or change of state (MRS VANDERTRAMP): monter, rester, sortir, venir, aller, naître, descendre, entrer, rentrer, tomber, retourner, arriver, mourir, partir, plus devenir and revenir. je suis allé(e), elle est née, ils sont partis."},{"id":"verbs-perfect-14","type":"flip","front":"How does the past participle agree when the verb takes être?","back":"Like an adjective, with the subject: add -e for feminine, -s for masculine plural, -es for feminine plural. il est arrivé, elle est arrivée, ils sont arrivés, elles sont arrivées. A mixed group is masculine plural: Max et Léa sont arrivés. With avoir there is no agreement with the subject: elle a mangé."},{"id":"verbs-perfect-15","type":"gap","prompt":"L'été dernier, ma tante ___ en Australie.","base":"aller","answers":["est allée"],"en":"Last summer my aunt went to Australia.","why":"aller takes être, and the participle agrees with ma tante (feminine singular): allée."},{"id":"verbs-perfect-16","type":"gap","prompt":"Mon grand-père ___ en Algérie en 1950.","base":"naître","answers":["est né"],"en":"My grandfather was born in Algeria in 1950.","why":"naître takes être and has the irregular participle né: il est né = he was born (elle est née for a woman)."},{"id":"verbs-perfect-17","type":"gap","prompt":"Ce matin, Inès et Clara ___ du bus devant le collège.","base":"descendre","answers":["sont descendues"],"en":"This morning Inès and Clara got off the bus outside school.","why":"descendre takes être here; two girls = feminine plural, so add -es: descendues."},{"id":"verbs-perfect-18","type":"gap","prompt":"Mes frères ___ à la maison très tard samedi soir.","base":"rentrer","answers":["sont rentrés"],"en":"My brothers came home very late on Saturday night.","why":"rentrer takes être; mes frères is masculine plural, so add -s: rentrés."},{"id":"verbs-perfect-19","type":"gap","prompt":"Pendant le match, Hugo ___ et il s'est cassé le bras.","base":"tomber","answers":["est tombé"],"en":"During the match Hugo fell and broke his arm.","why":"tomber takes être; Hugo is masculine singular, so no extra ending: tombé."},{"id":"verbs-perfect-20","type":"transform","instruction":"Rewrite the sentence in the perfect tense.","prompt":"Elle sort avec ses amis.","answers":["Elle est sortie avec ses amis."],"en":"She went out with her friends.","why":"sortir takes être, so the participle agrees with elle: sortie."},{"id":"verbs-perfect-21","type":"flip","front":"How do reflexive verbs form the perfect tense?","back":"With être. The reflexive pronoun goes before the auxiliary and the participle agrees with the subject: je me suis réveillé(e), tu t'es habillé(e), il s'est lavé, elle s'est levée, nous nous sommes amusé(e)s, vous vous êtes couché(e)(s), ils se sont reposés, elles se sont reposées."},{"id":"verbs-perfect-22","type":"gap","prompt":"Hier, ma mère ___ à six heures.","base":"se lever","answers":["s'est levée"],"en":"Yesterday my mother got up at six o'clock.","why":"Reflexive verbs take être; the participle agrees with ma mère (feminine): s'est levée."},{"id":"verbs-perfect-23","type":"gap","prompt":"Samedi soir, Emma et sa cousine ___ à la fête.","base":"s'amuser","hint":"(perfect tense)","answers":["se sont amusées"],"en":"On Saturday evening Emma and her cousin had fun at the party.","why":"Reflexive verb → être; two girls = feminine plural, so add -es: se sont amusées."},{"id":"verbs-perfect-24","type":"transform","instruction":"Make this sentence negative using ne...pas.","prompt":"Ma sœur s'est couchée tard.","answers":["Ma sœur ne s'est pas couchée tard."],"en":"My sister didn't go to bed late.","why":"With a reflexive verb in the perfect, ne goes before the reflexive pronoun and pas after the auxiliary: ne s'est pas couchée. The participle still agrees with ma sœur."}]},{"id":"verbs-imperfect","order":28,"area":"Verbs","title":"Imperfect tense (and perfect vs imperfect)","spec":"Verbs: tenses: imperfect","receptive":false,"summary":["Formation: take the nous form of the present, remove -ons and add -ais, -ais, -ait, -ions, -iez, -aient: nous finissons → je finissais.","The only irregular stem is être → ét-: j'étais, c'était, nous étions.","Spelling: -ger verbs keep the e before a (je mangeais, ils nageaient, but nous mangions); -cer verbs take ç before a (je commençais, but nous commencions).","Use it for descriptions in the past: La maison était grande et il y avait un jardin.","Use it for repeated or habitual actions ('used to' / 'would'): Quand j'étais petit, je jouais au parc tous les jours.","Use it for an action in progress ('was ...ing'), often interrupted by a perfect: Je regardais la télé quand le téléphone a sonné.","Use it for weather, feelings and opinions in the past: Il faisait beau. J'avais peur. C'était génial !","Perfect = a single completed event (what happened). Imperfect = background, description or habit (what was going on, what used to happen).","Imperfect clues: d'habitude, souvent, tous les jours, le samedi, autrefois, quand j'étais petit(e). Perfect clues: soudain, tout à coup, un jour, ce jour-là, une fois."],"cards":[{"id":"verbs-imperfect-01","type":"flip","front":"How do you form the imperfect tense?","back":"Take the nous form of the present, remove -ons and add -ais, -ais, -ait, -ions, -iez, -aient. nous jouons → je jouais; nous finissons → il finissait; nous faisons → ils faisaient; nous prenons → vous preniez."},{"id":"verbs-imperfect-02","type":"flip","front":"Which verb has an irregular imperfect stem?","back":"Only être: ét- → j'étais, tu étais, il était, nous étions, vous étiez, ils étaient. Everything else follows the nous rule, even avoir (nous avons → j'avais) and aller (nous allons → j'allais)."},{"id":"verbs-imperfect-03","type":"gap","prompt":"Quand j'étais petit, je ___ au foot tous les samedis.","base":"jouer","answers":["jouais"],"en":"When I was little, I used to play football every Saturday.","why":"A repeated action in the past (tous les samedis) → imperfect: je jouais."},{"id":"verbs-imperfect-04","type":"gap","prompt":"Quand ils étaient petits, mes cousins ___ souvent chez nous.","base":"venir","answers":["venaient"],"en":"When they were little, my cousins often came to our house.","why":"Habitual past → imperfect. Stem from nous venons → ven- + -aient."},{"id":"verbs-imperfect-05","type":"gap","prompt":"Quand nous étions jeunes, nous ___ toujours nos devoirs avant le dîner.","base":"finir","answers":["finissions"],"en":"When we were young, we always finished our homework before dinner.","why":"Habit in the past → imperfect. Stem from nous finissons → finiss- + -ions."},{"id":"verbs-imperfect-06","type":"gap","prompt":"Autrefois, mes grands-parents ___ dans une ferme.","base":"habiter","answers":["habitaient"],"en":"In the past my grandparents lived on a farm.","why":"autrefois describes how things used to be → imperfect: ils habitaient."},{"id":"verbs-imperfect-07","type":"gap","prompt":"Mon ancienne école primaire ___ petite, mais les profs étaient sympas.","base":"être","answers":["était"],"en":"My old primary school was small, but the teachers were nice.","why":"Description in the past → imperfect. être has the irregular stem ét-: elle était."},{"id":"verbs-imperfect-08","type":"gap","prompt":"Quand j'étais petite, je ___ beaucoup de bonbons.","base":"manger","answers":["mangeais"],"en":"When I was little, I used to eat lots of sweets.","why":"Habitual past → imperfect. -ger verbs keep the e before a to keep the g soft: je mangeais."},{"id":"verbs-imperfect-09","type":"gap","prompt":"Quand j'étais au collège, les cours ___ à huit heures.","base":"commencer","answers":["commençaient"],"en":"When I was at secondary school, lessons started at eight o'clock.","why":"Habitual past → imperfect. -cer verbs take ç before a to keep the soft c: commençaient."},{"id":"verbs-imperfect-10","type":"flip","front":"What are the main uses of the imperfect?","back":"1 Description in the past: C'était un village calme. 2 Habits and repeated actions ('used to'): Je nageais tous les jours. 3 An action in progress ('was ...ing'): Je lisais quand... 4 Weather, feelings and opinions: Il faisait froid. J'étais content. C'était nul."},{"id":"verbs-imperfect-11","type":"flip","front":"How do you say 'it was', 'there was / there were', 'the weather was nice' and 'you had to' in the past?","back":"c'était, il y avait, il faisait beau, il fallait. These almost always go in the imperfect when you describe a past scene: C'était super, il y avait beaucoup de monde et il faisait chaud."},{"id":"verbs-imperfect-12","type":"transform","instruction":"Rewrite the sentence in the imperfect.","prompt":"Je suis fatigué et j'ai faim.","answers":["J'étais fatigué et j'avais faim."],"en":"I was tired and I was hungry.","why":"Feelings and states in the past → imperfect: j'étais (irregular stem ét-) and j'avais."},{"id":"verbs-imperfect-13","type":"transform","instruction":"Rewrite the sentence in the imperfect.","prompt":"Nous mangeons à la cantine.","answers":["Nous mangions à la cantine."],"en":"We used to eat in the canteen.","why":"Before the i of -ions the g is already soft, so no extra e: nous mangions."},{"id":"verbs-imperfect-14","type":"transform","instruction":"Rewrite the sentence in the imperfect.","prompt":"Il y a beaucoup de monde et c'est génial.","answers":["Il y avait beaucoup de monde et c'était génial."],"en":"There were lots of people and it was great.","why":"il y a → il y avait; c'est → c'était. Both describe a past scene."},{"id":"verbs-imperfect-15","type":"flip","front":"Perfect or imperfect: how do you decide?","back":"Perfect = a completed single event, what happened next: Soudain, j'ai entendu un bruit. Imperfect = the background, a description, or something that used to happen or was going on: Il était minuit et il pleuvait. Test: if English could say 'was ...ing' or 'used to', use the imperfect."},{"id":"verbs-imperfect-16","type":"gap","prompt":"Quand il était petit, Hugo ___ peur du noir.","base":"avoir","answers":["avait"],"en":"When he was little, Hugo was afraid of the dark.","why":"A feeling that lasted over a period of the past → imperfect: il avait peur."},{"id":"verbs-imperfect-17","type":"gap","prompt":"Quand j'habitais à Paris, ma mère ___ au marché tous les samedis.","base":"aller","answers":["allait"],"en":"When I lived in Paris, my mother went to the market every Saturday.","why":"tous les samedis shows a habit → imperfect: elle allait."},{"id":"verbs-imperfect-18","type":"gap","prompt":"Hier soir, je ___ mes devoirs quand mon portable a sonné.","base":"faire","answers":["faisais"],"en":"Last night I was doing my homework when my phone rang.","why":"An action in progress ('was doing') interrupted by an event in the perfect → imperfect: je faisais."},{"id":"verbs-imperfect-19","type":"gap","prompt":"Mes parents dormaient quand le voleur ___ dans la maison.","base":"entrer","answers":["est entré"],"en":"My parents were sleeping when the burglar came into the house.","why":"The sudden event that interrupts the background action → perfect. entrer takes être: le voleur est entré."},{"id":"verbs-imperfect-20","type":"gap","prompt":"Quand je suis arrivé à la gare, il ___ et je n'avais pas de parapluie.","base":"pleuvoir","answers":["pleuvait"],"en":"When I arrived at the station, it was raining and I didn't have an umbrella.","why":"Weather as background to an event → imperfect: il pleuvait."},{"id":"verbs-imperfect-21","type":"gap","prompt":"D'habitude, Paul prenait le bus, mais ce jour-là, il ___ un taxi.","base":"prendre","answers":["a pris"],"en":"Paul usually took the bus, but that day he took a taxi.","why":"ce jour-là marks one completed occasion, in contrast with the habit (prenait) → perfect: il a pris."},{"id":"verbs-imperfect-22","type":"gap","prompt":"L'année dernière, mes parents ___ en Grèce pour la première fois.","base":"aller","answers":["sont allés"],"en":"Last year my parents went to Greece for the first time.","why":"pour la première fois marks a single completed event → perfect. aller takes être and agrees: sont allés."},{"id":"verbs-imperfect-23","type":"transform","instruction":"Rewrite in the past: imperfect for the background action, perfect for the event.","prompt":"Je lis quand ma mère arrive.","answers":["Je lisais quand ma mère est arrivée.","J'étais en train de lire quand ma mère est arrivée."],"en":"I was reading when my mother arrived.","why":"The ongoing action (lire) → imperfect: je lisais. The interruption → perfect with être and agreement: ma mère est arrivée."},{"id":"verbs-imperfect-24","type":"transform","instruction":"Rewrite in the past: imperfect for the weather, perfect for the action.","prompt":"Il fait froid, alors je mets un pull.","answers":["Il faisait froid, alors j'ai mis un pull."],"en":"It was cold, so I put on a jumper.","why":"Weather as background → imperfect: il faisait froid. A single completed action → perfect: j'ai mis (irregular participle of mettre)."}]},{"id":"verbs-future","order":29,"area":"Verbs","title":"Near future and simple future","spec":"Verbs: tenses: immediate/near future; simple future","receptive":false,"summary":["Near future: present of aller + infinitive means 'going to': Je vais réviser ce soir. Ils vont partir demain.","In the negative, ne ... pas goes round the part of aller: Nous n'allons pas sortir ce week-end. A reflexive pronoun stays in front of the infinitive and matches the subject: Je vais me coucher. Nous allons nous lever tôt.","Simple future of regular verbs: infinitive + -ai, -as, -a, -ons, -ez, -ont: je jouerai, tu finiras, nous regarderons.","-re verbs drop the final e before the endings: prendre -> je prendrai, attendre -> ils attendront.","Irregular stems take the same endings: être -> ser-, avoir -> aur-, aller -> ir-, faire -> fer-: je serai, nous aurons, ils iront, il fera beau.","More irregular stems: pouvoir -> pourr-, vouloir -> voudr-, devoir -> devr-, savoir -> saur-, venir -> viendr-, voir -> verr-, envoyer -> enverr-, il faut -> il faudra.","Every future stem ends in r. Verbs like acheter add a grave accent: j'achèterai, elle achètera.","After quand (and lorsque, dès que), use the future when the action is still to come, even though English uses the present: Quand j'aurai dix-huit ans, j'apprendrai à conduire.","Use the near future for plans and things about to happen, and the simple future for predictions and things further ahead; using both in your writing shows range.","Don't confuse the future (je serai = I will be) with the conditional (je serais = I would be)."],"cards":[{"id":"verbs-future-01","type":"flip","front":"How do you form the near future (le futur proche)?","back":"Present tense of aller + infinitive: je vais jouer, tu vas jouer, il/elle/on va jouer, nous allons jouer, vous allez jouer, ils/elles vont jouer. It means 'going to': Je vais jouer au tennis = I'm going to play tennis."},{"id":"verbs-future-02","type":"gap","prompt":"Demain, nous ___ au parc avec le chien.","base":"jouer","hint":"near future","answers":["allons jouer"],"en":"Tomorrow we are going to play in the park with the dog.","why":"Near future = present of aller (nous allons) + the infinitive, which does not change: allons jouer."},{"id":"verbs-future-03","type":"gap","prompt":"Je suis très fatigué, alors je ___ tout de suite.","base":"se coucher","hint":"near future","answers":["vais me coucher"],"en":"I'm very tired, so I'm going to go to bed straight away.","why":"In the near future the reflexive pronoun stays in front of the infinitive and matches the subject: je vais me coucher (not je vais se coucher)."},{"id":"verbs-future-04","type":"transform","instruction":"Rewrite the sentence in the near future (aller + infinitive).","prompt":"Je fais mes devoirs.","answers":["Je vais faire mes devoirs."],"en":"I am going to do my homework.","why":"Put the present of aller (je vais) in front and change fais to the infinitive faire."},{"id":"verbs-future-05","type":"transform","instruction":"Rewrite the sentence in the near future, keeping it negative.","prompt":"Ils ne prennent pas le train.","answers":["Ils ne vont pas prendre le train."],"en":"They are not going to take the train.","why":"ne ... pas goes round the conjugated part (vont); the infinitive prendre comes after pas."},{"id":"verbs-future-06","type":"flip","front":"How do you form the simple future of regular verbs?","back":"Take the infinitive and add -ai, -as, -a, -ons, -ez, -ont. -re verbs drop their final e first. jouer -> je jouerai, finir -> tu finiras, vendre -> il vendra, regarder -> nous regarderons, choisir -> vous choisirez, attendre -> elles attendront. It means 'will': je jouerai = I will play."},{"id":"verbs-future-07","type":"gap","prompt":"L'année prochaine, ma sœur ___ ses études à Lyon.","base":"commencer","hint":"simple future","answers":["commencera"],"en":"Next year my sister will start her studies in Lyon.","why":"Regular -er verb: infinitive commencer + -a for elle. No cedilla is needed because the c is followed by e."},{"id":"verbs-future-08","type":"gap","prompt":"Demain matin, tu ___ le bus de huit heures.","base":"prendre","hint":"simple future","answers":["prendras"],"en":"Tomorrow morning you will take the eight o'clock bus.","why":"-re verbs drop the final e of the infinitive before the ending: prendr- + -as."},{"id":"verbs-future-09","type":"gap","prompt":"Mes grands-parents nous ___ à l'aéroport samedi prochain.","base":"attendre","hint":"simple future","answers":["attendront"],"en":"My grandparents will wait for us at the airport next Saturday.","why":"attendre drops its final e: attendr- + -ont for a plural subject (ils)."},{"id":"verbs-future-10","type":"flip","front":"Which common verbs have an irregular stem in the simple future?","back":"être -> ser- (je serai), avoir -> aur- (j'aurai), aller -> ir- (j'irai), faire -> fer- (je ferai), pouvoir -> pourr- (je pourrai), vouloir -> voudr- (je voudrai), devoir -> devr- (je devrai), savoir -> saur- (je saurai), venir -> viendr- (je viendrai), voir -> verr- (je verrai), envoyer -> enverr- (j'enverrai), falloir -> il faudra. The endings are the same as for regular verbs."},{"id":"verbs-future-11","type":"gap","prompt":"L'été prochain, nous ___ en Italie pour les vacances.","base":"aller","hint":"simple future","answers":["irons"],"en":"Next summer we will go to Italy for the holidays.","why":"aller has the irregular future stem ir-: nous irons."},{"id":"verbs-future-12","type":"gap","prompt":"Selon la météo, demain il ___ beau dans le sud de la France.","base":"faire","hint":"simple future","answers":["fera"],"en":"According to the weather forecast, it will be fine in the south of France tomorrow.","why":"faire has the irregular future stem fer-: il fera beau = it will be fine."},{"id":"verbs-future-13","type":"gap","prompt":"Le mois prochain, mes parents ___ une voiture électrique.","base":"avoir","hint":"simple future","answers":["auront"],"en":"Next month my parents will have an electric car.","why":"avoir has the irregular future stem aur-: ils auront."},{"id":"verbs-future-14","type":"gap","prompt":"Quand j'aurai dix-huit ans, je ___ passer mon permis de conduire.","base":"pouvoir","hint":"simple future","answers":["pourrai"],"en":"When I am eighteen, I will be able to take my driving test.","why":"pouvoir has the irregular future stem pourr- (double r): je pourrai."},{"id":"verbs-future-15","type":"gap","prompt":"Ce soir, tu ___ ranger ta chambre avant de sortir.","base":"devoir","hint":"simple future","answers":["devras"],"en":"This evening you will have to tidy your room before going out.","why":"devoir has the irregular future stem devr-: tu devras = you will have to."},{"id":"verbs-future-16","type":"transform","instruction":"Rewrite the sentence in the simple future.","prompt":"Mes cousins savent nager.","answers":["Mes cousins sauront nager."],"en":"My cousins will know how to swim.","why":"savoir has the irregular future stem saur-: ils sauront."},{"id":"verbs-future-17","type":"flip","front":"Translate: 'When I am older, I will live abroad.' What is the trap?","back":"Quand je serai plus âgé(e), j'habiterai à l'étranger. After quand, French uses the future when the action is still to come; English uses the present ('when I am'). Writing 'quand je suis plus âgé' for a future idea is a classic mistake."},{"id":"verbs-future-18","type":"gap","prompt":"Quand je ___ grand, je deviendrai pilote.","base":"être","answers":["serai"],"en":"When I grow up, I will become a pilot.","why":"quand + future: the action is still to come, so French uses the future (je serai) where English uses the present."},{"id":"verbs-future-19","type":"gap","prompt":"Quand Paul ___ à la maison ce soir, il t'enverra un message.","base":"rentrer","answers":["rentrera","sera rentré"],"en":"When Paul gets home this evening, he will send you a message.","why":"The main verb (enverra) is in the future, so the verb after quand must be future too: rentrera, not rentre. (The future perfect sera rentré is also correct.)"},{"id":"verbs-future-20","type":"gap","prompt":"Quand vous viendrez à Paris, vous ___ la tour Eiffel.","base":"voir","hint":"simple future","answers":["verrez"],"en":"When you come to Paris, you will see the Eiffel Tower.","why":"voir has the irregular future stem verr-: vous verrez. Notice viendrez (venir -> viendr-) after quand as well."},{"id":"verbs-future-21","type":"gap","prompt":"Ma cousine nous ___ des photos de son voyage au Canada.","base":"envoyer","hint":"simple future","answers":["enverra"],"en":"My cousin will send us photos of her trip to Canada.","why":"envoyer has the irregular future stem enverr-: elle enverra."},{"id":"verbs-future-22","type":"transform","instruction":"Change the near future to the simple future.","prompt":"Il va falloir partir tôt.","answers":["Il faudra partir tôt."],"en":"We will have to leave early.","why":"falloir is only used with il; its future is il faudra (stem faudr-)."},{"id":"verbs-future-23","type":"gap","prompt":"Demain, ma mère ___ du pain à la boulangerie.","base":"acheter","hint":"simple future","answers":["achètera"],"en":"Tomorrow my mother will buy some bread at the baker's.","why":"acheter changes e to è in its future stem (achèter-), so elle achètera."},{"id":"verbs-future-24","type":"flip","front":"je serai or je serais? How do you tell the simple future from the conditional?","back":"Both use the same stem. The future has the endings -ai, -as, -a, -ons, -ez, -ont: je serai = I will be. The conditional has the imperfect endings -ais, -ais, -ait, -ions, -iez, -aient: je serais = I would be. The je forms can sound alike, so check the spelling carefully when you write."}]},{"id":"verbs-conditional","order":30,"area":"Verbs","title":"Conditional (and si clauses)","spec":"Verbs: tenses: conditional","receptive":false,"summary":["The conditional means 'would': future stem + imperfect endings -ais, -ais, -ait, -ions, -iez, -aient: je jouerais, nous finirions, ils vendraient.","-re verbs drop the final e: prendre -> je prendrais, attendre -> il attendrait.","Irregular verbs use their future stems: je serais, j'aurais, j'irais, je ferais, je pourrais, je voudrais, je devrais, je saurais, je viendrais, je verrais.","Use it to be polite: Je voudrais un café, s'il vous plaît. Pourriez-vous m'aider ?","j'aimerais (I would like) and je préférerais (I would prefer) are useful for future plans: J'aimerais travailler à l'étranger.","devoir and pouvoir in the conditional mean 'should' and 'could': Tu devrais manger plus de fruits. On pourrait aller au cinéma.","Imaginary situation: si + imperfect, then the conditional: Si j'avais de l'argent, je voyagerais.","Real possibility: si + present, then the future: S'il pleut demain, nous resterons à la maison.","Never put the future or the conditional straight after si meaning 'if': Si j'avais le temps (not si j'aurais le temps).","si shortens to s' only before il and ils: s'il fait beau, but si elle vient."],"cards":[{"id":"verbs-conditional-01","type":"flip","front":"How do you form the conditional, and what does it mean?","back":"Future stem + the imperfect endings -ais, -ais, -ait, -ions, -iez, -aient. jouer -> je jouerais, finir -> nous finirions, prendre -> ils prendraient. It translates 'would': je jouerais = I would play."},{"id":"verbs-conditional-02","type":"gap","prompt":"Avec plus de temps libre, je ___ plus souvent au foot.","base":"jouer","hint":"conditional","answers":["jouerais"],"en":"With more free time, I would play football more often.","why":"Conditional = infinitive (the future stem) + the imperfect ending -ais: je jouerais."},{"id":"verbs-conditional-03","type":"gap","prompt":"À ta place, je ___ le train ; c'est plus rapide.","base":"prendre","answers":["prendrais"],"en":"If I were you, I would take the train; it's quicker.","why":"À ta place (in your place) gives advice, so the conditional is used. -re verbs drop the e: prendr- + -ais."},{"id":"verbs-conditional-04","type":"flip","front":"Which verbs have an irregular stem in the conditional?","back":"The same ones as in the future: être -> je serais, avoir -> j'aurais, aller -> j'irais, faire -> je ferais, pouvoir -> je pourrais, vouloir -> je voudrais, devoir -> je devrais, savoir -> je saurais, venir -> je viendrais, voir -> je verrais, falloir -> il faudrait."},{"id":"verbs-conditional-05","type":"gap","prompt":"Bonjour, je ___ deux billets pour Marseille, s'il vous plaît.","base":"vouloir","hint":"would like","answers":["voudrais"],"en":"Hello, I would like two tickets for Marseille, please.","why":"je voudrais (vouloir in the conditional) is the polite way to ask for something; je veux sounds rude."},{"id":"verbs-conditional-06","type":"flip","front":"Give six useful conditional phrases for requests, advice and plans.","back":"Je voudrais... (I would like...), J'aimerais... (I would like...), Je préférerais... (I would prefer...), Pourriez-vous... ? (Could you...?), Tu devrais... (You should...), Ce serait génial (It would be great)."},{"id":"verbs-conditional-07","type":"gap","prompt":"Tu ___ boire plus d'eau quand tu fais du sport.","base":"devoir","hint":"should","answers":["devrais"],"en":"You should drink more water when you do sport.","why":"devoir in the conditional means 'should': tu devrais (stem devr- + -ais)."},{"id":"verbs-conditional-08","type":"gap","prompt":"Plus tard, mon copain et moi ___ faire le tour du monde.","base":"aimer","hint":"would like","answers":["aimerions"],"en":"Later on, my friend and I would like to travel round the world.","why":"mon copain et moi = nous; conditional of aimer: aimer + -ions = aimerions."},{"id":"verbs-conditional-09","type":"transform","instruction":"Make the question more polite by using the conditional.","prompt":"Pouvez-vous fermer la fenêtre ?","answers":["Pourriez-vous fermer la fenêtre ?","Est-ce que vous pourriez fermer la fenêtre ?","Vous pourriez fermer la fenêtre ?"],"en":"Could you close the window?","why":"pouvoir has the conditional stem pourr-: vous pourriez. Pourriez-vous is the polite form of Pouvez-vous."},{"id":"verbs-conditional-10","type":"flip","front":"Which tenses go together in a sentence with si (if)?","back":"Real possibility: si + present, then the future: Si tu viens, on ira au parc (If you come, we'll go to the park). Imaginary situation: si + imperfect, then the conditional: Si tu venais, on irait au parc (If you came, we would go to the park). The verb straight after si is never future or conditional."},{"id":"verbs-conditional-11","type":"gap","prompt":"Si ma mère avait plus d'argent, elle ___ une nouvelle voiture.","base":"acheter","answers":["achèterait"],"en":"If my mother had more money, she would buy a new car.","why":"si + imperfect (avait) is followed by the conditional. acheter takes a grave accent in its stem: achèter- + -ait."},{"id":"verbs-conditional-12","type":"gap","prompt":"Si nous habitions à la campagne, nous ___ un chien.","base":"avoir","answers":["aurions"],"en":"If we lived in the countryside, we would have a dog.","why":"si + imperfect, then the conditional. avoir has the irregular stem aur-: nous aurions."},{"id":"verbs-conditional-13","type":"gap","prompt":"S'il faisait beau, on ___ à la plage.","base":"aller","answers":["irait"],"en":"If the weather were nice, we would go to the beach.","why":"si + imperfect (faisait), then the conditional. aller has the stem ir-, and on takes the il ending -ait: on irait."},{"id":"verbs-conditional-14","type":"gap","prompt":"Si mes parents ___ riches, ils habiteraient dans une grande maison.","base":"être","answers":["étaient"],"en":"If my parents were rich, they would live in a big house.","why":"The verb after si goes in the imperfect (ils étaient), not the conditional; the conditional (habiteraient) is in the other half of the sentence."},{"id":"verbs-conditional-15","type":"gap","prompt":"Si ma sœur ___ à Paris, elle irait au musée tous les week-ends.","base":"habiter","answers":["habitait"],"en":"If my sister lived in Paris, she would go to the museum every weekend.","why":"The main verb (irait) is conditional, so the si clause is in the imperfect: elle habitait."},{"id":"verbs-conditional-16","type":"gap","prompt":"S'il pleut demain, nous ___ à la maison.","base":"rester","hint":"simple future","answers":["resterons"],"en":"If it rains tomorrow, we will stay at home.","why":"si + present (il pleut) for a real possibility, then the future: nous resterons."},{"id":"verbs-conditional-17","type":"gap","prompt":"Si tu ___ faim plus tard, tu pourras manger un sandwich.","base":"avoir","answers":["as"],"en":"If you are hungry later, you will be able to eat a sandwich.","why":"The main verb (pourras) is in the future, so the si clause is in the present: tu as faim."},{"id":"verbs-conditional-18","type":"transform","instruction":"Make the situation imaginary: change the present to the imperfect and the future to the conditional.","prompt":"Si j'ai le temps, je ferai du vélo.","answers":["Si j'avais le temps, je ferais du vélo.","Je ferais du vélo si j'avais le temps."],"en":"If I had time, I would go cycling.","why":"Imaginary situation: si + imperfect (j'avais), then the conditional (je ferais, from the stem fer-)."}]},{"id":"verbs-pluperfect","order":31,"area":"Verbs","title":"Pluperfect tense","spec":"Verbs: tenses: pluperfect","receptive":false,"summary":["The pluperfect means 'had done': imperfect of avoir or être + past participle: j'avais fini, elle était partie.","Imperfect of avoir: j'avais, tu avais, il avait, nous avions, vous aviez, ils avaient.","Imperfect of être: j'étais, tu étais, il était, nous étions, vous étiez, ils étaient.","Verbs that take être in the perfect take être in the pluperfect, and so do reflexive verbs: nous étions arrivés, elle s'était levée.","With être, the past participle agrees with the subject: Mes amies étaient déjà parties.","With avoir, the past participle only agrees with a direct object placed before the verb: les photos qu'il avait prises.","Use it for something that had already happened before another past event: J'avais déjà mangé quand il est arrivé.","déjà and ne ... pas go round the auxiliary: Le film avait déjà commencé. Je n'avais pas compris."],"cards":[{"id":"verbs-pluperfect-01","type":"flip","front":"How do you form the pluperfect, and what does it mean?","back":"Imperfect of avoir or être + past participle. It means 'had done': j'avais mangé = I had eaten; nous étions partis = we had left. Use the same auxiliary (avoir or être) as in the perfect tense."},{"id":"verbs-pluperfect-02","type":"gap","prompt":"Quand nous sommes arrivés au cinéma, le film ___ sans nous.","base":"commencer","hint":"pluperfect","answers":["avait commencé"],"en":"When we arrived at the cinema, the film had started without us.","why":"The film started before we arrived, so the pluperfect is used: imperfect of avoir (avait) + commencé."},{"id":"verbs-pluperfect-03","type":"gap","prompt":"Maman était contente parce que nous ___ la cuisine.","base":"ranger","hint":"pluperfect","answers":["avions rangé"],"en":"Mum was pleased because we had tidied the kitchen.","why":"nous avions (imperfect of avoir) + rangé. With avoir the participle does not agree with the subject."},{"id":"verbs-pluperfect-04","type":"gap","prompt":"Paul a enfin retrouvé le portable qu'il ___ dans le bus.","base":"perdre","hint":"pluperfect","answers":["avait perdu"],"en":"Paul finally found the phone he had lost on the bus.","why":"Losing the phone happened before finding it, so the pluperfect is used: il avait + perdu."},{"id":"verbs-pluperfect-05","type":"transform","instruction":"Rewrite the sentence in the pluperfect.","prompt":"J'ai fini mes devoirs.","answers":["J'avais fini mes devoirs."],"en":"I had finished my homework.","why":"Change the present of avoir (ai) to the imperfect (avais); the past participle fini stays the same."},{"id":"verbs-pluperfect-06","type":"flip","front":"Which verbs use être in the pluperfect, and what happens to the past participle?","back":"The same ones as in the perfect: verbs of movement or change of state (aller, venir, arriver, partir, entrer, sortir, monter, descendre, naître, mourir, rester, tomber, retourner, rentrer, devenir, revenir) and all reflexive verbs. The participle agrees with the subject: elle était partie, ils étaient arrivés, nous nous étions levé(e)s."},{"id":"verbs-pluperfect-07","type":"gap","prompt":"Quand Marc est arrivé à la gare, ses amis ___ sans lui.","base":"partir","hint":"pluperfect","answers":["étaient partis"],"en":"When Marc got to the station, his friends had left without him.","why":"partir takes être; ses amis is masculine plural, so the participle adds -s: étaient partis."},{"id":"verbs-pluperfect-08","type":"gap","prompt":"Léa n'est pas venue à la fête parce qu'elle ___ malade la veille.","base":"tomber","hint":"pluperfect","answers":["était tombée"],"en":"Léa didn't come to the party because she had fallen ill the day before.","why":"tomber takes être; the participle agrees with elle (feminine singular): était tombée."},{"id":"verbs-pluperfect-09","type":"transform","instruction":"Rewrite the sentence in the pluperfect.","prompt":"Elles sont allées en ville.","answers":["Elles étaient allées en ville."],"en":"They had gone into town.","why":"Change sont (present of être) to étaient; allées keeps its feminine plural agreement."},{"id":"verbs-pluperfect-10","type":"flip","front":"When do you use the pluperfect? Translate: J'avais déjà mangé quand il est arrivé.","back":"'I had already eaten when he arrived.' The pluperfect is for an action that happened before another past action: eating came first (pluperfect), his arrival second (perfect). déjà goes between the auxiliary and the participle."},{"id":"verbs-pluperfect-11","type":"gap","prompt":"Nous sommes restés à la maison parce qu'il ___ toute la nuit.","base":"pleuvoir","hint":"pluperfect","answers":["avait plu"],"en":"We stayed at home because it had rained all night.","why":"pleuvoir takes avoir and has the irregular past participle plu: il avait plu."},{"id":"verbs-pluperfect-12","type":"gap","prompt":"Chloé était épuisée parce qu'elle ___ du sport toute la journée.","base":"faire","hint":"pluperfect","answers":["avait fait"],"en":"Chloé was exhausted because she had done sport all day.","why":"faire takes avoir and has the irregular past participle fait: elle avait fait."},{"id":"verbs-pluperfect-13","type":"gap","prompt":"Mon frère et moi avons raté le concert parce que nous ___ trop tard.","base":"partir","hint":"pluperfect","answers":["étions partis"],"en":"My brother and I missed the concert because we had left too late.","why":"partir takes être. Mon frère et moi = nous, masculine plural, so the participle is partis."},{"id":"verbs-pluperfect-14","type":"gap","prompt":"Ce matin-là, ma sœur ___ très tôt pour réviser.","base":"se lever","hint":"pluperfect","answers":["s'était levée"],"en":"That morning my sister had got up very early to revise.","why":"Reflexive verbs take être: se becomes s' before était, and the participle agrees with ma sœur: levée."},{"id":"verbs-pluperfect-15","type":"transform","instruction":"Rewrite the sentence in the pluperfect.","prompt":"Il n'a pas compris la question.","answers":["Il n'avait pas compris la question."],"en":"He had not understood the question.","why":"ne ... pas goes round the auxiliary, which changes to the imperfect: n'avait pas compris."},{"id":"verbs-pluperfect-16","type":"gap","prompt":"Ma correspondante m'a dit qu'elle ___ en Espagne l'été précédent.","base":"aller","hint":"pluperfect","answers":["était allée"],"en":"My penfriend told me that she had gone to Spain the summer before.","why":"In reported speech, an earlier past action goes into the pluperfect. aller takes être, and the participle agrees with elle: allée."},{"id":"verbs-pluperfect-17","type":"flip","front":"In the pluperfect with avoir, when does the past participle agree?","back":"Only when a direct object comes before the verb (often que, la, l' or les): Où sont les clés que j'avais laissées sur la table ? La lettre ? Je l'avais déjà lue. With no direct object in front there is no agreement: Elle avait fini."},{"id":"verbs-pluperfect-18","type":"gap","prompt":"Mon père a imprimé les photos que ma sœur ___ pendant les vacances.","base":"prendre","hint":"pluperfect","answers":["avait prises"],"en":"My dad printed the photos that my sister had taken during the holidays.","why":"prendre takes avoir, but que (= les photos, feminine plural) is a direct object placed before the verb, so the participle agrees with it: prises."}]},{"id":"verbs-depuis","order":32,"area":"Verbs","title":"depuis with the present and imperfect","spec":"Verbs: use of depuis with present and imperfect tenses","receptive":false,"summary":["depuis + present = something that started in the past and is still going on: J'habite ici depuis cinq ans = I have lived here for five years.","English says 'have been doing' or 'have done', but French uses the present tense: Je joue du piano depuis deux ans.","depuis + a length of time = for; depuis + a point in time = since: depuis trois mois, depuis lundi, depuis 2020.","depuis + imperfect = 'had been doing', for something still going on at a moment in the past: Je dormais depuis une heure quand le téléphone a sonné.","To ask how long: Depuis combien de temps apprends-tu le français ? To ask since when: Depuis quand habites-tu ici ? Both take the present.","pendant = for a period that is over, usually with the perfect: J'ai habité à Paris pendant trois ans (I don't live there now).","il y a + a length of time = ago, with the perfect: Je suis arrivé il y a deux jours.","Compare: J'apprends le judo depuis trois ans (and still do) / J'ai fait du judo pendant trois ans (and stopped) / J'ai commencé le judo il y a trois ans."],"cards":[{"id":"verbs-depuis-01","type":"flip","front":"How do you say 'I have lived here for five years' in French? Why?","back":"J'habite ici depuis cinq ans. With depuis, French uses the present tense for an action that started in the past and is still going on. English says 'have lived' or 'have been living', but the French verb stays in the present."},{"id":"verbs-depuis-02","type":"gap","prompt":"Ma famille ___ à Bordeaux depuis dix ans et nous adorons la ville.","base":"habiter","answers":["habite"],"en":"My family has lived in Bordeaux for ten years and we love the city.","why":"depuis + present for an action that is still going on: ma famille (= elle) habite."},{"id":"verbs-depuis-03","type":"gap","prompt":"Nous ___ le français depuis quatre ans maintenant.","base":"apprendre","answers":["apprenons"],"en":"We have been learning French for four years now.","why":"We are still learning French, so depuis takes the present: nous apprenons."},{"id":"verbs-depuis-04","type":"gap","prompt":"Mon frère ___ au foot depuis l'âge de six ans et il est très fort.","base":"jouer","answers":["joue"],"en":"My brother has played football since he was six and he is very good.","why":"depuis + a point in time means 'since'; he still plays, so the verb is in the present: il joue."},{"id":"verbs-depuis-05","type":"flip","front":"depuis can mean 'for' or 'since'. How do you know which?","back":"depuis + a length of time = for: depuis deux ans (for two years), depuis une heure (for an hour). depuis + a point in time = since: depuis lundi (since Monday), depuis 2021, depuis mon enfance (since my childhood). The verb is in the present either way."},{"id":"verbs-depuis-06","type":"gap","prompt":"Il ___ depuis ce matin ; prends ton parapluie !","base":"pleuvoir","answers":["pleut"],"en":"It has been raining since this morning; take your umbrella!","why":"It is still raining, so depuis takes the present: il pleut."},{"id":"verbs-depuis-07","type":"transform","instruction":"Correct the mistake: the sentence should mean 'I have been waiting for twenty minutes'.","prompt":"J'ai attendu depuis vingt minutes.","answers":["J'attends depuis vingt minutes.","Depuis vingt minutes, j'attends."],"en":"I have been waiting for twenty minutes.","why":"The waiting is still going on, so French uses the present with depuis, not the perfect."},{"id":"verbs-depuis-08","type":"transform","instruction":"Rewrite the sentence using depuis, changing the verb as needed.","prompt":"J'ai commencé à jouer de la guitare il y a trois ans.","answers":["Je joue de la guitare depuis trois ans.","Depuis trois ans, je joue de la guitare."],"en":"I have been playing the guitar for three years.","why":"Started three years ago and still going on = present + depuis: je joue de la guitare depuis trois ans."},{"id":"verbs-depuis-09","type":"flip","front":"What does depuis mean with the imperfect? Translate: Je dormais depuis une heure quand le téléphone a sonné.","back":"'I had been sleeping for an hour when the phone rang.' depuis + imperfect describes something that had been going on up to a moment in the past and was still going on then. English uses 'had been doing'."},{"id":"verbs-depuis-10","type":"gap","prompt":"Quand mon père est rentré, je ___ mes devoirs depuis deux heures.","base":"faire","answers":["faisais"],"en":"When my dad got home, I had been doing my homework for two hours.","why":"The homework was still going on at a moment in the past (when he got home), so depuis takes the imperfect: je faisais (stem fais-, from nous faisons)."},{"id":"verbs-depuis-11","type":"gap","prompt":"Ma grand-mère ___ dans ce village depuis cinquante ans quand elle a déménagé.","base":"habiter","answers":["habitait"],"en":"My grandmother had lived in this village for fifty years when she moved.","why":"depuis + imperfect = 'had been doing' up to a moment in the past: elle habitait."},{"id":"verbs-depuis-12","type":"flip","front":"How do you ask 'How long...?' and 'Since when...?' with depuis?","back":"Depuis combien de temps + present = How long (have you been...)?: Depuis combien de temps apprends-tu le français ? Depuis quand + present = Since when...?: Depuis quand habitez-vous ici ? Answer with depuis + present: J'habite ici depuis 2019."},{"id":"verbs-depuis-13","type":"gap","prompt":"___ habites-tu à Londres ?","hint":"(since when)","answers":["Depuis quand"],"en":"Since when have you been living in London?","why":"Depuis quand asks when something started; the verb is in the present because you still live there."},{"id":"verbs-depuis-14","type":"gap","prompt":"Vous jouez très bien ! Depuis combien de temps ___-vous du basket ?","base":"faire","answers":["faites"],"en":"You play really well! How long have you been playing basketball?","why":"Depuis combien de temps takes the present: vous faites (irregular), inverted to faites-vous."},{"id":"verbs-depuis-15","type":"flip","front":"depuis, pendant or il y a? What is the difference?","back":"depuis + present = for/since, still going on: Je fais du judo depuis deux ans. pendant = for a period that is over, usually with the perfect: J'ai fait du judo pendant deux ans (I've stopped). il y a = ago: J'ai commencé le judo il y a deux ans."},{"id":"verbs-depuis-16","type":"gap","prompt":"J'ai vécu au Maroc ___ deux ans, puis nous sommes rentrés en France.","hint":"(for)","answers":["pendant","durant"],"en":"I lived in Morocco for two years, then we came back to France.","why":"The stay is over (perfect tense, then we came back), so 'for' is pendant, not depuis."},{"id":"verbs-depuis-17","type":"gap","prompt":"Nous sommes arrivés à Nice ___ trois jours.","hint":"(ago)","answers":["il y a"],"en":"We arrived in Nice three days ago.","why":"il y a + a length of time = ago; it goes with a completed action in the perfect tense."},{"id":"verbs-depuis-18","type":"gap","prompt":"Je fais de la natation ___ trois ans et j'adore ça.","hint":"(for)","answers":["depuis"],"en":"I have been swimming for three years and I love it.","why":"The verb is in the present and I still swim, so 'for' is depuis, not pendant."}]},{"id":"verbs-passive","order":33,"area":"Verbs","title":"Passive voice (recognition)","spec":"Verbs: passive voice (R)","receptive":true,"summary":["You only need to recognise and understand the passive, not produce it.","The passive shows what is done to the subject: être + past participle: La maison est vendue = The house is sold.","The participle agrees with the subject like an adjective: Les fenêtres sont nettoyées.","par introduces who or what does the action: Le match est regardé par des millions de supporters.","The tense is shown by être: est construit (is built), a été construit (was built / has been built), sera construit (will be built).","With a few verbs of feeling, de replaces par: Ce professeur est respecté de tous.","Don't confuse it with the perfect of être verbs: elle est partie = she has left (not passive); la lettre est envoyée = the letter is sent (passive).","French often avoids the passive by using on: On parle français ici = French is spoken here."],"cards":[{"id":"verbs-passive-01","type":"flip","front":"What is the passive voice and how is it formed?","back":"The passive shows what is done to the subject rather than what the subject does. Form: être + past participle (+ par + the doer): Le gâteau est préparé par mon père = The cake is prepared by my father. The tense is shown by être."},{"id":"verbs-passive-02","type":"flip","front":"Translate: Les tables sont réservées pour ce soir. Why -es on réservées?","back":"The tables are reserved for this evening. In the passive the participle agrees with the subject like an adjective: les tables is feminine plural, so réservées."},{"id":"verbs-passive-03","type":"flip","front":"Translate: Le match est regardé par des millions de supporters.","back":"The match is watched by millions of fans. par introduces the person or thing doing the action."},{"id":"verbs-passive-04","type":"flip","front":"Translate: En ville, la pollution est causée surtout par les voitures.","back":"In town, pollution is caused mainly by cars. Present passive: est + causée (feminine, agreeing with la pollution)."},{"id":"verbs-passive-05","type":"flip","front":"Translate: Ce château a été construit au quinzième siècle.","back":"This castle was built in the fifteenth century. a été + past participle is the passive in the perfect tense: 'was built' or 'has been built'."},{"id":"verbs-passive-06","type":"flip","front":"Translate: Le voleur a été arrêté par la police devant la banque.","back":"The thief was arrested by the police outside the bank. Perfect passive: a été arrêté."},{"id":"verbs-passive-07","type":"flip","front":"Translate: Ma sœur a été choisie pour l'équipe de basket.","back":"My sister was (has been) chosen for the basketball team. choisie agrees with ma sœur (feminine singular)."},{"id":"verbs-passive-08","type":"flip","front":"Translate: Les résultats des examens seront publiés en août.","back":"The exam results will be published in August. seront (future of être) + past participle = future passive: 'will be ...'."},{"id":"verbs-passive-09","type":"flip","front":"Elle est partie or Elle est invitée: which is passive, and how can you tell?","back":"Elle est invitée (she is invited) is passive: inviter normally takes avoir in the perfect (elle a invité), so est + invitée must be passive. Elle est partie (she has left) is the ordinary perfect tense of partir, one of the être verbs. Ask yourself: is something being done to her by someone?"},{"id":"verbs-passive-10","type":"flip","front":"Which sentence is passive? (a) Nous sommes allés au parc. (b) Nous sommes invités chez Marc. (c) Nous avons visité le musée.","back":"(b) We are invited to Marc's house. (a) is the perfect tense of aller, an être verb (we went to the park), and (c) is the perfect tense with avoir (we visited the museum)."},{"id":"verbs-passive-11","type":"flip","front":"How does French often avoid the passive? Translate: On a volé mon vélo. / Ici, on parle anglais.","back":"With on + an active verb: 'My bike has been stolen.' / 'English is spoken here.' English often uses a passive where French prefers on."},{"id":"verbs-passive-12","type":"flip","front":"Translate: On m'a offert un portable pour mon anniversaire.","back":"I was given a mobile phone for my birthday. French cannot make 'I' the subject of a passive here, so it uses on: literally 'someone gave me a phone'."}]},{"id":"verbs-imperative","order":34,"area":"Verbs","title":"Imperative (commands)","spec":"Verbs: imperative","receptive":false,"summary":["The imperative gives orders, instructions and advice. Take the tu, nous or vous form of the present tense and drop the subject pronoun: Finis ! Écoutons ! Prenez !","-er verbs, aller, and verbs like ouvrir and offrir (tu ouvres, tu offres) drop the -s of the tu form: tu regardes -> Regarde ! tu vas -> Va ! tu ouvres -> Ouvre !","The -s comes back before y and en: Vas-y ! Achètes-en !","The nous form means 'let's': Partons ! Allons au cinéma !","Irregular forms: être -> sois, soyons, soyez; avoir -> aie, ayons, ayez. Also recognise savoir -> sache, sachez and vouloir -> veuillez (Veuillez patienter = Please wait).","Negative commands: ne ... pas goes round the verb: Ne crie pas ! Ne courez pas !","Positive commands: object and reflexive pronouns go after the verb with a hyphen, and me/te become moi/toi: Lève-toi ! Regarde-moi ! Prends-le !","With two pronouns in a positive command, the direct object comes first: Donne-le-moi ! Envoie-la-moi !","Negative commands: the pronouns go back in front of the verb in their normal form: Ne te lève pas ! Ne le prends pas !"],"cards":[{"id":"verbs-imperative-01","type":"flip","front":"How do you form the imperative (a command)?","back":"Use the tu, nous or vous form of the present tense without the pronoun: tu finis -> Finis ! nous partons -> Partons ! (Let's leave!) vous écoutez -> Écoutez ! -er verbs drop the -s in the tu form: tu regardes -> Regarde !"},{"id":"verbs-imperative-02","type":"gap","prompt":"Tu as soif ? ___ de l'eau !","base":"boire","answers":["Bois"],"en":"Are you thirsty? Drink some water!","why":"The tu form of boire in the present (tu bois) without the pronoun: Bois !"},{"id":"verbs-imperative-03","type":"gap","prompt":"Paul, ___ la porte, s'il te plaît !","base":"fermer","answers":["ferme"],"en":"Paul, close the door, please!","why":"fermer is an -er verb, so the tu command drops the -s: tu fermes -> Ferme !"},{"id":"verbs-imperative-04","type":"gap","prompt":"Les enfants, ___ vos devoirs avant de jouer !","base":"finir","answers":["finissez"],"en":"Children, finish your homework before you play!","why":"Speaking to several people, so use the vous form without the pronoun: Finissez !"},{"id":"verbs-imperative-05","type":"gap","prompt":"Il fait beau : ___ au parc cet après-midi !","base":"aller","hint":"let's","answers":["allons"],"en":"It's sunny: let's go to the park this afternoon!","why":"The nous form of the imperative means 'let's': Allons !"},{"id":"verbs-imperative-06","type":"flip","front":"When does the tu imperative drop its -s, and when does it keep it?","back":"-er verbs, aller, and verbs like ouvrir, offrir and découvrir (whose tu form ends in -es) drop the -s: tu manges -> Mange ! tu vas -> Va ! tu ouvres -> Ouvre ! Other verbs keep it: Finis ! Prends ! Fais ! The -s comes back before y or en so that it is easier to say: Vas-y ! Manges-en !"},{"id":"verbs-imperative-07","type":"transform","instruction":"Turn the sentence into a command.","prompt":"Tu ouvres la fenêtre.","answers":["Ouvre la fenêtre !"],"en":"Open the window!","why":"ouvrir has -er-type endings in the present (tu ouvres), so, like an -er verb, it drops the -s in the tu command: Ouvre."},{"id":"verbs-imperative-08","type":"gap","prompt":"Tu veux aller à la piscine ? Alors ___-y !","base":"aller","answers":["vas"],"en":"You want to go to the swimming pool? Then go!","why":"Va ! normally has no -s, but before y the -s comes back for the sound: Vas-y !"},{"id":"verbs-imperative-09","type":"flip","front":"Which verbs have irregular imperatives?","back":"être: sois, soyons, soyez (Sois sage ! = Be good!). avoir: aie, ayons, ayez (N'aie pas peur ! = Don't be afraid!). To recognise: savoir -> sache, sachons, sachez; vouloir -> veuillez, used in polite notices: Veuillez fermer la porte = Please close the door."},{"id":"verbs-imperative-10","type":"gap","prompt":"___ sage chez ta grand-mère !","base":"être","answers":["Sois"],"en":"Be good at your grandmother's!","why":"être has an irregular imperative: sois (tu), soyons (nous), soyez (vous). ta shows it is the tu form."},{"id":"verbs-imperative-11","type":"gap","prompt":"___ confiance en toi : tu vas réussir !","base":"avoir","answers":["Aie"],"en":"Have confidence in yourself: you're going to succeed!","why":"avoir has an irregular imperative: aie (tu), ayons (nous), ayez (vous). toi shows it is the tu form."},{"id":"verbs-imperative-12","type":"flip","front":"Where do pronouns go in positive and negative commands? Use se lever.","back":"Positive: after the verb with a hyphen, and te/me become toi/moi: Lève-toi ! Levons-nous ! Levez-vous ! Negative: in front of the verb in their normal form: Ne te lève pas ! Ne vous levez pas ! Object pronouns work the same way: Prends-le ! / Ne le prends pas !"},{"id":"verbs-imperative-13","type":"gap","prompt":"Il est sept heures, ___ ! Tu vas être en retard.","base":"se lever","answers":["lève-toi"],"en":"It's seven o'clock, get up! You're going to be late.","why":"Positive reflexive command: the pronoun goes after the verb with a hyphen and te becomes toi: Lève-toi !"},{"id":"verbs-imperative-14","type":"gap","prompt":"Nous sommes en retard : ___ !","base":"se dépêcher","hint":"let's","answers":["dépêchons-nous"],"en":"We're late: let's hurry!","why":"nous imperative of a reflexive verb: the pronoun nous follows the verb with a hyphen: Dépêchons-nous !"},{"id":"verbs-imperative-15","type":"transform","instruction":"Make the command negative.","prompt":"Lève-toi !","answers":["Ne te lève pas !"],"en":"Don't get up!","why":"In a negative command the pronoun goes back in front of the verb as te, and ne ... pas goes round both."},{"id":"verbs-imperative-16","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Achète **le pain** !","answers":["Achète-le !"],"en":"Buy it!","why":"In a positive command the object pronoun goes after the verb, joined by a hyphen: Achète-le !"},{"id":"verbs-imperative-17","type":"transform","instruction":"Make the command negative.","prompt":"Mange-les !","answers":["Ne les mange pas !"],"en":"Don't eat them!","why":"In a negative command the pronoun goes back in front of the verb: Ne les mange pas !"},{"id":"verbs-imperative-18","type":"transform","instruction":"Replace the words in bold with a pronoun.","prompt":"Envoie-moi **la photo** !","answers":["Envoie-la-moi !"],"en":"Send it to me!","why":"With two pronouns after a positive command, the direct object comes first and both are joined by hyphens: Envoie-la-moi !"}]},{"id":"verbs-perfect-infinitive","order":35,"area":"Verbs","title":"Perfect infinitive (après avoir / après être)","spec":"Verbs: perfect infinitive","receptive":false,"summary":["après avoir + past participle = 'after doing' or 'after having done': Après avoir mangé, j'ai fait mes devoirs.","Verbs that take être in the perfect use après être + past participle: Après être arrivé, il a appelé sa mère.","With être, the participle agrees with the subject of the main clause: Après être rentrées, mes sœurs ont dîné.","Reflexive verbs use après + reflexive pronoun + être, with the pronoun matching the subject: Après m'être levé, j'ai pris une douche. Après nous être habillés, nous sommes sortis.","The same person must do both actions: Après avoir fini le match, les joueurs sont rentrés (the players finished and went home).","The main clause can be in any tense: Après avoir passé mes examens, je partirai en vacances.","The après part can come first or second: Je suis sorti après avoir mangé."],"cards":[{"id":"verbs-perfect-infinitive-01","type":"flip","front":"What does après avoir + past participle mean? Give an example.","back":"'After doing' or 'after having done'. Après avoir regardé le film, nous sommes allés au café = After watching (having watched) the film, we went to the café. English often uses '-ing' here, but French needs avoir + past participle."},{"id":"verbs-perfect-infinitive-02","type":"gap","prompt":"Après avoir ___ mes devoirs, j'ai joué aux jeux vidéo.","base":"finir","answers":["fini"],"en":"After finishing my homework, I played video games.","why":"après avoir + past participle: finir -> fini."},{"id":"verbs-perfect-infinitive-03","type":"gap","prompt":"Après ___ le petit déjeuner, je suis parti au collège.","base":"prendre","answers":["avoir pris"],"en":"After having breakfast, I left for school.","why":"prendre takes avoir in the perfect, so: après avoir + pris (irregular past participle)."},{"id":"verbs-perfect-infinitive-04","type":"gap","prompt":"Après ___ le film, nous sommes allés au café.","base":"voir","answers":["avoir vu"],"en":"After seeing the film, we went to the café.","why":"voir takes avoir and its past participle is vu: après avoir vu."},{"id":"verbs-perfect-infinitive-05","type":"flip","front":"When do you use après être instead of après avoir? What happens to the participle?","back":"With verbs that take être in the perfect (aller, arriver, partir, sortir, rentrer, tomber etc.). The participle agrees with the subject of the main clause: Après être arrivée à la gare, ma mère a acheté un billet. Après être sortis, les garçons ont joué au foot."},{"id":"verbs-perfect-infinitive-06","type":"gap","prompt":"Après ___ à l'hôtel, mon père a garé la voiture.","base":"arriver","answers":["être arrivé"],"en":"After arriving at the hotel, my father parked the car.","why":"arriver takes être, so après être arrivé; mon père is masculine singular, so no extra ending."},{"id":"verbs-perfect-infinitive-07","type":"gap","prompt":"Après ___ de l'école, ma sœur a promené le chien.","base":"rentrer","answers":["être rentrée"],"en":"After getting home from school, my sister walked the dog.","why":"rentrer takes être; the participle agrees with ma sœur (feminine singular): rentrée."},{"id":"verbs-perfect-infinitive-08","type":"gap","prompt":"Après être ___ du cinéma, les filles ont pris un taxi.","base":"sortir","answers":["sorties"],"en":"After leaving the cinema, the girls took a taxi.","why":"sortir takes être; the participle agrees with les filles (feminine plural): sorties."},{"id":"verbs-perfect-infinitive-09","type":"transform","instruction":"Join the sentences using après + perfect infinitive.","prompt":"J'ai mangé. Ensuite, je suis sorti.","answers":["Après avoir mangé, je suis sorti.","Je suis sorti après avoir mangé."],"en":"After eating, I went out.","why":"manger takes avoir, so après avoir mangé; the subject (je) is the same for both actions."},{"id":"verbs-perfect-infinitive-10","type":"flip","front":"How do you form the perfect infinitive of a reflexive verb?","back":"après + reflexive pronoun + être + past participle. The pronoun matches the subject and the participle agrees with it: Après m'être réveillé(e), j'ai mangé. Après s'être douchée, elle s'est habillée. Après nous être préparés, nous sommes partis."},{"id":"verbs-perfect-infinitive-11","type":"gap","prompt":"Après ___, Thomas s'est habillé.","base":"se doucher","answers":["s'être douché"],"en":"After having a shower, Thomas got dressed.","why":"Reflexive verb: après s'être + past participle; Thomas is masculine singular, so douché."},{"id":"verbs-perfect-infinitive-12","type":"gap","prompt":"Après ___ très tôt, je suis allée courir dans le parc.","base":"se lever","answers":["m'être levée"],"en":"After getting up very early, I went running in the park.","why":"The subject is je, so se becomes m'; allée shows that je is female, so levée agrees."},{"id":"verbs-perfect-infinitive-13","type":"transform","instruction":"Join the sentences using après + perfect infinitive.","prompt":"Elle est rentrée. Ensuite, elle a dîné.","answers":["Après être rentrée, elle a dîné.","Elle a dîné après être rentrée."],"en":"After getting home, she had dinner.","why":"rentrer takes être, so après être rentrée, with the participle agreeing with elle."},{"id":"verbs-perfect-infinitive-14","type":"transform","instruction":"Join the sentences using après + perfect infinitive.","prompt":"Nous nous sommes habillés. Ensuite, nous sommes sortis.","answers":["Après nous être habillés, nous sommes sortis.","Nous sommes sortis après nous être habillés."],"en":"After getting dressed, we went out.","why":"Reflexive verb: après nous être habillés; the pronoun matches nous and habillés agrees with a masculine plural subject."},{"id":"verbs-perfect-infinitive-15","type":"gap","prompt":"Après ___ mes examens, je partirai en vacances.","base":"passer","answers":["avoir passé"],"en":"After taking my exams, I will go on holiday.","why":"passer un examen takes avoir: après avoir passé. The main clause can be in any tense, here the future."},{"id":"verbs-perfect-infinitive-16","type":"flip","front":"Is this right? 'Après avoir mangé, ma mère m'a appelé.' (meaning: after I had eaten, my mother called me)","back":"No. The perfect infinitive must have the same subject as the main verb, so this sentence says that my mother had eaten. To say what you mean, use two full verbs: J'avais mangé quand ma mère m'a appelé(e)."}]},{"id":"verbs-present-participle","order":36,"area":"Verbs","title":"Present participle and en + -ant","spec":"Verbs: present participle, including use after en","receptive":false,"summary":["Form: take the nous form of the present, remove -ons and add -ant: nous regardons -> regardant, nous finissons -> finissant, nous faisons -> faisant.","-ger and -cer verbs keep their nous spelling: nous mangeons -> mangeant, nous commençons -> commençant.","Only three are irregular: être -> étant, avoir -> ayant, savoir -> sachant.","en + present participle = while, on or by doing something: Je chante en prenant ma douche. On apprend en écoutant.","The en + -ant action is done by the subject of the main verb: En sortant du cinéma, nous avons vu Marc (we were coming out).","tout en + -ant stresses that two things happen at the same time: Il révise tout en écoutant de la musique.","Used as a verb, the present participle never changes its ending: en arrivant, whoever is arriving.","With reflexive verbs the pronoun matches the subject: en me levant, en nous promenant.","Don't use -ant for English '-ing' after another verb or for 'am doing': J'aime nager (I like swimming). Je mange (I am eating)."],"cards":[{"id":"verbs-present-participle-01","type":"flip","front":"How do you form the present participle (the '-ing' form)?","back":"Take the nous form of the present tense, remove -ons and add -ant: nous parlons -> parlant, nous finissons -> finissant, nous prenons -> prenant, nous faisons -> faisant. Used as a verb, it never changes its ending."},{"id":"verbs-present-participle-02","type":"gap","prompt":"Je prends mon petit déjeuner en ___ les infos.","base":"regarder","answers":["regardant"],"en":"I have my breakfast while watching the news.","why":"nous regardons -> regard- + -ant. en + present participle = while doing."},{"id":"verbs-present-participle-03","type":"gap","prompt":"Mon père écoute la radio en ___ sa voiture.","base":"conduire","answers":["conduisant"],"en":"My dad listens to the radio while driving his car.","why":"nous conduisons -> conduis- + -ant = conduisant."},{"id":"verbs-present-participle-04","type":"gap","prompt":"On reste en forme en ___ du sport régulièrement.","base":"faire","answers":["faisant"],"en":"You keep fit by doing sport regularly.","why":"nous faisons -> fais- + -ant. Here en + -ant means 'by doing'."},{"id":"verbs-present-participle-05","type":"flip","front":"What can en + present participle mean? Give examples.","back":"While: Je chante en prenant ma douche (I sing while having a shower). By: On apprend en pratiquant (You learn by practising). On/when: En arrivant au collège, j'ai vu mes amis (On arriving at school, I saw my friends). The same person does both actions."},{"id":"verbs-present-participle-06","type":"gap","prompt":"En ___ mes devoirs tôt, j'ai pu sortir avec mes amis.","base":"finir","answers":["finissant"],"en":"By finishing my homework early, I was able to go out with my friends.","why":"-ir verbs like finir have nous finissons, so the present participle is finissant."},{"id":"verbs-present-participle-07","type":"transform","instruction":"Replace the words in bold with en + present participle.","prompt":"On apprend beaucoup **quand on voyage**.","answers":["On apprend beaucoup en voyageant."],"en":"You learn a lot by travelling.","why":"voyager: nous voyageons -> voyageant (the e after g stays). Both verbs have the same subject, on."},{"id":"verbs-present-participle-08","type":"flip","front":"Which present participles have a spelling change or are irregular?","back":"-ger verbs keep the e: mangeant, nageant, voyageant. -cer verbs keep the ç: commençant, lançant. Irregular: être -> étant, avoir -> ayant, savoir -> sachant."},{"id":"verbs-present-participle-09","type":"gap","prompt":"Ne parle pas en ___, s'il te plaît !","base":"manger","answers":["mangeant"],"en":"Don't talk while you're eating, please!","why":"manger keeps the e before -ant to keep the soft g sound: nous mangeons -> mangeant."},{"id":"verbs-present-participle-10","type":"gap","prompt":"En ___ ses études, Lucie a trouvé un petit boulot.","base":"commencer","answers":["commençant"],"en":"When she started her studies, Lucie found a part-time job.","why":"commencer keeps the ç before a to keep the soft c sound: nous commençons -> commençant."},{"id":"verbs-present-participle-11","type":"gap","prompt":"___ malade, je suis resté au lit toute la journée.","base":"être","answers":["Étant"],"en":"Being ill, I stayed in bed all day.","why":"être has the irregular present participle étant."},{"id":"verbs-present-participle-12","type":"gap","prompt":"___ peu de temps, nous avons pris un taxi.","base":"avoir","answers":["Ayant"],"en":"Having little time, we took a taxi.","why":"avoir has the irregular present participle ayant."},{"id":"verbs-present-participle-13","type":"gap","prompt":"___ que le magasin fermait à midi, nous sommes partis tôt.","base":"savoir","answers":["Sachant"],"en":"Knowing that the shop closed at midday, we left early.","why":"savoir has the irregular present participle sachant."},{"id":"verbs-present-participle-14","type":"transform","instruction":"Join the sentences: turn the verb in bold into en + present participle.","prompt":"Je fais mes devoirs. **J'écoute** de la musique.","answers":["Je fais mes devoirs en écoutant de la musique.","En écoutant de la musique, je fais mes devoirs.","Je fais mes devoirs tout en écoutant de la musique.","Tout en écoutant de la musique, je fais mes devoirs."],"en":"I do my homework while listening to music.","why":"Both actions are done by the same person at the same time: en écoutant (nous écoutons -> écoutant)."},{"id":"verbs-present-participle-15","type":"flip","front":"What does tout en + present participle add? Translate: Elle travaille tout en écoutant la radio.","back":"'She works while listening to the radio (at the same time).' tout stresses that the two actions happen together. It can also show a contrast: Tout en étant fatigué, il a fini le marathon = Although he was tired, he finished the marathon."},{"id":"verbs-present-participle-16","type":"gap","prompt":"Ma sœur fait ses devoirs tout en ___ des messages à ses amies.","base":"envoyer","answers":["envoyant"],"en":"My sister does her homework while sending messages to her friends.","why":"nous envoyons -> envoy- + -ant = envoyant. tout en stresses that both things happen at the same time."},{"id":"verbs-present-participle-17","type":"gap","prompt":"En ___ ce matin, j'ai vu qu'il neigeait.","base":"se réveiller","answers":["me réveillant"],"en":"When I woke up this morning, I saw that it was snowing.","why":"With a reflexive verb the pronoun matches the subject (je), so se becomes me: en me réveillant."},{"id":"verbs-present-participle-18","type":"flip","front":"How do you say 'I like swimming' and 'I am eating'? Why not use -ant?","back":"J'aime nager (verb + infinitive) and Je mange or Je suis en train de manger. The present participle is not used after another verb or to make English '-ing' tenses; French uses the infinitive or the ordinary present."}]},{"id":"verbs-subjunctive","order":37,"area":"Verbs","title":"Present subjunctive (recognition)","spec":"Verbs: subjunctive mood: present, in commonly used expressions (R)","receptive":true,"summary":["The subjunctive is a verb form used after certain expressions with que. You need to recognise and understand it, not produce it.","Regular forms: ils form of the present minus -ent, plus -e, -es, -e, -ions, -iez, -ent: ils finissent -> que je finisse, ils partent -> que tu partes.","For -er verbs most forms look the same as the present: qu'il parle. The expression before que tells you it is subjunctive.","Common triggers: il faut que (must), vouloir que (to want ... to), avant que (before), bien que (although), pour que (so that), avoir peur que (to be afraid that), je ne pense pas que (I don't think that).","Key irregular forms: être -> que je sois, avoir -> que j'aie, aller -> que j'aille, faire -> que je fasse, pouvoir -> que je puisse, vouloir -> que je veuille, savoir -> que je sache.","Translate for meaning, not word for word: Il faut que tu partes = You must leave. Ma mère veut que je range ma chambre = My mum wants me to tidy my room.","je pense que + normal verb, but je ne pense pas que + subjunctive: Je pense qu'il est là. / Je ne pense pas qu'il soit là.","When the subject is the same, French uses an infinitive instead: Je veux partir (I want to leave), but Je veux que tu partes (I want you to leave)."],"cards":[{"id":"verbs-subjunctive-01","type":"flip","front":"What is the subjunctive and how do you spot it?","back":"A special verb form used after certain expressions ending in que (il faut que, bien que, pour que...). Regular forms: ils form of the present minus -ent, plus -e, -es, -e, -ions, -iez, -ent: ils finissent -> que je finisse, que nous finissions. Look for a trigger + que + an unusual verb form."},{"id":"verbs-subjunctive-02","type":"flip","front":"Name seven common expressions that are followed by the subjunctive.","back":"il faut que (must / it is necessary that), vouloir que (to want ... to), avant que (before), bien que (although), pour que (so that), avoir peur que (to be afraid that), je ne pense pas que (I don't think that)."},{"id":"verbs-subjunctive-03","type":"flip","front":"Which infinitives do these subjunctive forms come from: sois, aie, aille, fasse, puisse, veuille, sache?","back":"sois -> être, aie -> avoir, aille -> aller, fasse -> faire, puisse -> pouvoir, veuille -> vouloir, sache -> savoir."},{"id":"verbs-subjunctive-04","type":"flip","front":"Translate: Il faut que tu fasses tes devoirs ce soir.","back":"You must do your homework this evening. (il faut que + subjunctive; fasses is from faire.)"},{"id":"verbs-subjunctive-05","type":"flip","front":"Translate: Mes parents veulent que je sois médecin.","back":"My parents want me to be a doctor. (vouloir que + subjunctive; sois is from être. English says 'want me to be', French says 'want that I be'.)"},{"id":"verbs-subjunctive-06","type":"flip","front":"Translate: Il faut que j'aille chez le dentiste demain.","back":"I have to go to the dentist tomorrow. (il faut que + subjunctive; aille is from aller.)"},{"id":"verbs-subjunctive-07","type":"flip","front":"Translate: Bien qu'il pleuve, nous allons faire une randonnée.","back":"Although it is raining, we are going to go hiking. (bien que = although; pleuve is from pleuvoir.)"},{"id":"verbs-subjunctive-08","type":"flip","front":"Translate: Le prof répète la règle pour que nous puissions faire l'exercice.","back":"The teacher repeats the rule so that we can do the exercise. (pour que = so that; puissions is from pouvoir.)"},{"id":"verbs-subjunctive-09","type":"flip","front":"Translate: Rentrons avant qu'il fasse nuit.","back":"Let's go home before it gets dark. (avant que = before; fasse is from faire: il fait nuit = it is dark.)"},{"id":"verbs-subjunctive-10","type":"flip","front":"Translate: Je ne pense pas qu'elle ait raison. Why ait and not a?","back":"I don't think she is right. Je pense que takes the normal verb (Je pense qu'elle a raison), but je ne pense pas que takes the subjunctive: ait, from avoir (avoir raison = to be right)."},{"id":"verbs-subjunctive-11","type":"flip","front":"Translate: J'ai peur que mon frère ne veuille pas venir à la fête.","back":"I'm afraid my brother won't want to come to the party. (avoir peur que + subjunctive; veuille is from vouloir. The present subjunctive often refers to the future.)"},{"id":"verbs-subjunctive-12","type":"flip","front":"Why do we say 'Je veux savoir la vérité' but 'Je veux que tu saches la vérité'?","back":"When the same person wants and does the action, use the infinitive: Je veux savoir la vérité (I want to know the truth). When the subjects are different, use que + subjunctive: Je veux que tu saches la vérité (I want you to know the truth). saches is from savoir."}]},{"id":"conjunctions","order":38,"area":"Conjunctions","title":"Coordinating and subordinating conjunctions","spec":"Conjunctions: co-ordinating (e.g. car, donc, ensuite) and subordinating (e.g. lorsque, puisque, comme)","receptive":false,"summary":["Coordinating conjunctions join two equal ideas: et (and), mais (but), ou (or), car (because), donc (so): Il pleut, donc je reste à la maison.","Sequencing words order events: d'abord (first), puis / ensuite (then), alors (so, then), enfin (finally).","car and parce que both mean because; car is a little more formal and cannot start a sentence; parce que becomes parce qu' before a vowel.","Subordinating conjunctions introduce a clause: quand / lorsque (when), puisque / comme (since, as), si (if), pendant que (while), parce que (because).","comme meaning as / since goes at the start of the sentence: Comme il pleuvait, nous sommes restés à la maison.","si becomes s' only before il and ils: s'il fait beau, but si elle vient.","After quand and lorsque, use the future when the action is in the future: Quand je serai grand, je serai médecin.","bien que (although) is followed by the subjunctive; you only need to recognise it: bien qu'il soit fatigué."],"cards":[{"id":"conjunctions-01","type":"flip","front":"Give the French for: and, but, or, because, so / therefore, then.","back":"et, mais, ou, car (or parce que), donc (or alors), puis / ensuite. J'aime le foot mais je préfère le tennis."},{"id":"conjunctions-02","type":"gap","prompt":"J'aime le français ___ je n'aime pas les maths.","hint":"(but)","answers":["mais"],"en":"I like French but I don't like maths.","why":"mais (but) joins two contrasting ideas."},{"id":"conjunctions-03","type":"gap","prompt":"Tu préfères le thé ___ le café ?","hint":"(or)","answers":["ou"],"en":"Do you prefer tea or coffee?","why":"ou (or) has no accent; où with an accent means where."},{"id":"conjunctions-04","type":"gap","prompt":"Il pleuvait, ___ nous sommes restés à la maison.","hint":"(so)","answers":["donc","alors"],"en":"It was raining, so we stayed at home.","why":"donc or alors (so) introduces a result."},{"id":"conjunctions-05","type":"gap","prompt":"D'abord, je prends une douche, ___ je m'habille.","hint":"(then)","answers":["puis","ensuite","après"],"en":"First I have a shower, then I get dressed.","why":"puis or ensuite (then) puts actions in order after d'abord (first); après is also used in everyday French."},{"id":"conjunctions-06","type":"flip","front":"car or parce que: what is the difference?","back":"Both mean because. car is slightly more formal and cannot start a sentence. parce que can, and becomes parce qu' before a vowel: parce qu'il fait froid."},{"id":"conjunctions-07","type":"gap","prompt":"J'aimerais travailler à l'étranger ___ j'adore voyager.","hint":"(because)","answers":["car","parce que"],"en":"I would like to work abroad because I love travelling.","why":"car or parce que (because) gives a reason; both are correct in the middle of a sentence."},{"id":"conjunctions-08","type":"transform","instruction":"Join the two sentences with parce que.","prompt":"Elle est fatiguée. Elle a mal dormi.","answers":["Elle est fatiguée parce qu'elle a mal dormi."],"en":"She is tired because she slept badly.","why":"parce que gives the reason; que becomes qu' before a vowel: parce qu'elle."},{"id":"conjunctions-09","type":"flip","front":"Give the French for: when (two ways), since / as (two ways), if, while.","back":"quand / lorsque, puisque / comme, si, pendant que. Lorsque je suis arrivé, il pleuvait. Puisque tu es là, aide-moi !"},{"id":"conjunctions-10","type":"gap","prompt":"___ j'étais petit, j'habitais à la campagne.","hint":"(when)","answers":["Quand","Lorsque"],"en":"When I was little, I lived in the countryside.","why":"quand or lorsque (when) introduces a time clause; lorsque is slightly more formal."},{"id":"conjunctions-11","type":"gap","prompt":"___ tu es malade, tu devrais rester au lit.","hint":"(since)","answers":["Puisque","Comme"],"en":"Since you're ill, you should stay in bed.","why":"puisque or comme (since, as) gives a reason that is already known; comme in this sense starts the sentence."},{"id":"conjunctions-12","type":"gap","prompt":"Mon père fait la cuisine ___ ma mère lit le journal.","hint":"(while)","answers":["pendant que","tandis que","alors que"],"en":"My father does the cooking while my mother reads the newspaper.","why":"pendant que (while) links two actions happening at the same time."},{"id":"conjunctions-13","type":"flip","front":"When does si become s'?","back":"Only before il and ils: s'il pleut, s'ils viennent. It stays si before elle, on and other vowels: si elle veut, si on va au parc."},{"id":"conjunctions-14","type":"transform","instruction":"Join the two sentences into one, starting with the French for 'if'. Keep the verbs as they are.","prompt":"Il pleut. Je reste à la maison.","answers":["S'il pleut, je reste à la maison."],"en":"If it rains, I stay at home.","why":"si introduces the condition and becomes s' before il: s'il pleut."},{"id":"conjunctions-15","type":"flip","front":"Which tense follows quand or lorsque when you talk about the future?","back":"The future, unlike English: Quand j'aurai dix-huit ans, j'apprendrai à conduire (When I am eighteen...). Not quand j'ai dix-huit ans for a future event."},{"id":"conjunctions-16","type":"gap","prompt":"Quand je ___ grand, j'habiterai au bord de la mer.","base":"être","answers":["serai"],"en":"When I'm older, I'll live by the sea.","why":"The action is in the future (j'habiterai), so quand is followed by the future tense too: je serai, not je suis."},{"id":"conjunctions-17","type":"transform","instruction":"Join the two sentences into one, starting with Comme (as / since).","prompt":"Il pleuvait. Nous sommes restés à la maison.","answers":["Comme il pleuvait, nous sommes restés à la maison."],"en":"As it was raining, we stayed at home.","why":"comme meaning as / since introduces the reason and goes at the start of the sentence."},{"id":"conjunctions-18","type":"flip","front":"What does bien que mean, and what is special about the verb after it?","back":"bien que = although. It is followed by the subjunctive, which you only need to recognise: Bien qu'il soit malade, il va au collège (Although he is ill, he goes to school)."}]},{"id":"numbers-dates-time","order":39,"area":"Numbers, quantity, dates and time","title":"Numbers, dates, time and quantities","spec":"Numbers, quantity, dates and time, including use of depuis with present and imperfect tenses","receptive":false,"summary":["70-79 are built on soixante: soixante-dix (70), soixante et onze (71), soixante-douze (72) … soixante-dix-neuf (79).","80-99 are built on quatre-vingts: quatre-vingts (80), quatre-vingt-un (81), quatre-vingt-dix (90), quatre-vingt-dix-neuf (99).","et appears in 21, 31, 41, 51, 61 and 71 (vingt et un, soixante et onze) but not in 81 or 91 (quatre-vingt-un, quatre-vingt-onze).","vingt and cent take -s only when multiplied and nothing follows: quatre-vingts, deux cents, but quatre-vingt-trois, deux cent dix. mille never takes -s: deux mille.","Ordinals add -ième: deuxième, troisième, cinquième, neuvième; first is premier / première.","Dates use normal numbers except the first: le premier mai, le quatorze juillet; years: en deux mille vingt-cinq. Months and days have no capital.","Time: Il est huit heures et quart / et demie / moins le quart; midi et demi; 24-hour clock: dix-sept heures quarante (17h40).","Quantities take plain de: un kilo de pommes, une bouteille d'eau, un paquet de chips; but la moitié is followed by de + article: la moitié du gâteau.","depuis + present for something still going on: J'apprends le français depuis cinq ans (I have been learning French for five years).","depuis + imperfect for something that had been going on when something else happened: J'attendais depuis une heure quand le bus est arrivé (I had been waiting for an hour when the bus arrived)."],"cards":[{"id":"numbers-dates-time-01","type":"flip","front":"How are the numbers 70-99 built in French?","back":"70-79 = soixante + 10-19: soixante-dix, soixante et onze, soixante-quinze. 80-99 = quatre-vingt(s) + 0-19: quatre-vingts, quatre-vingt-un, quatre-vingt-dix, quatre-vingt-dix-neuf. et only in 21-71, never in 81 or 91."},{"id":"numbers-dates-time-02","type":"gap","prompt":"Ma grand-mère a ___ ans.","hint":"(75, in words)","answers":["soixante-quinze"],"en":"My grandmother is 75.","why":"75 = 60 + 15: soixante-quinze, with a hyphen."},{"id":"numbers-dates-time-03","type":"gap","prompt":"Mon arrière-grand-père a ___ ans.","hint":"(80, in words)","answers":["quatre-vingts"],"en":"My great-grandfather is 80.","why":"80 = four twenties; vingt is multiplied and nothing follows, so it takes -s: quatre-vingts."},{"id":"numbers-dates-time-04","type":"gap","prompt":"Le billet de train coûte ___ euros.","hint":"(91, in words)","answers":["quatre-vingt-onze"],"en":"The train ticket costs 91 euros.","why":"91 = 80 + 11: quatre-vingt-onze. No et and no -s on vingt, because a number follows."},{"id":"numbers-dates-time-05","type":"gap","prompt":"Il y a ___ jours en mai.","hint":"(31, in words)","answers":["trente et un","trente-et-un"],"en":"There are 31 days in May.","why":"21, 31, 41, 51, 61 and 71 use et: trente et un (the reformed spelling trente-et-un is also accepted)."},{"id":"numbers-dates-time-06","type":"flip","front":"When do vingt and cent take an -s, and what about mille?","back":"Only when they are multiplied and nothing follows: quatre-vingts, deux cents, trois cents. With a number after them, no -s: quatre-vingt-deux, deux cent vingt. mille never changes: deux mille, trois mille euros."},{"id":"numbers-dates-time-07","type":"gap","prompt":"Il y a ___ élèves dans mon collège.","hint":"(200, in words)","answers":["deux cents","deux-cents"],"en":"There are 200 pupils in my school.","why":"cent is multiplied by deux and nothing follows, so it takes -s: deux cents."},{"id":"numbers-dates-time-08","type":"gap","prompt":"Mon petit frère est né en ___.","hint":"(2010, in words)","answers":["deux mille dix","deux-mille-dix"],"en":"My little brother was born in 2010.","why":"Years are said as full numbers; mille never takes -s: deux mille dix."},{"id":"numbers-dates-time-09","type":"flip","front":"How do you form ordinal numbers (first, second...) and write dates?","back":"Add -ième to the number: deuxième, troisième, quatrième (drop the final -e), cinquième (add u), neuvième (f → v). First = premier / première. Dates use normal numbers except the 1st: le premier avril, le deux avril, le vingt et un avril."},{"id":"numbers-dates-time-10","type":"gap","prompt":"C'est la ___ fois que je viens en France.","base":"premier","answers":["première"],"en":"It's the first time I've come to France.","why":"premier is an adjective and agrees with the feminine noun fois: première."},{"id":"numbers-dates-time-11","type":"gap","prompt":"Mon anniversaire, c'est le ___ mai.","hint":"(1st, in words)","answers":["premier"],"en":"My birthday is on 1st May.","why":"The first of the month is the only date that uses the ordinal: le premier mai, but le deux mai."},{"id":"numbers-dates-time-12","type":"flip","front":"How do you say quarter past, half past, quarter to, and half past twelve?","back":"et quart, et demie, moins le quart: Il est trois heures et quart / et demie; Il est quatre heures moins le quart. After midi and minuit, demi has no -e: midi et demi, minuit et demi."},{"id":"numbers-dates-time-13","type":"gap","prompt":"Le cours de maths commence à neuf heures et ___.","hint":"(half past)","answers":["demie"],"en":"The maths lesson starts at half past nine.","why":"After heures, demi agrees with the feminine noun heure: et demie."},{"id":"numbers-dates-time-14","type":"gap","prompt":"Il est ___ heures moins le quart.","hint":"(it is 7:45; write the hour in words)","answers":["huit"],"en":"It's quarter to eight.","why":"moins le quart counts back from the next hour: 7:45 = huit heures moins le quart."},{"id":"numbers-dates-time-15","type":"transform","instruction":"Write the time in words, using the 24-hour clock.","prompt":"Le film commence à 20h30.","answers":["Le film commence à vingt heures trente."],"en":"The film starts at 20:30.","why":"With the 24-hour clock, say the minutes as a number (trente), not et demie."},{"id":"numbers-dates-time-16","type":"flip","front":"How do you say a kilo of, a bottle of, a packet of, a dozen, half of?","back":"un kilo de, une bouteille de, un paquet de, une douzaine de, la moitié de: un kilo de tomates, une bouteille d'eau, un paquet de biscuits, une douzaine d'œufs, la moitié du gâteau."},{"id":"numbers-dates-time-17","type":"gap","prompt":"Je voudrais un kilo ___ pommes, s'il vous plaît.","hint":"(of)","answers":["de"],"en":"I'd like a kilo of apples, please.","why":"After a quantity, use plain de, never des: un kilo de pommes."},{"id":"numbers-dates-time-18","type":"gap","prompt":"J'habite dans cette ville ___ trois ans.","hint":"(for; I still live here)","answers":["depuis"],"en":"I have lived in this town for three years.","why":"For something that started in the past and is still going on, use depuis + present tense."},{"id":"numbers-dates-time-19","type":"flip","front":"How do you use depuis with the present and with the imperfect?","back":"depuis + present = have been doing (and still are): J'attends depuis dix minutes (I have been waiting for ten minutes). depuis + imperfect = had been doing (when something else happened): J'attendais depuis dix minutes quand le bus est arrivé (I had been waiting for ten minutes when the bus arrived). Do not use the perfect or pluperfect for these sentences."},{"id":"numbers-dates-time-20","type":"gap","prompt":"Quand je suis arrivé à la gare, mes parents ___ depuis une heure.","base":"attendre","answers":["attendaient"],"en":"When I arrived at the station, my parents had been waiting for an hour.","why":"For something that had been going on when something else happened, use depuis + imperfect: ils attendaient (had been waiting)."}]}]};
